insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('5361cf37-c6de-510e-b896-884da81afa8c', 'A company posts signs at every entrance stating that the premises are monitored by video surveillance 24/7. Which control TYPE do the signs primarily represent?', 1, 'easy', 'single', 1, 'The signs are meant to discourage someone from attempting unauthorized activity in the first place. A control whose purpose is to discourage an attacker is a deterrent control.', 'If the control works by making an attacker think twice, it is a deterrent. If it records or alerts, it is detective.', 'Deter = discourage. Detect = discover.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('159f9efb-c5bb-51e7-ae94-41f64e581d6a', '5361cf37-c6de-510e-b896-884da81afa8c', 0, 'Deterrent', true, null),
  ('04dac7e8-6df4-5ccb-8bf8-d1f34df86382', '5361cf37-c6de-510e-b896-884da81afa8c', 1, 'Detective', false, 'The cameras recording activity would be detective; the signs themselves detect nothing.'),
  ('d24da226-fd67-5cb3-b3be-5e30c89d5864', '5361cf37-c6de-510e-b896-884da81afa8c', 2, 'Corrective', false, 'Corrective controls restore systems or fix problems after an incident, such as restoring from backup.'),
  ('68c34467-f7d3-5c76-834f-e516eab9e37e', '5361cf37-c6de-510e-b896-884da81afa8c', 3, 'Compensating', false, 'Compensating controls substitute for a primary control that cannot be implemented.')
insert into public.question_topics (question_id, topic_id) values ('5361cf37-c6de-510e-b896-884da81afa8c', 'security-controls'), ('5361cf37-c6de-510e-b896-884da81afa8c', 'physical-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('17272654-f3ea-5df9-a7b3-4195d948a112', 'An organization cannot patch a legacy controller because the vendor no longer supports it. The security team places the controller on an isolated network segment with strict access control lists until it can be replaced. Which control type BEST describes the isolation?', 1, 'medium', 'single', 1, 'Patching is the primary control, but it cannot be applied. Isolation is an alternative measure that reduces the same risk, which is the definition of a compensating control.', 'Look for the phrase ''cannot implement'' or ''not supported'' followed by an alternative safeguard: that is a compensating control.', 'Compensating = Plan B when Plan A is impossible.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('03e329f7-c5f2-5e1e-bfbe-4b899569dad6', '17272654-f3ea-5df9-a7b3-4195d948a112', 0, 'Directive', false, 'Directive controls instruct people what to do, such as a policy or a sign reading ''Authorized personnel only''.'),
  ('964c9a86-ea6f-53db-b8a9-3293e752ecf0', '17272654-f3ea-5df9-a7b3-4195d948a112', 1, 'Corrective', false, 'Corrective controls respond after an incident to fix or restore something.'),
  ('9c4e5e59-048c-5bd1-b2c1-543ffc90f282', '17272654-f3ea-5df9-a7b3-4195d948a112', 2, 'Compensating', true, null),
  ('034f3f5a-af14-57b1-a41a-d87cc929820b', '17272654-f3ea-5df9-a7b3-4195d948a112', 3, 'Deterrent', false, 'Deterrent controls discourage attackers; network isolation actively reduces exposure rather than discouraging.')
insert into public.question_topics (question_id, topic_id) values ('17272654-f3ea-5df9-a7b3-4195d948a112', 'security-controls'), ('17272654-f3ea-5df9-a7b3-4195d948a112', 'segmentation'), ('17272654-f3ea-5df9-a7b3-4195d948a112', 'iot-ics') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('7b38e62a-4b25-5f09-aece-b9e906933fbe', 'Which of the following is an example of a MANAGERIAL security control?', 1, 'easy', 'single', 1, 'Managerial (administrative) controls focus on managing risk and the security program: risk assessments, policies, and planning. A risk assessment is a managerial activity.', 'Managerial = decisions and oversight (policies, risk assessments). Technical = implemented by systems. Operational = performed by people day to day.', 'Managers assess and decide; technology enforces.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d02bddd1-d839-5ca0-8967-a3c0a872db75', '7b38e62a-4b25-5f09-aece-b9e906933fbe', 0, 'Configuring host-based firewall rules', false, 'Firewall rules are implemented in technology, so they are technical controls.'),
  ('e100ce92-3a13-5758-833c-edea70096f16', '7b38e62a-4b25-5f09-aece-b9e906933fbe', 1, 'Conducting an annual risk assessment', true, null),
  ('9939f5ec-ace7-5af4-b2ef-62350f957c15', '7b38e62a-4b25-5f09-aece-b9e906933fbe', 2, 'Installing locks on server room doors', false, 'Door locks are physical controls.'),
  ('77954594-0159-55ed-b24c-25b4097ec2be', '7b38e62a-4b25-5f09-aece-b9e906933fbe', 3, 'Deploying endpoint antivirus software', false, 'Antivirus software is a technical control.')
insert into public.question_topics (question_id, topic_id) values ('7b38e62a-4b25-5f09-aece-b9e906933fbe', 'security-controls'), ('7b38e62a-4b25-5f09-aece-b9e906933fbe', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ab9ca009-116d-54a7-9ea1-69c3288eae88', 'Which TWO of the following are detective controls?', 1, 'medium', 'multiple', 2, 'Detective controls identify and record events that are happening or have happened. Log reviews and IDS alerts both discover activity rather than stop it.', 'Ask: does this control stop, discourage, discover, or fix? ''Discover'' means detective.', 'Detective controls leave a trail: logs, alerts, cameras.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('9330f480-2158-5a7f-b7ed-991b70c798bd', 'ab9ca009-116d-54a7-9ea1-69c3288eae88', 0, 'Reviewing audit logs for suspicious activity', true, null),
  ('2bc96099-7bf9-5852-b578-6b022e12efcf', 'ab9ca009-116d-54a7-9ea1-69c3288eae88', 1, 'A firewall rule blocking inbound Telnet', false, 'Blocking traffic prevents an action, so the firewall rule is preventive.'),
  ('9403c914-07bd-52d7-a1bf-a6fcd9d54195', 'ab9ca009-116d-54a7-9ea1-69c3288eae88', 2, 'An intrusion detection system that generates alerts', true, null),
  ('b69fd492-3365-54ba-845e-7358017653b2', 'ab9ca009-116d-54a7-9ea1-69c3288eae88', 3, 'Restoring a server from backup after ransomware', false, 'Restoring from backup fixes the damage after an incident, which is corrective.'),
  ('63c8b2d5-2454-5958-ba56-1737b971e789', 'ab9ca009-116d-54a7-9ea1-69c3288eae88', 4, 'A login banner warning against unauthorized use', false, 'A warning banner discourages misuse; it is a deterrent (and directive) control.')
insert into public.question_topics (question_id, topic_id) values ('ab9ca009-116d-54a7-9ea1-69c3288eae88', 'security-controls'), ('ab9ca009-116d-54a7-9ea1-69c3288eae88', 'logging') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('6490a217-2e0d-56cf-bf3d-00da08c466bb', 'A hospital discovers that an unauthorized user modified several patient records, changing recorded medication doses. Which element of the CIA triad was MOST directly violated?', 1, 'easy', 'single', 1, 'Integrity means data is accurate and has not been altered without authorization. Changing medication doses is an unauthorized modification, so integrity was violated.', 'Altered, modified, tampered = integrity. Disclosed, leaked, viewed = confidentiality. Down, deleted, unreachable = availability.', 'Integrity = the data tells the truth.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('58957f55-38c9-5f25-b3c0-d608626a9b5e', '6490a217-2e0d-56cf-bf3d-00da08c466bb', 0, 'Confidentiality', false, 'Confidentiality concerns unauthorized disclosure. The scenario focuses on data being changed, not viewed.'),
  ('7f651023-77b5-541f-b9dd-39e7fdebb391', '6490a217-2e0d-56cf-bf3d-00da08c466bb', 1, 'Integrity', true, null),
  ('31f41cb4-3831-56de-9f97-6c4d0b287130', '6490a217-2e0d-56cf-bf3d-00da08c466bb', 2, 'Availability', false, 'Availability concerns whether authorized users can access data when needed; the records remained available.'),
  ('1c4bd835-3f3e-578f-a4b9-f95f8e9f4c30', '6490a217-2e0d-56cf-bf3d-00da08c466bb', 3, 'Non-repudiation', false, 'Non-repudiation is about proving who performed an action; it is not one of the three CIA elements.')
insert into public.question_topics (question_id, topic_id) values ('6490a217-2e0d-56cf-bf3d-00da08c466bb', 'cia-triad') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('0a06f075-5b61-52fe-804e-9fdb83fcd00e', 'After authenticating to the corporate VPN, a contractor can open only the file shares for the project they were hired to work on. Which part of the AAA framework enforces this restriction?', 1, 'easy', 'single', 1, 'Authorization determines what an authenticated identity is allowed to access. Limiting the contractor to specific shares is an authorization decision.', 'Who are you? = authentication. What can you do? = authorization. What did you do? = accounting.', 'AuthN proves identity; AuthZ grants permission.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('48a6f22d-77b4-5957-af54-b257feca9808', '0a06f075-5b61-52fe-804e-9fdb83fcd00e', 0, 'Authentication', false, 'Authentication proves who the contractor is; it happened when they logged in to the VPN.'),
  ('cefbcfd5-9d91-5525-bfc0-42e4beabeab2', '0a06f075-5b61-52fe-804e-9fdb83fcd00e', 1, 'Authorization', true, null),
  ('025757db-6b4a-51cf-9b45-a2e2282fc92b', '0a06f075-5b61-52fe-804e-9fdb83fcd00e', 2, 'Accounting', false, 'Accounting records what the contractor did, such as files accessed and session duration.'),
  ('21e90362-9775-5c39-84d0-5d037b657803', '0a06f075-5b61-52fe-804e-9fdb83fcd00e', 3, 'Attestation', false, 'Attestation is a formal confirmation (for example, reviewing that access is still appropriate); it is not part of AAA.')
insert into public.question_topics (question_id, topic_id) values ('0a06f075-5b61-52fe-804e-9fdb83fcd00e', 'aaa'), ('0a06f075-5b61-52fe-804e-9fdb83fcd00e', 'iam') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 'In a Zero Trust architecture, which component evaluates policy and decides whether a subject should be granted access to a resource?', 1, 'medium', 'single', 1, 'The policy engine, part of the policy decision point in the control plane, makes the grant/deny decision using identity, device, and context signals. The policy administrator then signals the enforcement point.', 'Engine decides, administrator communicates, enforcement point enforces.', 'The Engine thinks, the PEP blocks.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('eeb55699-f273-54a5-883e-d9724d9f39a3', '9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 0, 'Policy enforcement point', false, 'The policy enforcement point allows or blocks the connection based on the decision it receives; it does not make the decision.'),
  ('5d9b5dbf-821d-5eb6-a0c5-0ce7bc506f00', '9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 1, 'Policy engine', true, null),
  ('b2574ad5-afd2-5c16-b606-358765b3cace', '9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 2, 'Implicit trust zone', false, 'Zero Trust aims to eliminate implicit trust zones rather than rely on them to decide access.'),
  ('c69d7e82-a390-54af-ad65-2b36669002d4', '9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 3, 'Data plane', false, 'The data plane carries the actual traffic; decisions are made in the control plane.')
insert into public.question_topics (question_id, topic_id) values ('9c1b69d4-cfd0-5903-bea9-06eff2fb8f1e', 'zero-trust') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d99fa1ec-b0da-5995-b062-5ad4484f6885', 'A company is adopting Zero Trust. Today, any device plugged into the corporate LAN can reach the HR database once it has an IP address. Which change BEST aligns with Zero Trust principles?', 1, 'hard', 'single', 1, 'Zero Trust removes implicit trust based on network location. Every request is verified explicitly using identity, device posture, and context, and access is granted with least privilege.', 'When the problem is ''being on the network grants access'', the Zero Trust answer verifies every request explicitly.', 'Zero Trust: never trust the network, always verify the request.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('145d2705-22ed-542c-a8fe-3b92980c715e', 'd99fa1ec-b0da-5995-b062-5ad4484f6885', 0, 'Add a second firewall at the internet edge', false, 'A second perimeter firewall reinforces the old ''trusted inside'' model and does nothing about internal devices.'),
  ('c419bb7e-6f7c-510b-9b51-0973cf114f56', 'd99fa1ec-b0da-5995-b062-5ad4484f6885', 1, 'Move the HR database into the screened subnet', false, 'A screened subnet exposes services to external networks; it would increase risk to HR data.'),
  ('54020744-4e2d-54f1-88fb-3a930c22f28e', 'd99fa1ec-b0da-5995-b062-5ad4484f6885', 2, 'Require per-session authentication and authorization based on user identity, device health, and context before any access to the HR database', true, null),
  ('00d46279-eff6-507a-a811-fa8998fa1959', 'd99fa1ec-b0da-5995-b062-5ad4484f6885', 3, 'Allow all employees read-only access to the HR database and log every query', false, 'Granting broad read access violates least privilege; logging is detective, not an access decision.')
insert into public.question_topics (question_id, topic_id) values ('d99fa1ec-b0da-5995-b062-5ad4484f6885', 'zero-trust'), ('d99fa1ec-b0da-5995-b062-5ad4484f6885', 'segmentation'), ('d99fa1ec-b0da-5995-b062-5ad4484f6885', 'iam') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 'A security team places a fake spreadsheet named ''executive_salaries_2026.xlsx'' on a file server. No legitimate user needs it, so any access immediately triggers an alert. What is this file?', 1, 'easy', 'single', 1, 'A honeyfile is a decoy file that looks valuable. Because no one should open it, any access is a high-fidelity signal of unauthorized activity.', 'Honey + the object: honeyfile (file), honeytoken (fake credential or data), honeypot (system), honeynet (network).', 'Nobody should touch it, so anyone who does is suspicious.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('2fd81818-e9f8-567b-8797-a7543be26faf', 'dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 0, 'Honeypot', false, 'A honeypot is an entire decoy system, not a single file.'),
  ('1798a741-1bb6-528f-ac0e-d39c9c7d6c40', 'dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 1, 'Honeyfile', true, null),
  ('ab9e7c76-9548-5b4e-8b0e-1e9b141d0e55', 'dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 2, 'Honeynet', false, 'A honeynet is a network of decoy systems.'),
  ('9fb8286a-18af-52eb-bb08-97967c63c7a2', 'dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 3, 'DNS sinkhole', false, 'A DNS sinkhole redirects malicious domain lookups to a controlled address.')
insert into public.question_topics (question_id, topic_id) values ('dccd502e-c6e4-5d05-a8e0-a21bceaf2fd3', 'deception') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d4e0abb1-0f9d-5381-9af6-6971feb93476', 'Before a major firewall configuration change, which change management document describes how to return to the previous configuration if the change causes an outage?', 1, 'medium', 'single', 1, 'A backout plan documents the steps to reverse a change and restore the prior state if something goes wrong.', 'Undo, roll back, revert = backout plan.', 'Always know the way back before you walk through the door.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('abf53d82-9780-5b56-82a7-3a0414f64f41', 'd4e0abb1-0f9d-5381-9af6-6971feb93476', 0, 'Impact analysis', false, 'Impact analysis predicts what a change will affect before approval; it does not describe how to undo it.'),
  ('2a6a540b-851a-5b88-9bda-fd31a72fa9f2', 'd4e0abb1-0f9d-5381-9af6-6971feb93476', 1, 'Backout plan', true, null),
  ('87c9977d-bb27-5829-8c76-41d350246aff', 'd4e0abb1-0f9d-5381-9af6-6971feb93476', 2, 'Standard operating procedure', false, 'An SOP describes routine, repeatable tasks rather than the rollback for a specific change.'),
  ('95703a5c-d27a-54d8-898b-87b5df313565', 'd4e0abb1-0f9d-5381-9af6-6971feb93476', 3, 'Maintenance window', false, 'A maintenance window is the approved time to implement a change.')
insert into public.question_topics (question_id, topic_id) values ('d4e0abb1-0f9d-5381-9af6-6971feb93476', 'change-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d147dd25-cade-5a8d-82be-94d400f4798d', 'An administrator applies a vendor patch to a production web server. The patch unexpectedly requires a database schema update, and the application fails for an hour. Which change management step would have MOST likely identified this requirement BEFORE implementation?', 1, 'medium', 'single', 1, 'Impact analysis evaluates what systems, dependencies, and downtime a change will involve before it is approved. It would have revealed the database dependency ahead of time.', '''Before implementation'' + ''identify effects/dependencies'' points to impact analysis.', 'Impact analysis asks ''what could this break?'' before you break it.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f40f58d6-f745-5a73-b9e3-23aab235c9f1', 'd147dd25-cade-5a8d-82be-94d400f4798d', 0, 'Impact analysis', true, null),
  ('e2b6b51e-54e2-55ee-85bf-1a35a9f47a37', 'd147dd25-cade-5a8d-82be-94d400f4798d', 1, 'Backout plan', false, 'A backout plan helps recover after a failure but does not identify dependencies in advance.'),
  ('917a80aa-3583-52e7-862f-06e4323c9a5e', 'd147dd25-cade-5a8d-82be-94d400f4798d', 2, 'Version control', false, 'Version control tracks changes to code and configurations; it does not predict a patch''s side effects.'),
  ('e7751873-413e-5c6b-a3c9-92ff5e3aee2f', 'd147dd25-cade-5a8d-82be-94d400f4798d', 3, 'Updating the allow list', false, 'Allow lists control which software may run; they are unrelated to discovering patch dependencies.')
insert into public.question_topics (question_id, topic_id) values ('d147dd25-cade-5a8d-82be-94d400f4798d', 'change-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 'Which PKI mechanism lets a client check the revocation status of a single certificate in real time?', 1, 'easy', 'single', 1, 'OCSP lets a client query a responder about one specific certificate and receive a current good, revoked, or unknown status.', 'Real-time status of one certificate = OCSP. Downloadable list = CRL.', 'OCSP = Online, one certificate, right now.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('2f79bcb0-4e5d-5c46-98d1-83fe822c5090', 'f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 0, 'Certificate revocation list (CRL)', false, 'A CRL is a periodically published list of all revoked certificates; it can be stale between updates.'),
  ('e49ed34b-6f7a-5b08-8d85-5ce95f46e3f5', 'f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 1, 'Online Certificate Status Protocol (OCSP)', true, null),
  ('9f1ed8ab-4a10-5b17-8c1b-7499753fde6b', 'f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 2, 'Certificate signing request (CSR)', false, 'A CSR is the request sent to a CA to obtain a certificate.'),
  ('4acebe75-eb6e-5bc9-aff9-c8deb86e03cb', 'f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 3, 'Key escrow', false, 'Key escrow stores copies of keys with a trusted third party for recovery.')
insert into public.question_topics (question_id, topic_id) values ('f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 'pki'), ('f8387e25-b79c-5c9b-9f57-d17bfdcd76ea', 'certificates') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('5e2a262d-e54f-5b71-9c32-1ac26d058d06', 'A company needs one certificate that secures www.example.com, mail.example.com, and shop.example.com, but it must NOT be valid for any other subdomain. Which option BEST meets this requirement?', 1, 'medium', 'single', 1, 'A SAN (multi-domain) certificate lists exactly which names it is valid for, so it covers the three hosts and nothing else.', 'Specific list of names = SAN. Any subdomain = wildcard.', 'SAN = Specific, Approved Names.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('1c8ab51b-9011-5cc0-808b-48376021513c', '5e2a262d-e54f-5b71-9c32-1ac26d058d06', 0, 'A wildcard certificate for *.example.com', false, 'A wildcard covers every first-level subdomain, which violates the requirement to exclude other subdomains.'),
  ('690cfaf9-7250-5b4c-98c4-fe694bb178d4', '5e2a262d-e54f-5b71-9c32-1ac26d058d06', 1, 'A certificate with each hostname listed as a Subject Alternative Name', true, null),
  ('3cc99011-8c8e-527b-822f-d021693f3f47', '5e2a262d-e54f-5b71-9c32-1ac26d058d06', 2, 'A self-signed root certificate', false, 'A self-signed root is not trusted by clients and is not a way to scope hostnames.'),
  ('35848c04-5caa-56fc-9883-2eec41259327', '5e2a262d-e54f-5b71-9c32-1ac26d058d06', 3, 'A code-signing certificate', false, 'Code-signing certificates validate software publishers, not web server hostnames.')
insert into public.question_topics (question_id, topic_id) values ('5e2a262d-e54f-5b71-9c32-1ac26d058d06', 'certificates'), ('5e2a262d-e54f-5b71-9c32-1ac26d058d06', 'pki') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('782d861c-81c8-5fb7-b3e0-e494cddb3996', 'Users see browser warnings when visiting an internal web application. The server''s certificate is unexpired, matches the hostname, and was issued by the company''s internal certificate authority. What is the MOST likely cause?', 1, 'hard', 'single', 1, 'Browsers trust a certificate only if its chain leads to a root in the device''s trust store. An internal CA''s root must be distributed (for example, through group policy or MDM) or every certificate it issues will be flagged.', 'Valid, unexpired, correct name but still untrusted? Suspect the chain of trust or a missing root.', 'No trusted root, no trusted route.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('bd7f4ce4-3a02-5d42-a0c6-98cc10e0b246', '782d861c-81c8-5fb7-b3e0-e494cddb3996', 0, 'The certificate uses a key length that is too long', false, 'Longer keys are stronger and do not cause trust errors.'),
  ('647e1c8e-d889-5e41-91af-6955066937f0', '782d861c-81c8-5fb7-b3e0-e494cddb3996', 1, 'The internal root CA certificate is not in the users'' trusted root store', true, null),
  ('2cf23a9e-e35c-5fa5-9350-9bd6c4865f42', '782d861c-81c8-5fb7-b3e0-e494cddb3996', 2, 'OCSP stapling is enabled on the web server', false, 'OCSP stapling improves revocation checking performance; it does not cause trust warnings.'),
  ('918a68c4-d96f-561c-a7da-86ec122280c4', '782d861c-81c8-5fb7-b3e0-e494cddb3996', 3, 'The site negotiates TLS 1.3', false, 'TLS 1.3 is the current, preferred protocol version.')
insert into public.question_topics (question_id, topic_id) values ('782d861c-81c8-5fb7-b3e0-e494cddb3996', 'pki'), ('782d861c-81c8-5fb7-b3e0-e494cddb3996', 'certificates') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('99f62ec2-58a5-56c7-a411-721dfe3c8e06', 'Which technique BEST verifies that a file downloaded from a vendor''s website has not been altered?', 1, 'easy', 'single', 1, 'A hash is a fixed-length fingerprint. If even one bit of the file changes, the hash changes, so matching the published hash confirms integrity.', 'Integrity check of a file or message = hashing.', 'Hashing = integrity. Encryption = confidentiality.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('70b60d5a-ea5e-5e5a-bc3a-71aff232a7d1', '99f62ec2-58a5-56c7-a411-721dfe3c8e06', 0, 'Comparing the file''s hash to the value published by the vendor', true, null),
  ('8fb6de86-138d-52ef-b220-78d378be5f3b', '99f62ec2-58a5-56c7-a411-721dfe3c8e06', 1, 'Encrypting the file with AES-256', false, 'Encryption protects confidentiality; it does not tell you whether the file was modified before you received it.'),
  ('f8056219-4a6a-51bd-b11c-fdf87f73a0bc', '99f62ec2-58a5-56c7-a411-721dfe3c8e06', 2, 'Hiding the file inside an image using steganography', false, 'Steganography hides data; it does not verify integrity.'),
  ('7824cba5-5d5e-5610-a21e-90bcc3836080', '99f62ec2-58a5-56c7-a411-721dfe3c8e06', 3, 'Tokenizing the file''s contents', false, 'Tokenization replaces sensitive values with surrogates; it does not verify files.')
insert into public.question_topics (question_id, topic_id) values ('99f62ec2-58a5-56c7-a411-721dfe3c8e06', 'hashing'), ('99f62ec2-58a5-56c7-a411-721dfe3c8e06', 'cia-triad') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 'Why is a unique salt added to each password before it is hashed?', 1, 'medium', 'single', 1, 'A salt is random data combined with the password before hashing. Two users with the same password get different hashes, and attackers cannot use precomputed tables of password hashes.', 'Rainbow table defense = salt. Slowing brute force = key stretching (bcrypt, PBKDF2).', 'Salt makes every hash its own recipe.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('55cdffa9-d25a-566d-a8b1-f2417413573f', '51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 0, 'So the hash can be reversed if the user forgets the password', false, 'Hashes are one-way; salting does not make them reversible.'),
  ('6bf4ba3c-4c34-5057-b82b-ea7dd52edf19', '51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 1, 'So identical passwords produce different hashes, defeating precomputed rainbow tables', true, null),
  ('7f219012-8d0c-5554-bf38-06318fa304f7', '51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 2, 'So the password is encrypted while in transit', false, 'Protecting passwords in transit is the job of TLS, not salting.'),
  ('3a3c7d4c-2f9b-57c2-af26-50fac53b5def', '51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 3, 'So the stored hash takes less space', false, 'Salts slightly increase stored data; they do not shrink hashes.')
insert into public.question_topics (question_id, topic_id) values ('51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 'hashing'), ('51a94fbb-88d5-5e07-9d52-082e2f4f1cb0', 'password-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ecd7719c-3d0b-5ac5-84ed-07222a873b73', 'Alice digitally signs a contract before emailing it to Bob. Which key does Bob use to verify that the signature is valid?', 1, 'medium', 'single', 1, 'Alice signs with her private key, which only she holds. Anyone can verify the signature with Alice''s public key, which proves the message came from her and was not altered.', 'Sign with the sender''s private key; verify with the sender''s public key. Encrypt with the recipient''s public key.', 'Signatures: private to sign, public to verify.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d3cc6336-d307-5ae9-8cb3-83a763f48254', 'ecd7719c-3d0b-5ac5-84ed-07222a873b73', 0, 'Alice''s private key', false, 'Alice''s private key creates the signature and must never be shared.'),
  ('45f066c0-2398-5646-97f2-aaa42efe1ab2', 'ecd7719c-3d0b-5ac5-84ed-07222a873b73', 1, 'Alice''s public key', true, null),
  ('04b317d2-fc70-51c1-9e14-3718f71d6262', 'ecd7719c-3d0b-5ac5-84ed-07222a873b73', 2, 'Bob''s private key', false, 'Bob''s private key would be used to decrypt messages encrypted to Bob, not to verify Alice''s signature.'),
  ('fd077e9e-db2a-5648-83e2-b7d030bd1253', 'ecd7719c-3d0b-5ac5-84ed-07222a873b73', 3, 'Bob''s public key', false, 'Bob''s public key is used to encrypt data for Bob.')
insert into public.question_topics (question_id, topic_id) values ('ecd7719c-3d0b-5ac5-84ed-07222a873b73', 'digital-signatures'), ('ecd7719c-3d0b-5ac5-84ed-07222a873b73', 'encryption') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 'Which TWO security properties does a digital signature provide?', 1, 'medium', 'multiple', 2, 'A digital signature is a hash encrypted with the signer''s private key. Verifying it proves the content was not altered (integrity) and that only the private-key holder could have signed it (non-repudiation and authentication).', 'Signature = integrity + authenticity + non-repudiation. It does NOT provide confidentiality.', 'A signature proves who and what, not secrecy.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('9609a7b7-6d24-5fd1-8be3-7c2d6f2dca5c', 'dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 0, 'Integrity', true, null),
  ('5eb913e1-aee3-51dc-a14c-f5469dcc6a3d', 'dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 1, 'Confidentiality', false, 'Signing does not hide the message; anyone can still read it.'),
  ('eb29074f-8c4a-50e2-abb9-b548e449ec37', 'dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 2, 'Non-repudiation', true, null),
  ('6ac39bae-da7d-51e9-a8fc-b770b60f0c00', 'dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 3, 'Availability', false, 'Signatures do nothing to keep a system available.'),
  ('51020e4a-7cb3-56d0-bb9c-7badde91f9b3', 'dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 4, 'Obfuscation', false, 'Obfuscation makes data harder to understand; signatures do not do this.')
insert into public.question_topics (question_id, topic_id) values ('dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 'digital-signatures'), ('dbfbace7-a3a0-5f6b-a719-e331b760ef7a', 'cia-triad') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('cd331caf-14a7-5480-b6bb-9b2a56a76a76', 'Which type of encryption uses the same key to both encrypt and decrypt data?', 1, 'easy', 'single', 1, 'Symmetric algorithms such as AES use one shared secret key. They are fast and ideal for bulk data, but the key must be shared securely.', 'One shared key = symmetric. Key pair = asymmetric.', 'Symmetric = same key on both sides.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('087b34a8-9915-5db7-8d2d-ec58b0192373', 'cd331caf-14a7-5480-b6bb-9b2a56a76a76', 0, 'Symmetric encryption', true, null),
  ('8e40deea-f99c-5286-8ea8-072fde0546df', 'cd331caf-14a7-5480-b6bb-9b2a56a76a76', 1, 'Asymmetric encryption', false, 'Asymmetric encryption uses a mathematically related public and private key pair.'),
  ('1a3129b7-7bb7-593e-9ee6-4bb87581e7ee', 'cd331caf-14a7-5480-b6bb-9b2a56a76a76', 2, 'Hashing', false, 'Hashing is one-way and uses no decryption key.'),
  ('9a197660-cabb-5d64-9432-0c63687e5963', 'cd331caf-14a7-5480-b6bb-9b2a56a76a76', 3, 'Key stretching', false, 'Key stretching strengthens weak secrets such as passwords; it is not an encryption method.')
insert into public.question_topics (question_id, topic_id) values ('cd331caf-14a7-5480-b6bb-9b2a56a76a76', 'encryption') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e453c9f4-8bbd-575e-b58c-0cec11751929', 'A company sends large daily database exports to a partner over the internet. It needs fast bulk encryption but does not want to send a shared secret key over an insecure channel. Which approach BEST meets both requirements?', 1, 'hard', 'single', 1, 'Hybrid encryption combines both strengths: asymmetric cryptography safely exchanges a symmetric key, and the symmetric algorithm encrypts the large data quickly. TLS works the same way.', 'Need speed AND safe key exchange? The answer is hybrid: asymmetric for the key, symmetric for the data.', 'Asymmetric delivers the key; symmetric does the heavy lifting.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('de697211-d50a-51d0-9f74-24a53070c12d', 'e453c9f4-8bbd-575e-b58c-0cec11751929', 0, 'Encrypt the entire export with the partner''s RSA public key', false, 'RSA is slow and limited in how much data it can encrypt directly, so it is impractical for large exports.'),
  ('77ba393b-f80a-5f6b-a477-c20c211f7696', 'e453c9f4-8bbd-575e-b58c-0cec11751929', 1, 'Hash the export with SHA-256 before sending it', false, 'Hashing provides integrity only; the data would still be readable.'),
  ('486aa364-4780-55b1-b218-aaacff86a9ae', 'e453c9f4-8bbd-575e-b58c-0cec11751929', 2, 'Use asymmetric encryption to exchange a symmetric session key, then encrypt the export with that symmetric key', true, null),
  ('7bc5624c-731e-5b9f-a380-59b3c51ef751', 'e453c9f4-8bbd-575e-b58c-0cec11751929', 3, 'Email the AES key to the partner in a separate message', false, 'Emailing the key sends the secret over the same insecure channel the company wants to avoid.')
insert into public.question_topics (question_id, topic_id) values ('e453c9f4-8bbd-575e-b58c-0cec11751929', 'encryption'), ('e453c9f4-8bbd-575e-b58c-0cec11751929', 'key-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9d327afb-84b2-574b-9456-6b3e115789aa', 'Which hardware component is built into a laptop''s motherboard and securely stores keys used for full-disk encryption and boot integrity measurements?', 1, 'medium', 'single', 1, 'A TPM is a chip on the motherboard that stores keys, measures the boot process, and releases disk-encryption keys only if the system has not been tampered with.', 'On the device''s motherboard = TPM. Dedicated enterprise appliance = HSM.', 'TPM lives in the laptop; HSM lives in the data center.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f0ad4b92-d581-50b3-8478-c1723349cc50', '9d327afb-84b2-574b-9456-6b3e115789aa', 0, 'Hardware security module (HSM)', false, 'An HSM is a dedicated appliance or card used by servers for high-volume key operations, not a laptop motherboard chip.'),
  ('49cb7842-64bb-5e27-8923-6d67dbcb8212', '9d327afb-84b2-574b-9456-6b3e115789aa', 1, 'Trusted Platform Module (TPM)', true, null),
  ('86a6e184-e8ad-5496-a050-0d7e9c838c32', '9d327afb-84b2-574b-9456-6b3e115789aa', 2, 'Cloud key management service (KMS)', false, 'A cloud KMS manages keys in a provider''s environment rather than on the device.'),
  ('21e909d4-d8cc-56a7-b5d8-2037b567d7c5', '9d327afb-84b2-574b-9456-6b3e115789aa', 3, 'Smart card', false, 'A smart card is a removable credential carried by the user.')
insert into public.question_topics (question_id, topic_id) values ('9d327afb-84b2-574b-9456-6b3e115789aa', 'key-management'), ('9d327afb-84b2-574b-9456-6b3e115789aa', 'encryption'), ('9d327afb-84b2-574b-9456-6b3e115789aa', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d5d77967-ad50-5d29-99f7-d8661fc6bb1b', 'A payment processor replaces stored card numbers with random values. The random values can be mapped back to real card numbers only through a secured vault. Which technique is this?', 1, 'medium', 'single', 1, 'Tokenization substitutes sensitive data with a non-sensitive token, and only the protected token vault can map it back. Systems that store only tokens hold nothing useful if breached.', 'Replaced with a surrogate + a vault that maps back = tokenization.', 'A token is a claim ticket; the vault holds the real item.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('309328da-8d66-53f5-a81d-b11622c58141', 'd5d77967-ad50-5d29-99f7-d8661fc6bb1b', 0, 'Data masking', false, 'Masking hides part of the value (such as showing only the last four digits) and is not designed to be reversed through a vault.'),
  ('c7c518d1-f92e-5c54-bf69-cbfc602662d4', 'd5d77967-ad50-5d29-99f7-d8661fc6bb1b', 1, 'Tokenization', true, null),
  ('4fb94e92-6c2e-5c87-a851-19b781cc17b9', 'd5d77967-ad50-5d29-99f7-d8661fc6bb1b', 2, 'Hashing', false, 'Hashing is one-way; the original number could not be retrieved for processing.'),
  ('ff7594f7-2bb0-5d1a-8c04-d709eda7df68', 'd5d77967-ad50-5d29-99f7-d8661fc6bb1b', 3, 'Steganography', false, 'Steganography hides data inside other media such as images.')
insert into public.question_topics (question_id, topic_id) values ('d5d77967-ad50-5d29-99f7-d8661fc6bb1b', 'obfuscation'), ('d5d77967-ad50-5d29-99f7-d8661fc6bb1b', 'data-protection'), ('d5d77967-ad50-5d29-99f7-d8661fc6bb1b', 'compliance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b63130be-97ce-5a7e-a093-93c71ca33ec3', 'A data center wants to stop tailgating by ensuring only one person enters at a time. The inner door must not open until the outer door has closed and the person is verified. What should be installed?', 1, 'medium', 'single', 1, 'An access control vestibule (mantrap) uses two interlocking doors so only one person can pass after verification, which prevents tailgating and piggybacking.', 'Two doors, one person at a time = access control vestibule.', 'Vestibule = a small room that lets only one person through.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('63fad60f-3ee9-5b74-8b20-227619a4c387', 'b63130be-97ce-5a7e-a093-93c71ca33ec3', 0, 'Bollards', false, 'Bollards stop vehicles, not people following each other through a door.'),
  ('2d6ff393-2f61-5b64-9f0b-88585ac40d5b', 'b63130be-97ce-5a7e-a093-93c71ca33ec3', 1, 'An access control vestibule', true, null),
  ('bbec95c7-dbf1-5089-a8ea-0cd2e144ee32', 'b63130be-97ce-5a7e-a093-93c71ca33ec3', 2, 'Motion-activated lighting', false, 'Lighting deters and aids detection but does not control entry.'),
  ('1bd1afdb-154f-519d-8e9f-0b563fc2d6df', 'b63130be-97ce-5a7e-a093-93c71ca33ec3', 3, 'A badge reader on the outer door only', false, 'A single badge reader still lets a second person slip through behind the first.')
insert into public.question_topics (question_id, topic_id) values ('b63130be-97ce-5a7e-a093-93c71ca33ec3', 'physical-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('16543ce8-88c0-5399-bae7-23ae7310d885', 'Which threat actor is MOST likely to be motivated primarily by a political or social cause?', 2, 'easy', 'single', 1, 'Hacktivists attack to promote a political, social, or ideological message, often through defacement, leaks, or DDoS.', 'Ideology or a cause = hacktivist. Money = organized crime. Espionage = nation-state.', 'Hacktivist = hacker + activist.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f7a38bb3-7791-5ba3-9f20-d02f506f6af7', '16543ce8-88c0-5399-bae7-23ae7310d885', 0, 'Organized crime group', false, 'Organized crime is motivated mainly by financial gain.'),
  ('5e9c8688-ed6e-5651-b7f8-824b6143e84a', '16543ce8-88c0-5399-bae7-23ae7310d885', 1, 'Hacktivist', true, null),
  ('fe6b31bf-bb14-5782-add9-c60fe0045972', '16543ce8-88c0-5399-bae7-23ae7310d885', 2, 'Unskilled attacker', false, 'Unskilled attackers use existing tools, often for curiosity or notoriety, without a defined cause.'),
  ('9304d953-796d-53b8-be2c-c8a6123ad6f8', '16543ce8-88c0-5399-bae7-23ae7310d885', 3, 'Shadow IT user', false, 'Shadow IT is well-meaning employees using unapproved technology, not an attacker with a cause.')
insert into public.question_topics (question_id, topic_id) values ('16543ce8-88c0-5399-bae7-23ae7310d885', 'threat-actors') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 'An attacker maintains undetected access to a defense contractor''s network for 18 months, using custom malware to slowly exfiltrate engineering designs. Which threat actor is MOST likely responsible?', 2, 'medium', 'single', 1, 'Long-term stealthy access, custom tooling, and theft of strategic intellectual property are hallmarks of an advanced persistent threat, typically sponsored by a nation-state.', 'Persistent + sophisticated + espionage = APT, usually a nation-state.', 'APT: Advanced, Persistent, and paid for by a Treasury.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ad86ef15-9982-53a8-8400-5d1cc53ca763', 'bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 0, 'Unskilled attacker', false, 'Unskilled attackers lack the resources to build custom malware and stay hidden for months.'),
  ('db7807c1-d91e-53e1-bde1-157dd47985c6', 'bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 1, 'Hacktivist', false, 'Hacktivists usually want visibility for a cause rather than quiet, long-term espionage.'),
  ('b3da451a-d84b-5951-9ac2-724d528e547b', 'bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 2, 'Nation-state', true, null),
  ('c2376a6a-11c0-5706-8f40-7e16d8178027', 'bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 3, 'Disgruntled insider', false, 'An insider could steal data, but custom malware with persistent external access points to a well-resourced outside actor.')
insert into public.question_topics (question_id, topic_id) values ('bdeb9d73-ae39-5715-bbe7-e0a03edfab63', 'threat-actors') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('714fe297-cccc-547b-a18f-4d526d9e9ce5', 'An employee installs an unapproved cloud file-sharing app to collaborate faster with a vendor, bypassing IT''s review process. What is this called?', 2, 'easy', 'single', 1, 'Shadow IT is technology used without the knowledge or approval of the IT or security team. It is usually well-intentioned but creates unmanaged risk.', 'Unapproved app or service used to get work done = shadow IT.', 'Shadow IT lives outside IT''s light.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7869030a-cb4e-5fae-90b3-91e4b39afabb', '714fe297-cccc-547b-a18f-4d526d9e9ce5', 0, 'Insider threat', false, 'An insider threat intends harm or causes it negligently; here the key point is unapproved technology.'),
  ('9e3b739c-d76f-5160-809d-26eabee4a9f2', '714fe297-cccc-547b-a18f-4d526d9e9ce5', 1, 'Shadow IT', true, null),
  ('eff0b2e4-a8e8-5be8-a5dc-4b6c50142008', '714fe297-cccc-547b-a18f-4d526d9e9ce5', 2, 'Supply chain attack', false, 'A supply chain attack compromises a vendor or product to reach its customers.'),
  ('d98f7fea-b56e-536b-bad5-223a243dec68', '714fe297-cccc-547b-a18f-4d526d9e9ce5', 3, 'Watering hole attack', false, 'A watering hole attack compromises a website frequented by the targets.')
insert into public.question_topics (question_id, topic_id) values ('714fe297-cccc-547b-a18f-4d526d9e9ce5', 'threat-actors'), ('714fe297-cccc-547b-a18f-4d526d9e9ce5', 'governance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('cfabf397-7bf1-5685-9b53-153cca47760a', 'Users receive text messages that claim to be from their bank and ask them to ''verify'' their account by tapping a link. Which attack is this?', 2, 'easy', 'single', 1, 'Smishing is phishing delivered by SMS text message.', 'SMS = smishing, voice = vishing, executives = whaling.', 'Smishing = SMS phishing.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('4c7e3da1-bbd0-55fe-80f6-e2fc2c5eae4c', 'cfabf397-7bf1-5685-9b53-153cca47760a', 0, 'Vishing', false, 'Vishing is voice phishing over a phone call.'),
  ('3ad53d0b-bb7a-5556-9f29-c633a824640d', 'cfabf397-7bf1-5685-9b53-153cca47760a', 1, 'Smishing', true, null),
  ('a02338f5-1b04-5b25-87b1-d08a88bc2551', 'cfabf397-7bf1-5685-9b53-153cca47760a', 2, 'Whaling', false, 'Whaling targets senior executives specifically.'),
  ('7dbf6f35-963c-5a31-9010-9584dcca2265', 'cfabf397-7bf1-5685-9b53-153cca47760a', 3, 'Pharming', false, 'Pharming redirects users from a legitimate site to a fraudulent one, often by poisoning DNS.')
insert into public.question_topics (question_id, topic_id) values ('cfabf397-7bf1-5685-9b53-153cca47760a', 'social-engineering') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('624b1818-cef9-5f24-bd81-20697e4211af', 'Several employees of a law firm visit a regional legal-industry forum. An attacker compromised the forum to deliver malware to its visitors. Which attack is this?', 2, 'medium', 'single', 1, 'A watering hole attack compromises a site the target group is known to visit, then waits for victims to come to it.', 'Attacker poisons a site the victims already trust and visit = watering hole.', 'Predators wait at the watering hole where the prey drinks.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7f9b9706-d662-50f6-aaf2-2f6250b20a41', '624b1818-cef9-5f24-bd81-20697e4211af', 0, 'Typosquatting', false, 'Typosquatting relies on users mistyping a domain name.'),
  ('4005d3be-b888-5644-b130-f47094b5bc13', '624b1818-cef9-5f24-bd81-20697e4211af', 1, 'Spear phishing', false, 'Spear phishing sends targeted messages directly to victims.'),
  ('52653e10-ea9f-59c4-bad3-8735b2c44f18', '624b1818-cef9-5f24-bd81-20697e4211af', 2, 'Watering hole attack', true, null),
  ('8730a45c-b1c3-53d5-98fd-eec6f2c2df8b', '624b1818-cef9-5f24-bd81-20697e4211af', 3, 'Pretexting', false, 'Pretexting uses a fabricated scenario to persuade someone to share information.')
insert into public.question_topics (question_id, topic_id) values ('624b1818-cef9-5f24-bd81-20697e4211af', 'social-engineering'), ('624b1818-cef9-5f24-bd81-20697e4211af', 'attack-vectors') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('212c1a45-9121-5d97-8d19-e72ac616bbed', 'Accounts payable receives an email sent from a long-time supplier''s real mailbox, which an attacker has taken over. It asks that all future invoices be paid to a new bank account. Which control would MOST effectively prevent the fraudulent payment?', 2, 'hard', 'single', 1, 'This is business email compromise sent from a legitimate, compromised account, so it passes technical checks. A process control that verifies payment changes through a separate, trusted channel stops the fraud.', 'When the email is from a real but compromised account, technical email authentication passes. Look for a verification procedure.', 'Money changes? Pick up the phone, not the reply button.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('556fdbfd-f2d4-598e-bb3b-9ebdd3725895', '212c1a45-9121-5d97-8d19-e72ac616bbed', 0, 'Enforcing SPF, DKIM, and DMARC on inbound email', false, 'The message genuinely comes from the supplier''s domain, so SPF, DKIM, and DMARC would all pass.'),
  ('ddd5e3ac-6d4b-5ab9-b9bd-d6b8e35688b4', '212c1a45-9121-5d97-8d19-e72ac616bbed', 1, 'Verifying bank detail changes through an out-of-band call to a known supplier phone number', true, null),
  ('bf6e8c87-9d1f-5406-8db9-65f62719003c', '212c1a45-9121-5d97-8d19-e72ac616bbed', 2, 'Scanning all email attachments for malware', false, 'The request contains no malicious attachment; it simply asks for a change in banking details.'),
  ('45b5bebb-96c1-56c6-82c7-0d762018d6f2', '212c1a45-9121-5d97-8d19-e72ac616bbed', 3, 'Increasing password complexity for accounts payable staff', false, 'The attacker compromised the supplier''s mailbox, not the company''s accounts, so internal password rules do not help.')
insert into public.question_topics (question_id, topic_id) values ('212c1a45-9121-5d97-8d19-e72ac616bbed', 'social-engineering'), ('212c1a45-9121-5d97-8d19-e72ac616bbed', 'email-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('2fd50a08-4818-58b3-85c5-024a82e28a9f', 'An attacker registers the domain ''rnicrosoft.com'', hoping users will misread or mistype the real company name. What is this technique called?', 2, 'easy', 'single', 1, 'Typosquatting (URL hijacking) registers look-alike domains that exploit typos or visual confusion (''rn'' looks like ''m'').', 'Look-alike or misspelled domain = typosquatting.', 'One typo away from trouble.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('aeabed19-779a-5d5e-a81b-3a03169eccf9', '2fd50a08-4818-58b3-85c5-024a82e28a9f', 0, 'DNS cache poisoning', false, 'DNS cache poisoning corrupts resolver records so a real domain resolves to a malicious address.'),
  ('a6bfa94c-d1fc-50e3-8eb8-18d48b63c0f2', '2fd50a08-4818-58b3-85c5-024a82e28a9f', 1, 'Typosquatting', true, null),
  ('65dd0f9d-d33b-580e-9b50-56afc9213536', '2fd50a08-4818-58b3-85c5-024a82e28a9f', 2, 'Domain hijacking', false, 'Domain hijacking takes control of the legitimate domain''s registration.'),
  ('50b3ebea-ee84-5498-9547-92f4a8969310', '2fd50a08-4818-58b3-85c5-024a82e28a9f', 3, 'Watering hole attack', false, 'A watering hole compromises a site the target already visits.')
insert into public.question_topics (question_id, topic_id) values ('2fd50a08-4818-58b3-85c5-024a82e28a9f', 'social-engineering'), ('2fd50a08-4818-58b3-85c5-024a82e28a9f', 'attack-vectors') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 'Which type of malware spreads across a network on its own by exploiting vulnerabilities, without needing a user to run it?', 2, 'easy', 'single', 1, 'Worms are self-replicating and self-propagating. They move from host to host automatically, which is why they spread so quickly.', 'Spreads by itself across the network = worm.', 'Worms wiggle through networks on their own.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('e9c0dc56-a6e3-5b2a-a6e4-93af970cd34d', '78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 0, 'Trojan', false, 'A Trojan disguises itself as legitimate software and relies on the user to run it.'),
  ('66eeae0f-538c-557c-9b2e-d6f543a1662d', '78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 1, 'Virus', false, 'A virus attaches to files and typically needs user action to spread.'),
  ('8b822a7c-0d8e-5eaa-9b34-8995c66ec0a5', '78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 2, 'Worm', true, null),
  ('966b3eba-6d67-5414-9708-5d1c3b3887d9', '78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 3, 'Logic bomb', false, 'A logic bomb waits for a trigger condition; it does not propagate.')
insert into public.question_topics (question_id, topic_id) values ('78c3ebe5-dbd4-52e1-92f2-ffa9670a6223', 'malware') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('62058bb6-2f54-5de6-8a7a-4620ea28f342', 'A developer who expects to be fired adds code that will delete the payroll database if their account is ever disabled. What type of malware is this?', 2, 'medium', 'single', 1, 'A logic bomb is malicious code that executes when a specific condition is met, such as a date or an account being disabled.', 'Trigger condition (date, event, account change) = logic bomb.', 'If X happens, then boom: logic bomb.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('db5c29c1-da4c-527c-b8ab-7884cf4596a8', '62058bb6-2f54-5de6-8a7a-4620ea28f342', 0, 'Rootkit', false, 'A rootkit hides malicious activity and maintains privileged access.'),
  ('e8e31cdb-477c-5ee0-8e5d-cfe2844e658c', '62058bb6-2f54-5de6-8a7a-4620ea28f342', 1, 'Logic bomb', true, null),
  ('7ea4ea1d-8de0-58f7-8ace-99dbe76b57de', '62058bb6-2f54-5de6-8a7a-4620ea28f342', 2, 'Remote access Trojan', false, 'A RAT gives an attacker remote control of a system.'),
  ('a88a1ac9-77f1-54ba-bd74-21746676de58', '62058bb6-2f54-5de6-8a7a-4620ea28f342', 3, 'Spyware', false, 'Spyware secretly gathers information about the user.')
insert into public.question_topics (question_id, topic_id) values ('62058bb6-2f54-5de6-8a7a-4620ea28f342', 'malware'), ('62058bb6-2f54-5de6-8a7a-4620ea28f342', 'threat-actors') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('a77fa475-211a-5a42-a4f1-94045979598f', 'An EDR tool alerts that a Word document launched PowerShell, which is running encoded commands directly in memory. No new executable files were written to disk. Which type of attack is MOST likely occurring?', 2, 'hard', 'single', 1, 'Fileless malware runs in memory using legitimate built-in tools such as PowerShell (living off the land), leaving few artifacts on disk. Behavior-based tools like EDR are needed to detect it.', 'Memory-only execution + built-in tools (PowerShell, WMI) + no files on disk = fileless.', 'Fileless: nothing to find on the disk, everything in RAM.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d1d75bb6-65be-5751-b283-138ddc60b885', 'a77fa475-211a-5a42-a4f1-94045979598f', 0, 'Boot sector virus', false, 'Boot sector viruses infect the boot record and run at startup, not from a document macro.'),
  ('73212584-30c4-5a96-9fa1-639028aa6d49', 'a77fa475-211a-5a42-a4f1-94045979598f', 1, 'Fileless malware', true, null),
  ('12c1b137-abb5-5810-8f70-02e734932103', 'a77fa475-211a-5a42-a4f1-94045979598f', 2, 'Adware', false, 'Adware displays unwanted advertising and does not match this behavior.'),
  ('104f7eed-765e-5514-acfa-f46082484d26', 'a77fa475-211a-5a42-a4f1-94045979598f', 3, 'Worm', false, 'Nothing indicates self-propagation across the network.')
insert into public.question_topics (question_id, topic_id) values ('a77fa475-211a-5a42-a4f1-94045979598f', 'malware'), ('a77fa475-211a-5a42-a4f1-94045979598f', 'indicators-of-compromise'), ('a77fa475-211a-5a42-a4f1-94045979598f', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('76982b2e-45e3-5630-93b6-c4d27eb29e2e', 'Which type of malware is designed to conceal its presence and maintain privileged access, often by modifying the operating system kernel?', 2, 'easy', 'single', 1, 'Rootkits hide processes, files, and network connections from the operating system and security tools while keeping administrator-level access.', 'Hidden + privileged + kernel level = rootkit.', 'Rootkit = root access, kept hidden.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('299a3605-3f8a-5dff-b4ad-0a546a98da05', '76982b2e-45e3-5630-93b6-c4d27eb29e2e', 0, 'Keylogger', false, 'A keylogger records keystrokes.'),
  ('57c6bdf0-b303-5918-8875-4ab3f6929dff', '76982b2e-45e3-5630-93b6-c4d27eb29e2e', 1, 'Rootkit', true, null),
  ('2dcb8ba0-b032-53d8-adba-969b4485b366', '76982b2e-45e3-5630-93b6-c4d27eb29e2e', 2, 'Ransomware', false, 'Ransomware encrypts data and demands payment; it wants to be noticed.'),
  ('0df1a5f1-f73b-5cd4-91e8-0fc0732e293c', '76982b2e-45e3-5630-93b6-c4d27eb29e2e', 3, 'Bloatware', false, 'Bloatware is unnecessary preinstalled software.')
insert into public.question_topics (question_id, topic_id) values ('76982b2e-45e3-5630-93b6-c4d27eb29e2e', 'malware') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('561213c1-8b48-532a-bd79-93bdba144bd7', 'Which TWO are common indicators of a ransomware infection on a file server?', 2, 'medium', 'multiple', 2, 'Ransomware encrypts files, often appending a new extension, and drops ransom instructions throughout the file system. Sudden high disk activity and inaccessible files are also typical.', 'Mass renames + ransom notes + unreadable files = ransomware.', 'Ransomware leaves a note and a new extension.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('82917587-1416-5eb7-b29c-25c1bda85afd', '561213c1-8b48-532a-bd79-93bdba144bd7', 0, 'Large numbers of files renamed with a new, unfamiliar extension', true, null),
  ('4b31e0f7-46a9-5633-bdc6-c747183ee53c', '561213c1-8b48-532a-bd79-93bdba144bd7', 1, 'A ransom note file appearing in many directories', true, null),
  ('c945f64b-9f9f-5b05-a314-513e501e334c', '561213c1-8b48-532a-bd79-93bdba144bd7', 2, 'An account logging in from two countries within minutes', false, 'Logins from distant locations in a short time are impossible travel, pointing to credential compromise.'),
  ('e509ac83-cc85-5bef-befa-705478fc5a1a', '561213c1-8b48-532a-bd79-93bdba144bd7', 3, 'A spike in failed logins for many accounts using one password', false, 'One password across many accounts is password spraying.'),
  ('7f9beb61-4250-545a-af87-72639eede9b2', '561213c1-8b48-532a-bd79-93bdba144bd7', 4, 'A certificate expiration warning in the browser', false, 'Certificate expiration is an operational issue, not a ransomware indicator.')
insert into public.question_topics (question_id, topic_id) values ('561213c1-8b48-532a-bd79-93bdba144bd7', 'malware'), ('561213c1-8b48-532a-bd79-93bdba144bd7', 'indicators-of-compromise') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('2af6b5b5-813d-5cc4-b23f-348d0191afe3', 'Which input submitted to a login form MOST likely indicates a SQL injection attempt?', 2, 'easy', 'single', 1, 'The quote closes the string in the query, OR 1=1 makes the condition always true, and -- comments out the rest. This is a classic SQL injection pattern.', 'Quotes, OR 1=1, UNION SELECT, or -- comments = SQL injection.', '1=1 is always true, and that is the trick.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('95c1f640-9f58-5e8a-b443-9a086c146e4b', '2af6b5b5-813d-5cc4-b23f-348d0191afe3', 0, ''' OR 1=1 --', true, null),
  ('ced8e5f9-c338-58f8-9eae-040751502626', '2af6b5b5-813d-5cc4-b23f-348d0191afe3', 1, '<script>alert(document.cookie)</script>', false, 'Script tags indicate cross-site scripting.'),
  ('d70e8981-65e0-5bfb-83a2-efa3dc361e05', '2af6b5b5-813d-5cc4-b23f-348d0191afe3', 2, '../../../etc/passwd', false, 'Dot-dot-slash sequences indicate directory traversal.'),
  ('53673721-dd8f-57de-9564-8b07f23524b2', '2af6b5b5-813d-5cc4-b23f-348d0191afe3', 3, 'A 5,000-character string of the letter A', false, 'An oversized input suggests a buffer overflow attempt.')
insert into public.question_topics (question_id, topic_id) values ('2af6b5b5-813d-5cc4-b23f-348d0191afe3', 'application-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('7fe2c449-6b8b-5851-b914-d178c221e5ae', 'A community forum displays user comments without sanitizing them. An attacker posts a comment containing JavaScript that sends the session cookie of anyone who views the page to the attacker''s server. Which attack is this?', 2, 'medium', 'single', 1, 'The malicious script is saved on the server and runs in every visitor''s browser. Because it persists, this is stored (persistent) XSS.', 'Script saved on the site and served to many users = stored XSS. Script in a crafted link = reflected XSS.', 'Stored XSS waits on the page for every visitor.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('cb9b817b-1bee-58b0-9134-50c3ba9771ad', '7fe2c449-6b8b-5851-b914-d178c221e5ae', 0, 'Reflected cross-site scripting', false, 'Reflected XSS bounces the script off a request, such as a crafted link, and is not saved on the site.'),
  ('f42a72de-ae18-51e9-9195-ff7430a340ae', '7fe2c449-6b8b-5851-b914-d178c221e5ae', 1, 'Stored cross-site scripting', true, null),
  ('1fc0a21a-e166-5d1e-8d7b-b40bd07b16b1', '7fe2c449-6b8b-5851-b914-d178c221e5ae', 2, 'Cross-site request forgery', false, 'CSRF tricks a user''s browser into sending an unwanted request; it does not inject script.'),
  ('ad38391d-3b3c-50b3-8bea-c062699b480e', '7fe2c449-6b8b-5851-b914-d178c221e5ae', 3, 'SQL injection', false, 'SQL injection targets the database query, not other users'' browsers.')
insert into public.question_topics (question_id, topic_id) values ('7fe2c449-6b8b-5851-b914-d178c221e5ae', 'application-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 'Which control BEST mitigates cross-site request forgery (CSRF)?', 2, 'medium', 'single', 1, 'CSRF works because the browser automatically sends the victim''s cookies. A secret token that an attacker''s page cannot know or read proves the request came from the legitimate application.', 'Forged requests riding on a logged-in session = CSRF; defend with anti-CSRF tokens and SameSite cookies.', 'CSRF: prove the request came from you with a secret token.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('38ea6870-118e-5151-aac3-44f7a0ad7ca9', 'b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 0, 'Parameterized database queries', false, 'Parameterized queries prevent SQL injection.'),
  ('d20686ef-69c0-5ba7-8a89-97e8dba153b0', 'b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 1, 'Unpredictable anti-CSRF tokens validated on every state-changing request', true, null),
  ('79055de6-404e-52bd-b2f3-92a962092c63', 'b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 2, 'Output encoding of user-supplied HTML', false, 'Output encoding prevents XSS.'),
  ('c55bfbaa-9909-5fd9-904d-93cd34b90527', 'b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 3, 'Stack canaries in compiled code', false, 'Stack canaries help detect buffer overflows.')
insert into public.question_topics (question_id, topic_id) values ('b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 'application-attacks'), ('b1a1e0a3-d158-5fad-a46f-67df8afc51d9', 'application-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ebb67740-291b-5fee-abbc-53e7f43b0157', 'A web server log shows the request GET /download?file=../../../../etc/passwd. Which attack is being attempted?', 2, 'easy', 'single', 1, 'Repeated ../ sequences try to climb out of the web root to read files elsewhere on the server, such as the Linux password file.', '../ in a path = directory (path) traversal.', 'Dot-dot-slash climbs the directory tree.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('9fc31f8e-18bc-5263-bcdc-44f63a00bbb8', 'ebb67740-291b-5fee-abbc-53e7f43b0157', 0, 'Directory traversal', true, null),
  ('0fb172ae-1f21-53e9-927b-71a2a65396ab', 'ebb67740-291b-5fee-abbc-53e7f43b0157', 1, 'Command injection', false, 'Command injection would include shell operators such as ; or && with operating system commands.'),
  ('19b42fb1-e1bb-580d-b154-5721e9d0aa2c', 'ebb67740-291b-5fee-abbc-53e7f43b0157', 2, 'Server-side request forgery', false, 'SSRF makes the server request an attacker-chosen URL, often an internal address.'),
  ('cc17cbb2-cbc3-5f04-9692-697d4cba59c7', 'ebb67740-291b-5fee-abbc-53e7f43b0157', 3, 'Buffer overflow', false, 'A buffer overflow sends more data than a buffer can hold.')
insert into public.question_topics (question_id, topic_id) values ('ebb67740-291b-5fee-abbc-53e7f43b0157', 'application-attacks'), ('ebb67740-291b-5fee-abbc-53e7f43b0157', 'indicators-of-compromise') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('34da8c6f-0e88-50be-8121-65108830dab1', 'A banking application checks an account balance and, a few milliseconds later, debits the account. An attacker sends many simultaneous withdrawal requests that all pass the balance check before any debit is recorded. Which vulnerability is being exploited?', 2, 'hard', 'single', 1, 'The gap between checking a condition and acting on it lets concurrent requests all see the same pre-debit balance. This is a TOCTOU race condition, fixed with atomic transactions or locking.', 'Simultaneous requests + check-then-act gap = race condition (TOCTOU).', 'Checked at one time, used at another: the gap is the bug.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('84193a69-7463-5bc6-8b4c-8cb0f183600c', '34da8c6f-0e88-50be-8121-65108830dab1', 0, 'Buffer overflow', false, 'Nothing overflows a memory buffer here.'),
  ('1c0c941b-0ead-504e-b433-6ccff2325e87', '34da8c6f-0e88-50be-8121-65108830dab1', 1, 'Time-of-check to time-of-use (TOCTOU) race condition', true, null),
  ('28c39163-b186-5df4-ba91-a0b3da801c7e', '34da8c6f-0e88-50be-8121-65108830dab1', 2, 'Replay attack', false, 'A replay attack resends a captured valid message; these are new concurrent requests exploiting timing.'),
  ('61e22e76-6eb6-5be0-a113-b377a35e2183', '34da8c6f-0e88-50be-8121-65108830dab1', 3, 'Memory injection', false, 'Memory injection places malicious code into a running process''s memory.')
insert into public.question_topics (question_id, topic_id) values ('34da8c6f-0e88-50be-8121-65108830dab1', 'vulnerabilities'), ('34da8c6f-0e88-50be-8121-65108830dab1', 'application-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('bc31d687-9b7d-5538-831c-a6bd037a2937', 'Which attack uses traffic from many compromised systems to overwhelm a target so legitimate users cannot reach it?', 2, 'easy', 'single', 1, 'A DDoS attack uses many sources, often a botnet, to exhaust a target''s bandwidth or resources, attacking availability.', 'Many sources + unavailable service = DDoS.', 'Distributed = many attackers, denial = nobody gets in.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('24079fe1-05e5-5a8a-8e09-bf8b4c715beb', 'bc31d687-9b7d-5538-831c-a6bd037a2937', 0, 'Distributed denial of service (DDoS)', true, null),
  ('a190c623-ea68-544a-ac55-340c2a4e5a81', 'bc31d687-9b7d-5538-831c-a6bd037a2937', 1, 'On-path attack', false, 'An on-path attack intercepts traffic between two parties.'),
  ('9034f55e-8686-53f2-b13f-de93027b60bd', 'bc31d687-9b7d-5538-831c-a6bd037a2937', 2, 'DNS poisoning', false, 'DNS poisoning redirects users by corrupting name resolution.'),
  ('89879166-682b-54b7-94ff-de3bdf4aad95', 'bc31d687-9b7d-5538-831c-a6bd037a2937', 3, 'Credential replay', false, 'Credential replay reuses captured authentication data.')
insert into public.question_topics (question_id, topic_id) values ('bc31d687-9b7d-5538-831c-a6bd037a2937', 'network-attacks'), ('bc31d687-9b7d-5538-831c-a6bd037a2937', 'cia-triad') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e4610624-c82d-5df7-af0f-5f83501c5180', 'An attacker sends small DNS queries to many open resolvers, spoofing the victim''s IP address as the source. The resolvers send much larger responses to the victim. What is this attack?', 2, 'medium', 'single', 1, 'Spoofed small requests that trigger large responses aimed at a victim is an amplification (reflection) attack. The open resolvers unknowingly flood the target.', 'Spoofed source + small request + large response = amplification.', 'Whisper a question, the resolver shouts the answer at the victim.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('6c2dcbf8-1998-575b-87c3-cec00171f77d', 'e4610624-c82d-5df7-af0f-5f83501c5180', 0, 'DNS cache poisoning', false, 'Cache poisoning inserts false records into a resolver; it does not flood a victim.'),
  ('f2a7301a-aa59-5c44-8209-7bb37a4bd036', 'e4610624-c82d-5df7-af0f-5f83501c5180', 1, 'DNS amplification (reflected DDoS)', true, null),
  ('9502a57e-58e5-5973-a11c-f77163d185cf', 'e4610624-c82d-5df7-af0f-5f83501c5180', 2, 'Domain hijacking', false, 'Domain hijacking takes over a domain''s registration.'),
  ('c819d52e-944a-5f89-b914-2a457d297879', 'e4610624-c82d-5df7-af0f-5f83501c5180', 3, 'DNS tunneling', false, 'DNS tunneling hides data inside DNS queries, typically for exfiltration or command and control.')
insert into public.question_topics (question_id, topic_id) values ('e4610624-c82d-5df7-af0f-5f83501c5180', 'network-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('72170e05-e5dd-545a-9605-0cb6eb8f80b0', 'At a coffee shop, an attacker sets up an access point that broadcasts the same network name as the shop''s legitimate Wi-Fi so customers connect to it. What is this attack?', 2, 'medium', 'single', 1, 'An evil twin impersonates a legitimate network''s SSID to lure victims so the attacker can intercept their traffic.', 'Same SSID as the real network = evil twin.', 'Evil twin looks just like its sibling.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('770ddd67-5ec5-5415-81a7-5a8388e8fc54', '72170e05-e5dd-545a-9605-0cb6eb8f80b0', 0, 'Rogue access point', false, 'A rogue access point is any unauthorized AP connected to a network; the defining trait here is impersonating a legitimate SSID.'),
  ('d7d9c283-2158-5d69-8e52-40ac42a81bb7', '72170e05-e5dd-545a-9605-0cb6eb8f80b0', 1, 'Evil twin', true, null),
  ('929d5369-987c-535a-990e-f0d0ce780658', '72170e05-e5dd-545a-9605-0cb6eb8f80b0', 2, 'Bluejacking', false, 'Bluejacking sends unsolicited messages over Bluetooth.'),
  ('d3dcfcdd-0bd5-5495-be92-4b4a5fd379f3', '72170e05-e5dd-545a-9605-0cb6eb8f80b0', 3, 'RF jamming', false, 'Jamming disrupts wireless signals; it does not lure users to connect.')
insert into public.question_topics (question_id, topic_id) values ('72170e05-e5dd-545a-9605-0cb6eb8f80b0', 'network-attacks'), ('72170e05-e5dd-545a-9605-0cb6eb8f80b0', 'wireless-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f967c395-6996-5a75-b970-74ffedf9f8d7', 'An analyst sees many unsolicited ARP replies on a LAN that map the default gateway''s IP address to an unfamiliar MAC address. Which attack is MOST likely underway?', 2, 'hard', 'single', 1, 'Gratuitous ARP replies claiming the gateway''s IP make hosts send their traffic to the attacker''s MAC address, placing the attacker on-path to intercept or modify traffic.', 'Gateway IP suddenly maps to a new MAC = ARP poisoning for on-path interception.', 'ARP lies about who the gateway is.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('84f73506-2387-528d-8556-39b03a196701', 'f967c395-6996-5a75-b970-74ffedf9f8d7', 0, 'MAC flooding to overload the switch', false, 'MAC flooding sends huge numbers of frames with random source MACs to overflow the CAM table, not targeted gateway replies.'),
  ('eb285d70-f174-5014-abbc-95d3d5700c04', 'f967c395-6996-5a75-b970-74ffedf9f8d7', 1, 'ARP poisoning to perform an on-path attack', true, null),
  ('20a5f2ee-dfa9-550a-bbee-7155cc539655', 'f967c395-6996-5a75-b970-74ffedf9f8d7', 2, 'DNS poisoning to redirect domain lookups', false, 'DNS poisoning corrupts name resolution, not IP-to-MAC mappings.'),
  ('835613bf-bb62-558b-a6db-e0097cf1f181', 'f967c395-6996-5a75-b970-74ffedf9f8d7', 3, 'VLAN hopping to reach another VLAN', false, 'VLAN hopping abuses trunking or double tagging, not ARP.')
insert into public.question_topics (question_id, topic_id) values ('f967c395-6996-5a75-b970-74ffedf9f8d7', 'network-attacks'), ('f967c395-6996-5a75-b970-74ffedf9f8d7', 'indicators-of-compromise') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('763afde9-cd8b-509b-ad79-d78210b6f6fb', 'Authentication logs show a single login attempt for each of 3,000 accounts within one hour, all using the password ''Spring2026!''. Which attack is this?', 2, 'medium', 'single', 1, 'Password spraying tries one or a few common passwords across many accounts, staying under per-account lockout thresholds.', 'One password, many accounts = spraying. Many passwords, one account = brute force. Leaked pairs = stuffing.', 'Spraying is wide and shallow.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('90fb688d-44c2-594f-8f86-d6842f2c0330', '763afde9-cd8b-509b-ad79-d78210b6f6fb', 0, 'Brute-force attack', false, 'Brute force tries many passwords against one account and would trigger lockouts.'),
  ('ba4d19e9-f2b2-542e-8281-3c2908eda3b2', '763afde9-cd8b-509b-ad79-d78210b6f6fb', 1, 'Password spraying', true, null),
  ('da0a9eb1-c5a5-5ab1-8251-9322d9c3441c', '763afde9-cd8b-509b-ad79-d78210b6f6fb', 2, 'Credential stuffing', false, 'Credential stuffing uses known username and password pairs from previous breaches, so the passwords would vary.'),
  ('b0a2b92e-5cd9-5d8c-af4f-49b73530a508', '763afde9-cd8b-509b-ad79-d78210b6f6fb', 3, 'Rainbow table attack', false, 'Rainbow tables crack stolen hashes offline; they do not generate login attempts.')
insert into public.question_topics (question_id, topic_id) values ('763afde9-cd8b-509b-ad79-d78210b6f6fb', 'password-attacks'), ('763afde9-cd8b-509b-ad79-d78210b6f6fb', 'indicators-of-compromise') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('5df457a2-f83d-56a7-b174-d85e5ff2ff54', 'Attackers use username and password pairs leaked from a breached shopping site to log in to employees'' corporate accounts. Which control MOST directly reduces this risk?', 2, 'medium', 'single', 1, 'Credential stuffing succeeds because users reuse passwords. MFA means a correct password alone is not enough to log in.', 'Stolen but valid passwords? The fix is a second factor, not a stronger password rule.', 'A leaked password is useless without the second factor.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('78572773-b075-5727-a21e-a088160b81ef', '5df457a2-f83d-56a7-b174-d85e5ff2ff54', 0, 'Requiring longer passwords', false, 'Reused passwords may already be long, and attackers already know them.'),
  ('d64c859a-50ab-5e13-90c4-56f4ef9b9783', '5df457a2-f83d-56a7-b174-d85e5ff2ff54', 1, 'Multifactor authentication', true, null),
  ('2f2bfc88-c886-5823-b29a-92f7e80a8c4f', '5df457a2-f83d-56a7-b174-d85e5ff2ff54', 2, 'Locking accounts after three failed attempts', false, 'Each leaked pair is typically tried once, so lockouts are rarely triggered.'),
  ('9157258f-62db-501e-9f29-ae5e2a5129cb', '5df457a2-f83d-56a7-b174-d85e5ff2ff54', 3, 'Enforcing password history', false, 'Password history prevents reusing old corporate passwords, not reusing a corporate password on other sites.')
insert into public.question_topics (question_id, topic_id) values ('5df457a2-f83d-56a7-b174-d85e5ff2ff54', 'password-attacks'), ('5df457a2-f83d-56a7-b174-d85e5ff2ff54', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('457ade1b-2a0b-5145-bea2-73cdd925caad', 'An attacker positioned between a client and server manipulates the TLS handshake so both sides negotiate an older protocol version with weak cipher suites. What is this called?', 2, 'hard', 'single', 1, 'A downgrade attack forces use of weaker protocols or ciphers that the attacker can then break. Disabling legacy versions on servers prevents it.', 'Forced to use an older or weaker version = downgrade.', 'Downgrade: talk them down to something breakable.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('0dd325a5-b06a-58bc-99be-5f8d105eff98', '457ade1b-2a0b-5145-bea2-73cdd925caad', 0, 'Collision attack', false, 'A collision attack finds two inputs with the same hash.'),
  ('50585fae-78de-5595-ab69-6058d841f0ab', '457ade1b-2a0b-5145-bea2-73cdd925caad', 1, 'Birthday attack', false, 'A birthday attack is a probability-based technique for finding hash collisions.'),
  ('c709a725-ffae-5bca-b811-456c2eb9d8d5', '457ade1b-2a0b-5145-bea2-73cdd925caad', 2, 'Downgrade attack', true, null),
  ('c617ee12-a0fe-59b0-ab68-e2f908a8a04d', '457ade1b-2a0b-5145-bea2-73cdd925caad', 3, 'Replay attack', false, 'A replay attack retransmits captured valid data.')
insert into public.question_topics (question_id, topic_id) values ('457ade1b-2a0b-5145-bea2-73cdd925caad', 'cryptographic-attacks'), ('457ade1b-2a0b-5145-bea2-73cdd925caad', 'network-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 'What is a zero-day vulnerability?', 2, 'easy', 'single', 1, 'A zero-day is a flaw that defenders have had zero days to fix because it is unknown to the vendor or no patch exists yet.', 'No patch, no signature, no warning = zero-day. Defend with layered and behavior-based controls.', 'Zero days of warning for defenders.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('194c1c59-d706-57ee-9419-6416a31d52a0', 'd0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 0, 'A vulnerability that is unknown to the vendor or has no patch available', true, null),
  ('1133f1cb-587e-5143-be03-d1f87954b185', 'd0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 1, 'A vulnerability that was patched the same day it was found', false, 'A same-day patch means the vulnerability is no longer a zero-day.'),
  ('4501c0a4-55a0-57d2-8b1e-870b42c26df7', 'd0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 2, 'A misconfiguration introduced on the first day of deployment', false, 'A deployment-day misconfiguration is a configuration weakness, not a zero-day.'),
  ('ccc7a150-0fd6-5d48-9045-0c49a7301a11', 'd0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 3, 'A vulnerability with a CVSS score of zero', false, 'CVSS scores measure severity; zero-day refers to patch availability.')
insert into public.question_topics (question_id, topic_id) values ('d0d34f31-bf40-5a6b-8ab6-c4d5a3071335', 'vulnerabilities') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('a56851f7-4479-5f6c-b047-8d9586dd4bbb', 'A newly deployed network appliance is still using the vendor''s default administrator username and password. Which vulnerability category does this represent?', 2, 'easy', 'single', 1, 'Leaving defaults in place is a misconfiguration. Default credentials are publicly documented and are among the first things attackers try.', 'Defaults left unchanged = misconfiguration. Fix with hardening baselines.', 'Default passwords are public passwords.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('78cf792b-5eca-50d7-8e9f-5ece8148b501', 'a56851f7-4479-5f6c-b047-8d9586dd4bbb', 0, 'Zero-day', false, 'The weakness is well known; a zero-day is unknown to the vendor.'),
  ('c9a6934b-65df-51eb-846f-288244ea0a24', 'a56851f7-4479-5f6c-b047-8d9586dd4bbb', 1, 'Misconfiguration', true, null),
  ('823c5daa-455d-57e7-85a7-1e633739fb0d', 'a56851f7-4479-5f6c-b047-8d9586dd4bbb', 2, 'Supply chain', false, 'A supply chain issue is a compromise introduced by a vendor or component.'),
  ('d719cdfd-ee67-5b06-b5d7-a601edaf5949', 'a56851f7-4479-5f6c-b047-8d9586dd4bbb', 3, 'Memory injection', false, 'Memory injection places malicious code into a process''s memory.')
insert into public.question_topics (question_id, topic_id) values ('a56851f7-4479-5f6c-b047-8d9586dd4bbb', 'vulnerabilities'), ('a56851f7-4479-5f6c-b047-8d9586dd4bbb', 'hardening') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3d453fcb-b3db-515e-8ad2-9e137f44896f', 'Attackers compromise a software vendor''s build server and insert a backdoor into a legitimate, digitally signed update installed by thousands of customers. Which attack vector is this?', 2, 'medium', 'single', 1, 'A supply chain attack compromises a trusted vendor, product, or service to reach its customers. Signed updates are trusted, which makes these attacks very effective.', 'Compromise the vendor to reach the customers = supply chain.', 'Poison the source, reach everyone downstream.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ed4eb43c-c068-5e0f-9464-b7161e6405f5', '3d453fcb-b3db-515e-8ad2-9e137f44896f', 0, 'Watering hole', false, 'A watering hole compromises a website visited by targets.'),
  ('a57d6d70-f7d2-5eef-9c40-4e6c4afa123d', '3d453fcb-b3db-515e-8ad2-9e137f44896f', 1, 'Supply chain', true, null),
  ('c8931604-4612-530c-a99a-ce52b93c0d8a', '3d453fcb-b3db-515e-8ad2-9e137f44896f', 2, 'Removable media', false, 'Removable media attacks rely on USB drives or similar devices.'),
  ('b3c5d58a-a5d5-57b1-9f83-96c9b3ee147d', '3d453fcb-b3db-515e-8ad2-9e137f44896f', 3, 'Unsecure network', false, 'Unsecure networks are exploited through open Wi-Fi or unencrypted protocols.')
insert into public.question_topics (question_id, topic_id) values ('3d453fcb-b3db-515e-8ad2-9e137f44896f', 'attack-vectors'), ('3d453fcb-b3db-515e-8ad2-9e137f44896f', 'vendor-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 'A user''s account signs in from New York and, 20 minutes later, from Singapore. What is this security indicator called?', 2, 'easy', 'single', 1, 'No one can physically travel between those locations in 20 minutes, so the logins indicate that credentials are being used by someone else.', 'Two distant locations in less time than travel allows = impossible travel.', 'Nobody flies New York to Singapore in 20 minutes.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('85db63b5-a566-5518-8564-b552767ef2d8', 'e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 0, 'Account lockout', false, 'Account lockout happens after repeated failed logins.'),
  ('4855c7f7-40e4-5ce1-b7c9-6f40f23e3041', 'e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 1, 'Impossible travel', true, null),
  ('9206e027-22e8-53ad-ad63-1c4516deb57a', 'e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 2, 'Resource inaccessibility', false, 'Resource inaccessibility means systems or files cannot be reached.'),
  ('355e5e60-b3e3-57fa-b555-5ac7be760ace', 'e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 3, 'Concurrent session usage', false, 'Concurrent sessions can be an indicator, but the defining detail here is geographic distance over a short time.')
insert into public.question_topics (question_id, topic_id) values ('e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 'indicators-of-compromise'), ('e0cc8be3-4d66-5ebf-b3c0-d8eafcb7915b', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('55e24c6a-95ff-5da1-bbd8-6eb05304c566', 'After a phishing incident, a company wants to ensure that users can run only approved applications on their workstations. Which mitigation is BEST?', 2, 'medium', 'single', 1, 'An allow list permits only explicitly approved software; everything else is blocked by default, including new, unknown malware.', '''Only approved'' = allow list. ''Block known bad'' = deny list.', 'Allow list: if it is not on the list, it does not run.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('721ec7d2-a3ae-5995-8a1a-2b6c4cedfb89', '55e24c6a-95ff-5da1-bbd8-6eb05304c566', 0, 'Application allow list', true, null),
  ('8b3ea6d6-64df-53a1-b050-509957549e38', '55e24c6a-95ff-5da1-bbd8-6eb05304c566', 1, 'Block list of known malware hashes', false, 'A block list stops only known-bad items and misses new malware.'),
  ('1f3fb258-c1cd-5348-8d2b-967f9f0a9e1e', '55e24c6a-95ff-5da1-bbd8-6eb05304c566', 2, 'Full-disk encryption', false, 'Full-disk encryption protects data at rest if a device is stolen, not what executes.'),
  ('ed98b0ad-f540-5809-97bd-445fad7f0ed9', '55e24c6a-95ff-5da1-bbd8-6eb05304c566', 3, 'A shorter screen-lock timeout', false, 'Screen locks prevent unauthorized physical access, not malware execution.')
insert into public.question_topics (question_id, topic_id) values ('55e24c6a-95ff-5da1-bbd8-6eb05304c566', 'mitigation-techniques'), ('55e24c6a-95ff-5da1-bbd8-6eb05304c566', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('6165f7fc-e876-5102-8fd3-259b29008be6', 'An end-of-life file server cannot be patched but must stay in service for six more months. Which TWO actions BEST reduce the risk until it is retired?', 2, 'hard', 'multiple', 2, 'When patching is impossible, reduce exposure with isolation and compensate with stronger detection. Together they limit who can reach the system and increase the chance of catching abuse.', 'Can''t patch? Isolate it, restrict it, watch it.', 'Legacy systems get a fence and a flashlight.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('88bd1388-bfd4-55b6-91b7-78c1797fbc29', '6165f7fc-e876-5102-8fd3-259b29008be6', 0, 'Place it in an isolated segment reachable only from systems that require it', true, null),
  ('6055e2a1-55a7-5b0f-a808-b39eb55dc69f', '6165f7fc-e876-5102-8fd3-259b29008be6', 1, 'Increase monitoring and alerting for activity on the server', true, null),
  ('b0fde953-8313-522c-ab1b-50d9dbe95100', '6165f7fc-e876-5102-8fd3-259b29008be6', 2, 'Disable host logging to improve performance', false, 'Disabling logs removes visibility exactly when monitoring matters most.'),
  ('9e4c68f7-bf53-58fb-bf4f-0e4d0bb08d3d', '6165f7fc-e876-5102-8fd3-259b29008be6', 3, 'Grant all users read access to reduce help desk tickets', false, 'Broad access violates least privilege and increases exposure.'),
  ('8eba7f9b-f250-5397-a0b3-be723c99e198', '6165f7fc-e876-5102-8fd3-259b29008be6', 4, 'Remove it from the asset inventory since it is being retired', false, 'Removing it from inventory makes an unsupported system invisible to security processes.')
insert into public.question_topics (question_id, topic_id) values ('6165f7fc-e876-5102-8fd3-259b29008be6', 'mitigation-techniques'), ('6165f7fc-e876-5102-8fd3-259b29008be6', 'vulnerabilities'), ('6165f7fc-e876-5102-8fd3-259b29008be6', 'segmentation') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ad45a715-dc03-5803-bc8d-e7b41d81a570', 'A user installs a mobile app from a third-party website instead of the official app store. What is this practice called?', 2, 'easy', 'single', 1, 'Sideloading installs apps from outside the official store, bypassing the store''s vetting and increasing the risk of malware.', 'App from outside the official store = sideloading. Removing OS restrictions = jailbreaking or rooting.', 'Sideloading comes in through the side door.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b3738685-5328-5f14-8dd6-c21e5c3cce91', 'ad45a715-dc03-5803-bc8d-e7b41d81a570', 0, 'Jailbreaking', false, 'Jailbreaking removes operating system restrictions on iOS; it often enables sideloading but is a different act.'),
  ('40e3d20a-9cdd-51cf-8e1d-63875991697b', 'ad45a715-dc03-5803-bc8d-e7b41d81a570', 1, 'Sideloading', true, null),
  ('b2b78ff6-bdf6-5374-bb7a-0f05ed4fa685', 'ad45a715-dc03-5803-bc8d-e7b41d81a570', 2, 'Tethering', false, 'Tethering shares a device''s cellular connection.'),
  ('f8f0f8f4-d4d8-52d8-ae42-55699f182638', 'ad45a715-dc03-5803-bc8d-e7b41d81a570', 3, 'Geofencing', false, 'Geofencing triggers actions based on a device''s location.')
insert into public.question_topics (question_id, topic_id) values ('ad45a715-dc03-5803-bc8d-e7b41d81a570', 'attack-vectors'), ('ad45a715-dc03-5803-bc8d-e7b41d81a570', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 'Under the shared responsibility model for Infrastructure as a Service (IaaS), which party is typically responsible for patching the guest operating system on a virtual machine?', 3, 'easy', 'single', 1, 'In IaaS, the provider secures the physical hosts, network, and hypervisor. The customer manages everything from the guest operating system upward, including patches.', 'IaaS: you manage the OS and up. PaaS: you manage apps and data. SaaS: you manage users and data.', 'The more ''as a service'', the less you manage.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a668c3ea-a4df-5257-949f-43930d1a5feb', 'de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 0, 'The customer', true, null),
  ('932a96d7-cb75-537e-99b7-5a0bc9b94901', 'de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 1, 'The cloud provider', false, 'The provider does not manage the customer''s guest OS in IaaS.'),
  ('72546416-6bd4-552d-aba3-8adb3244736c', 'de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 2, 'The hypervisor vendor', false, 'The hypervisor vendor is not responsible for tenants'' guest operating systems.'),
  ('fcb02ef1-f81c-59d0-91e4-73528bd80bc8', 'de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 3, 'Responsibility is always split evenly by law', false, 'Responsibilities are defined by the service model and contract, not split evenly.')
insert into public.question_topics (question_id, topic_id) values ('de559bac-2d63-5ebc-aff9-6984f9ef5c8f', 'cloud-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('a7c4cf30-98d7-54a2-92a9-1551a2934993', 'Which cloud service model gives users a complete, ready-to-use application where the provider manages the infrastructure, platform, and software?', 3, 'easy', 'single', 1, 'Software as a Service delivers a finished application, such as web email. The customer is mainly responsible for its data, user accounts, and access settings.', 'Just log in and use it = SaaS.', 'SaaS = software, served.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b92e1249-57b1-5567-9151-35fc08a3bbec', 'a7c4cf30-98d7-54a2-92a9-1551a2934993', 0, 'IaaS', false, 'IaaS provides virtual servers, storage, and networking that the customer builds on.'),
  ('1b8ce8a5-c790-50ab-a36e-424458acd848', 'a7c4cf30-98d7-54a2-92a9-1551a2934993', 1, 'PaaS', false, 'PaaS provides a platform for customers to deploy their own applications.'),
  ('b1f57605-2969-58e3-8476-a385f2e1a873', 'a7c4cf30-98d7-54a2-92a9-1551a2934993', 2, 'SaaS', true, null),
  ('0614ed65-b5d2-5e42-a98f-e7d1785b95db', 'a7c4cf30-98d7-54a2-92a9-1551a2934993', 3, 'On-premises', false, 'On-premises means the organization runs everything itself.')
insert into public.question_topics (question_id, topic_id) values ('a7c4cf30-98d7-54a2-92a9-1551a2934993', 'cloud-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 'A company discovers employees are using dozens of unsanctioned SaaS applications. It wants visibility into this usage and the ability to enforce data policies between users and cloud services. Which solution BEST fits?', 3, 'medium', 'single', 1, 'A CASB sits between users and cloud services to discover shadow IT, enforce access and data-loss policies, and monitor activity across SaaS applications.', 'Visibility and policy control over cloud app usage = CASB.', 'CASB = the security broker between users and the cloud.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('beafd1dd-3223-5941-9751-9747737c77d0', '9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 0, 'Web application firewall', false, 'A WAF protects a web application the company hosts from attacks; it does not govern employees'' use of SaaS apps.'),
  ('9d50cd2f-823b-5e02-ae6b-e42763a72d64', '9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 1, 'Cloud access security broker (CASB)', true, null),
  ('15109834-fccb-50cf-b329-b9a195e127bd', '9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 2, 'Next-generation firewall at the data center', false, 'A data center firewall cannot see traffic from remote users going directly to cloud services.'),
  ('6515b61e-c364-56c4-a131-b7df23255355', '9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 3, 'Hardware security module', false, 'An HSM stores and processes cryptographic keys.')
insert into public.question_topics (question_id, topic_id) values ('9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 'cloud-security'), ('9343abd1-a8e9-572b-ad90-cb8f263c7c4e', 'dlp') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('62142bb0-c4a0-5e2d-80e4-d28867673198', 'What is a key security benefit of managing cloud infrastructure with infrastructure as code (IaC)?', 3, 'medium', 'single', 1, 'IaC defines infrastructure in code templates. Changes can be peer reviewed, scanned for misconfigurations, versioned, and deployed identically every time.', 'IaC benefits: repeatability, consistency, version control, and fewer manual errors.', 'If infrastructure is code, it can be reviewed like code.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ba9ae94f-d888-5905-ad95-06dd9dcb56e5', '62142bb0-c4a0-5e2d-80e4-d28867673198', 0, 'It removes the need to patch systems', false, 'Systems deployed through IaC still need patching.'),
  ('868b20e3-520d-5fd8-aa73-acfbf3c5674f', '62142bb0-c4a0-5e2d-80e4-d28867673198', 1, 'Configurations are consistent, reviewable, and version-controlled, which reduces misconfiguration and drift', true, null),
  ('e1b45eef-647d-569d-b2a0-21829ef13eb7', '62142bb0-c4a0-5e2d-80e4-d28867673198', 2, 'All data is automatically encrypted', false, 'Encryption must still be configured; IaC does not add it automatically.'),
  ('075a1123-ff19-5851-9361-22581b78ba51', '62142bb0-c4a0-5e2d-80e4-d28867673198', 3, 'It transfers all security responsibility to the cloud provider', false, 'The shared responsibility model still applies.')
insert into public.question_topics (question_id, topic_id) values ('62142bb0-c4a0-5e2d-80e4-d28867673198', 'cloud-security'), ('62142bb0-c4a0-5e2d-80e4-d28867673198', 'automation') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('74916532-0cbc-5655-a1d5-2581cdd468e5', 'A misconfigured cloud storage bucket exposed customer files to the public internet. Under the shared responsibility model, who was responsible for the bucket''s access configuration?', 3, 'medium', 'single', 1, 'Providers secure the storage service itself, but customers are responsible for how they configure access to their own data. Most cloud breaches stem from customer misconfiguration.', 'Customer data and customer configuration = customer responsibility, in every cloud model.', 'The provider secures the cloud; you secure what you put in it.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7b9832a5-395f-51af-8bd1-15efb0839097', '74916532-0cbc-5655-a1d5-2581cdd468e5', 0, 'The cloud provider', false, 'The provider secures the underlying service, not each tenant''s access settings.'),
  ('676467b1-b496-5b57-a02f-f31fd879429d', '74916532-0cbc-5655-a1d5-2581cdd468e5', 1, 'The customer', true, null),
  ('2ceee731-fa84-5315-859c-5beb8725931b', '74916532-0cbc-5655-a1d5-2581cdd468e5', 2, 'The customers'' internet service providers', false, 'ISPs have no role in configuring cloud storage permissions.'),
  ('334b05f0-f4c4-5ce4-873d-2f83447e28b3', '74916532-0cbc-5655-a1d5-2581cdd468e5', 3, 'No one, because storage is public by default', false, 'Major providers default to private storage; access must be configured.')
insert into public.question_topics (question_id, topic_id) values ('74916532-0cbc-5655-a1d5-2581cdd468e5', 'cloud-security'), ('74916532-0cbc-5655-a1d5-2581cdd468e5', 'data-protection') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('98223108-4e5e-57f0-a4b4-5820ad5c20b0', 'An attacker breaks out of a guest virtual machine and gains access to the hypervisor and other VMs running on the same host. What is this called?', 3, 'medium', 'single', 1, 'VM escape breaks the isolation between a guest and the hypervisor, potentially compromising every VM on the host. Keeping hypervisors patched is the main defense.', 'Guest breaks out to the host = VM escape.', 'Escape the VM, own the host.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('2e16b698-21ac-5311-971b-e0d9f1ba37a9', '98223108-4e5e-57f0-a4b4-5820ad5c20b0', 0, 'VM sprawl', false, 'VM sprawl is an uncontrolled growth of unmanaged VMs.'),
  ('0859cfa2-b721-5f48-9815-50b569b86054', '98223108-4e5e-57f0-a4b4-5820ad5c20b0', 1, 'VM escape', true, null),
  ('e7877c78-e642-5350-beb3-722a63faff4d', '98223108-4e5e-57f0-a4b4-5820ad5c20b0', 2, 'Resource reuse', false, 'Resource reuse is when memory or storage from one tenant is not properly cleared before another uses it.'),
  ('cd85e6aa-d35f-5124-af7b-335a27090d58', '98223108-4e5e-57f0-a4b4-5820ad5c20b0', 3, 'Container drift', false, 'Container drift is when a running container no longer matches its image.')
insert into public.question_topics (question_id, topic_id) values ('98223108-4e5e-57f0-a4b4-5820ad5c20b0', 'virtualization'), ('98223108-4e5e-57f0-a4b4-5820ad5c20b0', 'vulnerabilities') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('837a7a75-3497-5bc2-ad87-da1342d1c634', 'An organization has hundreds of undocumented, unpatched virtual machines left over from short-term projects. Which issue does this describe?', 3, 'easy', 'single', 1, 'VM sprawl occurs when virtual machines are created faster than they are tracked and maintained, leaving forgotten systems that miss patches and monitoring.', 'Too many unmanaged VMs = sprawl. Solve with inventory and lifecycle management.', 'Sprawl is VMs spreading like weeds.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('2003626e-a052-5e69-93b3-83db3212d989', '837a7a75-3497-5bc2-ad87-da1342d1c634', 0, 'VM escape', false, 'VM escape is breaking out of a guest to the host.'),
  ('beec3b0c-3831-5dc4-afb9-29ec9b23ab94', '837a7a75-3497-5bc2-ad87-da1342d1c634', 1, 'VM sprawl', true, null),
  ('814c3039-a529-50d8-aef3-40bcb0076a85', '837a7a75-3497-5bc2-ad87-da1342d1c634', 2, 'Hypervisor hardening', false, 'Hardening reduces the attack surface; it is a solution, not the problem described.'),
  ('f9bd63cd-d627-534c-ae5b-bbbce139d689', '837a7a75-3497-5bc2-ad87-da1342d1c634', 3, 'Microsegmentation', false, 'Microsegmentation is a network control, not an inventory problem.')
insert into public.question_topics (question_id, topic_id) values ('837a7a75-3497-5bc2-ad87-da1342d1c634', 'virtualization'), ('837a7a75-3497-5bc2-ad87-da1342d1c634', 'asset-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 'Which statement BEST describes a security difference between containers and virtual machines?', 3, 'hard', 'single', 1, 'Containers are lightweight because they share the host kernel. That efficiency means isolation is weaker than a VM''s, where each guest has its own kernel on top of a hypervisor.', 'Shared kernel = containers. Separate kernels on a hypervisor = VMs.', 'Containers are apartments sharing one foundation; VMs are separate houses.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7495854f-ac1d-57ec-b7b8-9d482e6e4ef4', '95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 0, 'Containers share the host operating system kernel, so a kernel vulnerability can affect every container on the host', true, null),
  ('3ce0df0f-dfad-51dd-84c0-719fc578746c', '95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 1, 'Each container runs its own full guest operating system', false, 'Containers package an application and its dependencies, not a full operating system.'),
  ('db8931de-5bc1-51c8-af2b-396ec8d21cd1', '95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 2, 'Virtual machines share one kernel, while containers each have their own', false, 'This reverses the relationship: VMs each have their own kernel.'),
  ('c55fa1a8-8d01-5d8f-93e5-3b3a888b52a9', '95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 3, 'Containers cannot be isolated from each other in any way', false, 'Containers use namespaces and control groups for isolation; it is weaker than VMs but not absent.')
insert into public.question_topics (question_id, topic_id) values ('95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 'virtualization'), ('95426e6d-0cbb-5ae8-b97c-35e31a5dff8d', 'cloud-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b641dd65-81e5-5532-b98f-cd25fe13f8ab', 'Administrators must manage servers in a restricted network zone without exposing management ports to the rest of the network. Which solution provides a single hardened and monitored entry point for this administration?', 3, 'medium', 'single', 1, 'A jump server (jump box or bastion host) is the only system allowed to connect into the secure zone. Admins connect to it first, which centralizes access control and logging.', 'Single controlled path for admins into a secure zone = jump server.', 'Jump through the one hardened door.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b9113985-b190-55ff-8fe4-843c7d87c6be', 'b641dd65-81e5-5532-b98f-cd25fe13f8ab', 0, 'Forward proxy', false, 'A forward proxy mediates users'' outbound web traffic.'),
  ('b4e542d5-e6a0-567d-a093-a3a65109684e', 'b641dd65-81e5-5532-b98f-cd25fe13f8ab', 1, 'Jump server', true, null),
  ('b2682033-7d44-5622-ad48-a70c3a96c803', 'b641dd65-81e5-5532-b98f-cd25fe13f8ab', 2, 'Load balancer', false, 'A load balancer distributes client traffic across servers.'),
  ('8c73a3b5-cab5-5089-9f19-da01bdd23f90', 'b641dd65-81e5-5532-b98f-cd25fe13f8ab', 3, 'Honeypot', false, 'A honeypot is a decoy that attracts attackers.')
insert into public.question_topics (question_id, topic_id) values ('b641dd65-81e5-5532-b98f-cd25fe13f8ab', 'network-security'), ('b641dd65-81e5-5532-b98f-cd25fe13f8ab', 'segmentation') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 'Which device inspects HTTP and HTTPS traffic to protect a web application from attacks such as SQL injection and cross-site scripting?', 3, 'easy', 'single', 1, 'A WAF understands application-layer web traffic and blocks malicious patterns targeting web applications.', 'Protecting a web app from web attacks = WAF.', 'WAF guards the web app''s front door.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('aeda21fb-4191-5513-a106-1639f99392ca', 'a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 0, 'Web application firewall (WAF)', true, null),
  ('2efa65e0-0354-5fd7-80f8-760bbc8f4e6e', 'a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 1, 'Stateless packet filter', false, 'Packet filters look at addresses and ports, not the contents of web requests.'),
  ('90fb8f12-dbf1-5d2c-afa9-9be76a88eed2', 'a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 2, 'Network-based IDS on a SPAN port', false, 'An IDS on a SPAN port can alert but cannot block, and it is not specific to web applications.'),
  ('b97c4ac3-557d-53d4-bbe3-22ca931fdab6', 'a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 3, 'Layer 2 switch', false, 'A switch forwards frames and does not inspect application payloads.')
insert into public.question_topics (question_id, topic_id) values ('a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 'firewalls'), ('a8b4ccd0-1985-51d6-bb09-a8f790d463ad', 'application-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d084115a-815c-5dd9-8962-66de676d84cd', 'How does a stateful firewall differ from a stateless packet filter?', 3, 'medium', 'single', 1, 'A stateful firewall keeps a state table of connections, so it knows whether a packet belongs to a legitimate established session.', 'Remembers connections = stateful. Judges each packet alone = stateless.', 'Stateful firewalls have a memory.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('47b8918d-43d5-557a-a3f4-7220c88db0e1', 'd084115a-815c-5dd9-8962-66de676d84cd', 0, 'It tracks active connections and automatically allows return traffic for established sessions', true, null),
  ('53d1d65d-75ae-5a53-be3e-7d318c17e428', 'd084115a-815c-5dd9-8962-66de676d84cd', 1, 'It decrypts all TLS traffic by default', false, 'TLS inspection is a separate feature and is not implied by stateful filtering.'),
  ('bc016012-4987-581b-9179-63cdd17b2251', 'd084115a-815c-5dd9-8962-66de676d84cd', 2, 'It can only filter by MAC address', false, 'Stateful firewalls work mainly with IP addresses, ports, and connection state.'),
  ('2059937a-6fff-5783-a312-f8a149dbb0ea', 'd084115a-815c-5dd9-8962-66de676d84cd', 3, 'It evaluates each packet in isolation with no memory of prior packets', false, 'Evaluating packets in isolation describes a stateless filter.')
insert into public.question_topics (question_id, topic_id) values ('d084115a-815c-5dd9-8962-66de676d84cd', 'firewalls'), ('d084115a-815c-5dd9-8962-66de676d84cd', 'network-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('eb6aa9b4-18fc-50a8-880b-7a1239285377', 'A firewall has these rules in order: 1) Allow TCP 443 from any to 10.0.0.5. 2) Deny any traffic from 203.0.113.0/24. 3) Deny all. A host at 203.0.113.50 can still reach 10.0.0.5 over HTTPS. Why?', 3, 'hard', 'single', 1, 'Firewall rules are usually evaluated in order and the first match wins. To block that subnet, the deny rule must be placed above the broad allow rule.', 'Unexpected traffic allowed? Check rule order: specific denies must come before broad allows.', 'First match wins.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8077da15-5918-5b1f-8407-a77e7016526e', 'eb6aa9b4-18fc-50a8-880b-7a1239285377', 0, 'The implicit deny rule is disabled', false, 'An explicit ''deny all'' is present, and it is never reached for this traffic anyway.'),
  ('e6ae6832-f398-504d-90b1-05da577ed771', 'eb6aa9b4-18fc-50a8-880b-7a1239285377', 1, 'Rules are processed top-down, and rule 1 matches the traffic before the deny rule is evaluated', true, null),
  ('e12b9d75-a64e-5c03-9cf1-57dd26cdc140', 'eb6aa9b4-18fc-50a8-880b-7a1239285377', 2, 'Stateful inspection bypasses deny rules', false, 'Stateful inspection tracks connections; it does not override rule order.'),
  ('2a5743ff-2f9f-564d-a3d6-33edd529bcdc', 'eb6aa9b4-18fc-50a8-880b-7a1239285377', 3, 'The /24 subnet mask does not include 203.0.113.50', false, '203.0.113.50 is inside 203.0.113.0/24.')
insert into public.question_topics (question_id, topic_id) values ('eb6aa9b4-18fc-50a8-880b-7a1239285377', 'firewalls') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('c4401157-8321-58eb-9ef2-b60e706b26e8', 'What is the key difference between an intrusion detection system (IDS) and an intrusion prevention system (IPS)?', 3, 'easy', 'single', 1, 'An IPS sits in the traffic path so it can drop or reset malicious sessions. An IDS typically watches a copy of traffic and raises alerts.', 'Inline + block = IPS. Passive + alert = IDS.', 'Detection tells you; prevention stops it.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('51db21be-6e59-5bf0-88be-8779723dc6a0', 'c4401157-8321-58eb-9ef2-b60e706b26e8', 0, 'An IPS is placed inline and can block malicious traffic; an IDS monitors and alerts', true, null),
  ('0bc1d5d1-e840-5c0f-a4d1-3fb6263fcc0f', 'c4401157-8321-58eb-9ef2-b60e706b26e8', 1, 'An IDS is always host-based and an IPS is always network-based', false, 'Both come in host-based and network-based forms.'),
  ('ec7506d9-b5a7-5726-aa46-2a373d7c3d0d', 'c4401157-8321-58eb-9ef2-b60e706b26e8', 2, 'An IDS uses signatures, while an IPS can only use anomaly detection', false, 'Both can use signature-based and anomaly-based detection.'),
  ('ea69fae0-eb0b-5954-886c-c5e5235f811e', 'c4401157-8321-58eb-9ef2-b60e706b26e8', 3, 'An IPS only analyzes logs after an incident', false, 'An IPS acts in real time; it does not only review logs.')
insert into public.question_topics (question_id, topic_id) values ('c4401157-8321-58eb-9ef2-b60e706b26e8', 'ids-ips') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f0589c23-554f-56f2-8b6d-70358ef66be0', 'Which detection method compares activity against a baseline of normal behavior and can therefore detect previously unknown attacks?', 3, 'medium', 'single', 1, 'Anomaly (behavior-based) detection flags deviations from a learned baseline, which can reveal zero-day activity but also tends to produce more false positives.', 'Baseline + deviation = anomaly-based. Known patterns = signature-based.', 'Anomaly spots the odd one out.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d4cf8cd5-286b-5dd4-b6c3-d50737f37a0e', 'f0589c23-554f-56f2-8b6d-70358ef66be0', 0, 'Signature-based', false, 'Signature-based detection only recognizes known attack patterns.'),
  ('bf89b70f-eee8-569e-ad3e-9b826bf92523', 'f0589c23-554f-56f2-8b6d-70358ef66be0', 1, 'Anomaly-based', true, null),
  ('fb8a7a42-ac22-5db2-a771-6088203115ab', 'f0589c23-554f-56f2-8b6d-70358ef66be0', 2, 'Hash-based', false, 'Hash matching identifies known files.'),
  ('f9dbe969-5f0c-5a3b-a008-bad30139f9f6', 'f0589c23-554f-56f2-8b6d-70358ef66be0', 3, 'Allow-list-based', false, 'An allow list permits approved items; it does not model normal behavior.')
insert into public.question_topics (question_id, topic_id) values ('f0589c23-554f-56f2-8b6d-70358ef66be0', 'ids-ips'), ('f0589c23-554f-56f2-8b6d-70358ef66be0', 'logging') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('8a5e111e-f512-56a9-8aca-a0f2806d0710', 'During a holiday sale, an inline IPS blocks legitimate customer checkout requests after misidentifying them as attacks. What type of result is this?', 3, 'medium', 'single', 1, 'A false positive is benign activity incorrectly flagged as malicious. For an inline IPS, false positives block legitimate business, so tuning is essential.', 'Good traffic flagged as bad = false positive. Bad traffic missed = false negative.', 'False positive: the alarm cried wolf.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d2d7bb2d-5712-5699-9322-1e574d29b1e0', '8a5e111e-f512-56a9-8aca-a0f2806d0710', 0, 'False positive', true, null),
  ('f96df9d0-a193-5c77-8861-e869781ccfbf', '8a5e111e-f512-56a9-8aca-a0f2806d0710', 1, 'False negative', false, 'A false negative is a real attack that goes undetected.'),
  ('9d4ddb26-a821-533b-8bee-fd1dcc3bd3c4', '8a5e111e-f512-56a9-8aca-a0f2806d0710', 2, 'True positive', false, 'A true positive is a real attack correctly detected.'),
  ('fa975952-3919-5024-82a4-116d49f5849c', '8a5e111e-f512-56a9-8aca-a0f2806d0710', 3, 'True negative', false, 'A true negative is benign activity correctly allowed.')
insert into public.question_topics (question_id, topic_id) values ('8a5e111e-f512-56a9-8aca-a0f2806d0710', 'ids-ips'), ('8a5e111e-f512-56a9-8aca-a0f2806d0710', 'vulnerability-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 'Which network zone hosts public-facing services such as web servers while keeping them separated from the internal network?', 3, 'easy', 'single', 1, 'A screened subnet sits between the internet and the internal network, allowing public access to specific services while limiting access inward.', 'Public servers kept apart from internal systems = screened subnet.', 'The DMZ is the lobby, not the office.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8f0f6133-9f4d-5c83-8eea-39106f710acc', '347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 0, 'Intranet', false, 'The intranet is the internal network the DMZ protects.'),
  ('a367f3dd-e265-50ba-a825-f9e43625a405', '347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 1, 'Screened subnet (DMZ)', true, null),
  ('6eca96bd-f745-5955-8744-8a8ef8a61a81', '347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 2, 'Air-gapped network', false, 'An air-gapped network has no connection at all, so it cannot host public services.'),
  ('55c1274f-1df4-59c3-9464-9cb5e732f3c6', '347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 3, 'Management VLAN', false, 'A management VLAN carries administrative traffic and should never be public.')
insert into public.question_topics (question_id, topic_id) values ('347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 'segmentation'), ('347ba58c-35ef-5601-bd2a-4cd9b8b9ffb1', 'network-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d9efc509-f83b-52ce-a2d9-94a0604245f0', 'A hospital wants to ensure that if a guest Wi-Fi device is compromised, it cannot reach medical devices. Staff laptops still need access to both the internet and clinical systems. What is the BEST approach?', 3, 'hard', 'single', 1, 'Segmentation with controlled inter-segment rules limits lateral movement. Guests reach only the internet, medical devices are isolated, and staff are allowed only what they need.', 'Limit what a compromised device can reach = segmentation with rules between segments.', 'Separate the rooms, lock the doors between them.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d26549e0-3bb1-5fd9-8166-98afc6d8acfd', 'd9efc509-f83b-52ce-a2d9-94a0604245f0', 0, 'Enable WPA3 on the guest network only', false, 'WPA3 protects the wireless link but does not stop a compromised guest from reaching internal systems.'),
  ('134c455d-fb94-5eb8-bf0e-11d2023f9279', 'd9efc509-f83b-52ce-a2d9-94a0604245f0', 1, 'Place guests, staff, and medical devices on separate segments with firewall rules controlling traffic between them', true, null),
  ('f69e5e91-c2c9-5dc2-acbf-7abbaa0bb91f', 'd9efc509-f83b-52ce-a2d9-94a0604245f0', 2, 'Keep a single flat network and add an IDS', false, 'A flat network allows lateral movement; an IDS only alerts after the fact.'),
  ('b14056dc-3781-5601-b90c-4cf42e9036b1', 'd9efc509-f83b-52ce-a2d9-94a0604245f0', 3, 'Hide the SSID of the guest network', false, 'Hiding an SSID is not a security control; the network can still be discovered.')
insert into public.question_topics (question_id, topic_id) values ('d9efc509-f83b-52ce-a2d9-94a0604245f0', 'segmentation'), ('d9efc509-f83b-52ce-a2d9-94a0604245f0', 'network-security'), ('d9efc509-f83b-52ce-a2d9-94a0604245f0', 'iot-ics') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('75ad4728-42af-523b-abab-9b79aa66f5e0', 'A classified research system has no physical or wireless connection to any other network. What is this approach called?', 3, 'easy', 'single', 1, 'An air gap physically isolates a system so no network path exists. Data must be moved manually, which introduces removable-media risks that must be controlled.', 'No connection at all = air gap.', 'Nothing but air between it and everything else.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('4af870df-ea1e-50ff-9417-9a5f3ebedbc3', '75ad4728-42af-523b-abab-9b79aa66f5e0', 0, 'Microsegmentation', false, 'Microsegmentation applies fine-grained network policies but systems remain connected.'),
  ('4ca04c56-8143-5a83-bc63-21452c5bf93b', '75ad4728-42af-523b-abab-9b79aa66f5e0', 1, 'Air gap', true, null),
  ('be65a2fc-f873-5746-a662-d7c45b92074f', '75ad4728-42af-523b-abab-9b79aa66f5e0', 2, 'Screened subnet', false, 'A screened subnet is connected to both the internet and the internal network.'),
  ('f5c11307-dcde-53d1-a333-ec9722d61543', '75ad4728-42af-523b-abab-9b79aa66f5e0', 3, 'Logical segmentation with VLANs', false, 'VLANs separate traffic logically on shared hardware.')
insert into public.question_topics (question_id, topic_id) values ('75ad4728-42af-523b-abab-9b79aa66f5e0', 'segmentation') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('5d212444-699d-574b-ac72-27f1ced705ce', 'A remote employee''s VPN sends only traffic destined for corporate networks through the tunnel, while general internet browsing goes directly to the internet. What is this configuration?', 3, 'medium', 'single', 1, 'A split tunnel routes only corporate-bound traffic through the VPN. It saves bandwidth but means internet traffic bypasses corporate security inspection.', 'Some traffic in the tunnel, some outside = split tunnel.', 'Split tunnel splits the traffic.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a7b24441-69ab-586e-b046-8aea42aff2cf', '5d212444-699d-574b-ac72-27f1ced705ce', 0, 'Full tunnel', false, 'A full tunnel sends all traffic through the VPN.'),
  ('574ada20-5b19-5d6a-a046-16a10bc440c6', '5d212444-699d-574b-ac72-27f1ced705ce', 1, 'Split tunnel', true, null),
  ('f23d3cba-f3ad-5b76-b041-55e2858eaf45', '5d212444-699d-574b-ac72-27f1ced705ce', 2, 'Site-to-site VPN', false, 'Site-to-site VPNs connect entire networks, not individual remote users.'),
  ('82c781f7-1eff-5509-ad69-2a1ef77e5496', '5d212444-699d-574b-ac72-27f1ced705ce', 3, 'Clientless VPN', false, 'A clientless VPN uses a browser-based portal rather than a full client.')
insert into public.question_topics (question_id, topic_id) values ('5d212444-699d-574b-ac72-27f1ced705ce', 'vpn') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('19393cf3-2499-504a-9d87-51788c9363fd', 'Which IPsec component provides confidentiality through encryption in addition to integrity and authentication of the payload?', 3, 'hard', 'single', 1, 'ESP encrypts the payload and can also provide integrity and authentication. AH provides integrity and authentication only, with no encryption.', 'Need encryption in IPsec? ESP. AH = authentication only.', 'ESP encrypts; AH just authenticates.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('4949b0fa-a721-50b6-ba0d-21231b1cb203', '19393cf3-2499-504a-9d87-51788c9363fd', 0, 'Authentication Header (AH)', false, 'AH provides integrity and origin authentication but no confidentiality.'),
  ('278afb94-a8e9-5a59-859b-f52d70a28e87', '19393cf3-2499-504a-9d87-51788c9363fd', 1, 'Encapsulating Security Payload (ESP)', true, null),
  ('af411d42-c174-5a7b-a866-3b398884d72c', '19393cf3-2499-504a-9d87-51788c9363fd', 2, 'Internet Key Exchange (IKE)', false, 'IKE negotiates security associations and exchanges keys; it does not protect the payload itself.'),
  ('bb93e39a-3392-5eb7-8f37-d39978e80652', '19393cf3-2499-504a-9d87-51788c9363fd', 3, 'Generic Routing Encapsulation (GRE)', false, 'GRE is a tunneling protocol without built-in encryption.')
insert into public.question_topics (question_id, topic_id) values ('19393cf3-2499-504a-9d87-51788c9363fd', 'vpn'), ('19393cf3-2499-504a-9d87-51788c9363fd', 'encryption'), ('19393cf3-2499-504a-9d87-51788c9363fd', 'secure-protocols') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ae75d85a-8d9d-5b10-bec7-833b32f39f34', 'Data that is actively being processed in a server''s memory is in which state?', 3, 'easy', 'single', 1, 'Data in use is being accessed or processed in RAM or the CPU. It is often unencrypted at that point, which is why secure enclaves exist.', 'Rest = stored. Transit = moving. Use = processing in memory.', 'In use means in RAM.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('d2722f4a-7a8d-5c1a-8e37-508fd05dd3df', 'ae75d85a-8d9d-5b10-bec7-833b32f39f34', 0, 'Data at rest', false, 'Data at rest is stored on disks, databases, or backups.'),
  ('9c051826-e80f-5f1b-8672-8d57403d0adb', 'ae75d85a-8d9d-5b10-bec7-833b32f39f34', 1, 'Data in transit', false, 'Data in transit is moving across a network.'),
  ('e8222793-2c2b-5021-9181-1489d4016222', 'ae75d85a-8d9d-5b10-bec7-833b32f39f34', 2, 'Data in use', true, null),
  ('3e780887-b48e-54a1-98fd-e84c04804924', 'ae75d85a-8d9d-5b10-bec7-833b32f39f34', 3, 'Data in escrow', false, 'Escrow refers to storing keys with a third party, not a data state.')
insert into public.question_topics (question_id, topic_id) values ('ae75d85a-8d9d-5b10-bec7-833b32f39f34', 'data-protection') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 'A European company must ensure customer data is stored only in data centers physically located within the EU because of local laws. Which concept does this describe?', 3, 'medium', 'single', 1, 'Data sovereignty means data is subject to the laws of the country where it is stored, so organizations must control where their data physically resides.', 'Where data is stored + which country''s laws apply = data sovereignty.', 'The data is subject to its sovereign''s laws.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a29a3913-3241-5c98-8791-b04693f8a872', 'b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 0, 'Data classification', false, 'Classification labels data by sensitivity; it does not govern location.'),
  ('295d55d3-a5ce-5164-b1bf-c35629d5b052', 'b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 1, 'Data sovereignty', true, null),
  ('28596b7b-777f-5c94-b406-8cde398a4a53', 'b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 2, 'Data masking', false, 'Masking hides parts of data values.'),
  ('7e3058f8-3255-5fad-a498-d3d16b9a6c4b', 'b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 3, 'Geofencing', false, 'Geofencing controls device behavior based on location.')
insert into public.question_topics (question_id, topic_id) values ('b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 'data-protection'), ('b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 'compliance'), ('b1dc828e-a398-51bc-82ee-c9a2fceb0d31', 'cloud-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 'Which technology distributes incoming requests across multiple servers to improve availability and performance?', 3, 'easy', 'single', 1, 'A load balancer spreads traffic across a pool of servers and removes failed servers from rotation, improving capacity and availability.', 'Spread requests across servers = load balancer.', 'Balance the load, keep the lights on.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('3df50958-57e9-5e60-8f27-b9cb384ba5a3', '4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 0, 'Load balancer', true, null),
  ('3dd137fa-8c0a-53de-b4c8-a5eb5f815d3b', '4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 1, 'Forward proxy', false, 'A forward proxy mediates outbound client requests.'),
  ('dded0229-13e1-5e52-b8b4-a1c437fd3edb', '4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 2, 'Jump server', false, 'A jump server provides controlled administrative access.'),
  ('ee5e9806-0bd1-58c9-a70f-284b4f1ed265', '4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 3, 'Network tap', false, 'A network tap copies traffic for monitoring.')
insert into public.question_topics (question_id, topic_id) values ('4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 'resilience'), ('4dc939fc-9fc9-5c0b-a17a-71e8db4d9005', 'network-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('39166100-a9ce-5463-a9bd-f9e383808e10', 'A company requires its customer web application to stay online even if an entire data center is lost. Which design BEST meets this requirement?', 3, 'hard', 'single', 1, 'Surviving the loss of a whole site requires redundancy in another location. Active-active sites let traffic shift automatically when one site fails.', 'Match the redundancy to the failure: disk = RAID, power = UPS/generator, site = geographic redundancy.', 'To survive a site loss, be in two places at once.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b1f6f953-ee1d-5364-9cfe-d0b6affb9f2c', '39166100-a9ce-5463-a9bd-f9e383808e10', 0, 'RAID 5 storage on the web server', false, 'RAID protects against disk failure within one server, not site loss.'),
  ('50a8812f-fee0-584d-9779-3d6e3ffa972a', '39166100-a9ce-5463-a9bd-f9e383808e10', 1, 'Active-active deployment across geographically separate sites with global load balancing', true, null),
  ('31ef7ee2-e510-5598-b5d8-86053af2a3e0', '39166100-a9ce-5463-a9bd-f9e383808e10', 2, 'Nightly tape backups stored in the same data center', false, 'Backups in the same building are lost with the site and restoring takes time.'),
  ('fc37e23b-d7ae-551f-b60d-ef52eca2199f', '39166100-a9ce-5463-a9bd-f9e383808e10', 3, 'An uninterruptible power supply for the server rack', false, 'A UPS covers short power interruptions, not the loss of the site.')
insert into public.question_topics (question_id, topic_id) values ('39166100-a9ce-5463-a9bd-f9e383808e10', 'resilience'), ('39166100-a9ce-5463-a9bd-f9e383808e10', 'disaster-recovery') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('55f697a6-9e44-5463-b051-11191670b7d2', 'A company runs a full backup every Sunday and, Monday through Saturday, backs up all changes made since the last full backup. A failure occurs Friday before that day''s backup. How many backup sets are needed to restore?', 3, 'medium', 'single', 1, 'Backing up all changes since the last full backup is a differential backup. Restoring needs only the last full backup plus the most recent differential.', 'Differential = full + last differential. Incremental = full + every incremental since.', 'Differential grows daily but restores in two steps.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('07642d70-0786-5bda-99d3-c97e046e2ae9', '55f697a6-9e44-5463-b051-11191670b7d2', 0, 'One: Thursday''s backup', false, 'A differential only contains changes since Sunday; it needs the full backup as a base.'),
  ('d29fb93b-02f9-539a-979b-95a2ae47f10a', '55f697a6-9e44-5463-b051-11191670b7d2', 1, 'Two: Sunday''s full backup and Thursday''s backup', true, null),
  ('e317fe89-0683-516a-a843-64498cfc30f1', '55f697a6-9e44-5463-b051-11191670b7d2', 2, 'Five: Sunday''s full backup and each daily backup through Thursday', false, 'Restoring every daily set is required for incremental backups, not differentials.'),
  ('5cf7e792-1f57-57e8-9e20-d6a6d389e7e2', '55f697a6-9e44-5463-b051-11191670b7d2', 3, 'Six: every backup since Sunday plus Friday''s', false, 'Friday''s backup was never taken.')
insert into public.question_topics (question_id, topic_id) values ('55f697a6-9e44-5463-b051-11191670b7d2', 'backups'), ('55f697a6-9e44-5463-b051-11191670b7d2', 'disaster-recovery') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('312d4f85-75db-57c9-908d-4704672b975e', 'Ransomware encrypted a company''s file servers and also encrypted the backups stored on a network share the servers could write to. Which backup strategy would BEST have prevented losing the backups?', 3, 'hard', 'single', 1, 'Backups that cannot be modified or reached from production systems survive ransomware. Immutability and offline copies break the attacker''s path to the backups.', 'Ransomware + backups also encrypted = need immutable, offline, or logically separated backups.', 'If malware can write to it, malware can ruin it.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('10f5b452-b3b2-59ed-b99a-77d002e0e887', '312d4f85-75db-57c9-908d-4704672b975e', 0, 'More frequent incremental backups to the same share', false, 'More frequent backups to a writable share would simply be encrypted too.'),
  ('d905cd1d-f8a6-5bc4-a0b8-864cbb219811', '312d4f85-75db-57c9-908d-4704672b975e', 1, 'Immutable or offline (air-gapped) backup copies', true, null),
  ('ecbdc4df-c528-53b8-b37d-c2021b49c704', '312d4f85-75db-57c9-908d-4704672b975e', 2, 'Replacing the storage with a RAID 10 array', false, 'RAID provides redundancy against disk failure, not protection from malicious encryption.'),
  ('f7b589de-0aba-5efa-acc5-222fc615d6ce', '312d4f85-75db-57c9-908d-4704672b975e', 3, 'Snapshots stored on the same volume as the data', false, 'Snapshots on the same volume can be deleted or encrypted along with the data.')
insert into public.question_topics (question_id, topic_id) values ('312d4f85-75db-57c9-908d-4704672b975e', 'backups'), ('312d4f85-75db-57c9-908d-4704672b975e', 'malware'), ('312d4f85-75db-57c9-908d-4704672b975e', 'resilience') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3419eee7-a74c-59a3-be07-72a20c7711ae', 'Which recovery site is fully equipped with hardware, software, and near-real-time data so operations can resume within minutes to hours?', 3, 'easy', 'single', 1, 'A hot site mirrors production and can take over almost immediately. It is the fastest and most expensive option.', 'Fastest recovery, highest cost = hot. Cheapest, slowest = cold.', 'Hot is ready now; cold starts from scratch.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b8adecb6-b83d-5964-9cca-627ae790198e', '3419eee7-a74c-59a3-be07-72a20c7711ae', 0, 'Cold site', false, 'A cold site provides space and power but little or no equipment, so recovery takes the longest.'),
  ('0b30d1b6-e441-5fa6-ad81-258c2a6660f5', '3419eee7-a74c-59a3-be07-72a20c7711ae', 1, 'Warm site', false, 'A warm site has some equipment but requires data restoration and setup.'),
  ('ebfdf84c-be7c-56ce-ae35-4081d18748d6', '3419eee7-a74c-59a3-be07-72a20c7711ae', 2, 'Hot site', true, null),
  ('afa6e967-65f9-5ada-b132-80032641abe4', '3419eee7-a74c-59a3-be07-72a20c7711ae', 3, 'Mobile site', false, 'A mobile site is a portable facility; readiness depends on how it is equipped.')
insert into public.question_topics (question_id, topic_id) values ('3419eee7-a74c-59a3-be07-72a20c7711ae', 'disaster-recovery'), ('3419eee7-a74c-59a3-be07-72a20c7711ae', 'business-impact-analysis') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('612eb23b-fcbd-5381-b8ba-f32350a12861', 'Which TWO statements describe a warm recovery site?', 3, 'medium', 'multiple', 2, 'A warm site is a middle ground: equipment and connectivity exist, but current data must be loaded and systems configured before cutover.', 'Warm = partially ready; expect restore time of hours to days.', 'Warm needs a little heating up.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('db14db79-58a4-5367-8ea1-c54b52ae8db8', '612eb23b-fcbd-5381-b8ba-f32350a12861', 0, 'Some hardware and network connectivity are already in place', true, null),
  ('593c2797-81bf-538d-b1f0-27cce392b5d2', '612eb23b-fcbd-5381-b8ba-f32350a12861', 1, 'Data must be restored from backups before operations resume', true, null),
  ('7d6ba20f-7fa2-5f28-912f-cafdd7ebde06', '612eb23b-fcbd-5381-b8ba-f32350a12861', 2, 'Data is continuously mirrored in real time', false, 'Real-time mirroring describes a hot site.'),
  ('33b9089e-e2f7-591f-a7da-6d19540baa63', '612eb23b-fcbd-5381-b8ba-f32350a12861', 3, 'It provides only an empty building with power', false, 'An empty building with power describes a cold site.'),
  ('6a14e645-3bd9-582f-8c57-7249967821a6', '612eb23b-fcbd-5381-b8ba-f32350a12861', 4, 'It is the fastest recovery option available', false, 'The fastest option is a hot site.')
insert into public.question_topics (question_id, topic_id) values ('612eb23b-fcbd-5381-b8ba-f32350a12861', 'disaster-recovery') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('fa22711e-0fc4-5de3-9937-ee83668e452b', 'A water treatment plant''s SCADA system uses legacy protocols with no authentication and cannot be replaced this year. What is the BEST way to reduce risk?', 3, 'medium', 'single', 1, 'ICS systems often cannot be changed, so risk is reduced by isolating them, allowing only required connections, and monitoring for anomalies.', 'Legacy ICS that cannot be changed = segment, restrict, monitor.', 'Critical infrastructure goes behind the strongest fence.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f422d70c-10a7-578d-b72d-ae6991dc28c8', 'fa22711e-0fc4-5de3-9937-ee83668e452b', 0, 'Connect it directly to the internet so the vendor can patch it remotely', false, 'Direct internet exposure of unauthenticated control systems is extremely dangerous.'),
  ('bdcd7b19-9f2d-58ff-bb13-590f35a11044', 'fa22711e-0fc4-5de3-9937-ee83668e452b', 1, 'Segment the ICS network and strictly control and monitor all traffic to it', true, null),
  ('8d2d9690-059e-5c97-a2d4-79919a43542f', 'fa22711e-0fc4-5de3-9937-ee83668e452b', 2, 'Install consumer antivirus software on each PLC', false, 'PLCs generally cannot run consumer antivirus, and it would not fix protocol weaknesses.'),
  ('1257eece-064f-5711-baea-58437cd7e56e', 'fa22711e-0fc4-5de3-9937-ee83668e452b', 3, 'Disable logging on the control network to reduce latency', false, 'Removing logs eliminates the visibility needed to detect attacks.')
insert into public.question_topics (question_id, topic_id) values ('fa22711e-0fc4-5de3-9937-ee83668e452b', 'iot-ics'), ('fa22711e-0fc4-5de3-9937-ee83668e452b', 'segmentation'), ('fa22711e-0fc4-5de3-9937-ee83668e452b', 'mitigation-techniques') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('58712fd6-701a-5c6d-aceb-5b89e88b722d', 'Which device provides short-term battery power to keep systems running through a brief outage or until a generator starts?', 3, 'easy', 'single', 1, 'A UPS supplies battery power instantly when utility power fails, bridging the gap until power returns or a generator takes over.', 'Brief outage bridge = UPS. Long outage = generator.', 'UPS keeps you up for a few minutes.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('279950bf-2813-5df7-a7da-638a16e7790d', '58712fd6-701a-5c6d-aceb-5b89e88b722d', 0, 'Uninterruptible power supply (UPS)', true, null),
  ('2cea52bc-e88a-5cd9-afe8-c31144fef782', '58712fd6-701a-5c6d-aceb-5b89e88b722d', 1, 'Power distribution unit (PDU)', false, 'A PDU distributes power to equipment in a rack but does not store it.'),
  ('a7fd6722-a2ef-5385-808a-731c3a50cf38', '58712fd6-701a-5c6d-aceb-5b89e88b722d', 2, 'Surge protector', false, 'A surge protector guards against voltage spikes, not outages.'),
  ('d549c094-c22d-5a23-850d-8e103dd130c7', '58712fd6-701a-5c6d-aceb-5b89e88b722d', 3, 'Load balancer', false, 'A load balancer distributes network traffic.')
insert into public.question_topics (question_id, topic_id) values ('58712fd6-701a-5c6d-aceb-5b89e88b722d', 'resilience') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d8deb3b4-4b57-5be4-80f4-2bda795aa713', 'An employee resigns effective today. Which identity lifecycle process should occur immediately to prevent continued access?', 4, 'easy', 'single', 1, 'Deprovisioning disables or removes a user''s accounts and access when they leave or change roles. Delays leave orphaned accounts that attackers or former staff can abuse.', 'Joiner = provisioning. Leaver = deprovisioning. Mover = adjust access.', 'Out the door, access no more.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('3369b664-068f-5932-89f9-f169681e050b', 'd8deb3b4-4b57-5be4-80f4-2bda795aa713', 0, 'Provisioning', false, 'Provisioning creates accounts and grants access for new users.'),
  ('20087412-69fe-5f0e-961c-98d38cd2fa5f', 'd8deb3b4-4b57-5be4-80f4-2bda795aa713', 1, 'Deprovisioning', true, null),
  ('1cbd9965-be6e-5176-9016-536890b1fd25', 'd8deb3b4-4b57-5be4-80f4-2bda795aa713', 2, 'Attestation', false, 'Attestation periodically confirms that access is still appropriate.'),
  ('c484901d-55f8-57c1-a5f5-4b7f631f3c69', 'd8deb3b4-4b57-5be4-80f4-2bda795aa713', 3, 'Federation', false, 'Federation establishes trust between identity systems of different organizations.')
insert into public.question_topics (question_id, topic_id) values ('d8deb3b4-4b57-5be4-80f4-2bda795aa713', 'iam') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('c0c5a246-4de6-55e7-9a22-59628153a1b6', 'An employee who has moved through three departments still holds the access rights from each previous role. Which control BEST addresses this problem?', 4, 'medium', 'single', 1, 'Accumulating permissions over time is privilege creep. Regular access reviews let managers confirm and remove access that is no longer needed, enforcing least privilege.', 'Leftover permissions from old roles = privilege creep. Fix with access reviews.', 'Review access or permissions creep up on you.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('0ce38f97-bcef-5dde-809a-394367f51b1a', 'c0c5a246-4de6-55e7-9a22-59628153a1b6', 0, 'Multifactor authentication', false, 'MFA strengthens login but does not remove excessive permissions.'),
  ('46139006-f9c8-5ed1-abe5-49765bcec0a6', 'c0c5a246-4de6-55e7-9a22-59628153a1b6', 1, 'Periodic access reviews (recertification)', true, null),
  ('88cb1a1a-90ab-5a24-82d2-a9e6d4cb3770', 'c0c5a246-4de6-55e7-9a22-59628153a1b6', 2, 'Password expiration', false, 'Password expiration has no effect on what an account can access.'),
  ('acead8dc-4b47-5f2a-aceb-fa02c88d86b9', 'c0c5a246-4de6-55e7-9a22-59628153a1b6', 3, 'Account lockout thresholds', false, 'Lockout thresholds defend against password guessing.')
insert into public.question_topics (question_id, topic_id) values ('c0c5a246-4de6-55e7-9a22-59628153a1b6', 'iam'), ('c0c5a246-4de6-55e7-9a22-59628153a1b6', 'access-control-models') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3ddd3c27-ab31-5ad8-b932-672825be32c2', 'Administrators share a single domain administrator password stored in a spreadsheet. The company wants privileged credentials that are checked out on demand, rotated after each use, and fully audited. Which solution BEST fits?', 4, 'hard', 'single', 1, 'PAM solutions vault privileged credentials, grant temporary just-in-time access, rotate passwords automatically, and record sessions for accountability.', 'Vault + check-out + rotation + session recording = PAM.', 'PAM keeps the keys to the kingdom in a vault.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a233526a-6024-505b-aa6e-3c28873cb2c3', '3ddd3c27-ab31-5ad8-b932-672825be32c2', 0, 'Single sign-on', false, 'SSO reduces logins for regular users but does not manage shared privileged credentials.'),
  ('516aebcf-11ae-5147-8576-af09b571b005', '3ddd3c27-ab31-5ad8-b932-672825be32c2', 1, 'Privileged access management with a credential vault and just-in-time access', true, null),
  ('91dbf9d1-477d-545b-b801-5ffcf328f2dd', '3ddd3c27-ab31-5ad8-b932-672825be32c2', 2, 'Federation with a partner identity provider', false, 'Federation extends identity trust across organizations.'),
  ('dc435720-c0f1-5ce7-a179-f1044810a3a3', '3ddd3c27-ab31-5ad8-b932-672825be32c2', 3, 'Self-service password reset', false, 'Self-service reset helps users recover their own passwords, not govern admin credentials.')
insert into public.question_topics (question_id, topic_id) values ('3ddd3c27-ab31-5ad8-b932-672825be32c2', 'iam'), ('3ddd3c27-ab31-5ad8-b932-672825be32c2', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f6687d68-ec65-53cc-89d9-284536aaa958', 'A user logs in with a password followed by a four-digit PIN. How many different authentication factor types are being used?', 4, 'easy', 'single', 1, 'A password and a PIN are both something you know. Multifactor authentication requires different factor types, such as something you know plus something you have.', 'Count factor categories, not credentials: know, have, are, somewhere you are.', 'Two secrets you know are still one factor.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('31766080-043a-5f44-aff0-14e4fd5466d0', 'f6687d68-ec65-53cc-89d9-284536aaa958', 0, 'One', true, null),
  ('c019df9d-df60-5762-abb7-4b68e88695ca', 'f6687d68-ec65-53cc-89d9-284536aaa958', 1, 'Two', false, 'Two items from the same category are still single-factor authentication.'),
  ('866bc206-f277-571b-bbbe-7b85ee92571d', 'f6687d68-ec65-53cc-89d9-284536aaa958', 2, 'Three', false, 'No possession or inherence factor is involved.'),
  ('41a4df11-8b4a-5462-add5-d07d1de873eb', 'f6687d68-ec65-53cc-89d9-284536aaa958', 3, 'It depends on the length of the PIN', false, 'Length does not change the factor type.')
insert into public.question_topics (question_id, topic_id) values ('f6687d68-ec65-53cc-89d9-284536aaa958', 'authentication'), ('f6687d68-ec65-53cc-89d9-284536aaa958', 'aaa') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 'Which multifactor authentication method is MOST resistant to phishing?', 4, 'medium', 'single', 1, 'FIDO2 keys cryptographically bind authentication to the legitimate site''s origin, so a look-alike phishing site cannot obtain a usable response.', 'Phishing-resistant MFA = FIDO2/WebAuthn (passkeys, security keys).', 'A security key checks the website before it answers.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f47c07ff-fad5-56a0-8442-6456ddf7f671', 'e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 0, 'One-time codes sent by SMS', false, 'SMS codes can be phished or intercepted through SIM swapping.'),
  ('6235ed80-fc17-58f7-bb73-f9611bd22ba4', 'e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 1, 'Codes sent by email', false, 'Email codes can be phished and depend on the mailbox''s security.'),
  ('f3c1c150-f4af-5f53-b18e-22ec11300404', 'e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 2, 'FIDO2/WebAuthn hardware security keys', true, null),
  ('1b20a5c1-5ea6-5900-bbc5-51fb78a9a526', 'e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 3, 'Time-based one-time password (TOTP) apps', false, 'TOTP codes can be entered on a fake site and relayed in real time by an attacker.')
insert into public.question_topics (question_id, topic_id) values ('e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 'authentication'), ('e4e61ef2-85fd-565c-8d5a-b24775aaa21d', 'social-engineering') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 'A biometric door system has a high false acceptance rate (FAR). What does this mean?', 4, 'medium', 'single', 1, 'FAR measures how often an impostor is accepted. A high FAR is a security problem; a high false rejection rate (FRR) is a usability problem.', 'FAR = bad actors accepted (security risk). FRR = good users rejected (annoyance). CER = where they meet.', 'False Acceptance lets the attacker in.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8f8bc4e0-e0bf-51b2-9839-a9a26f6a273d', '0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 0, 'Authorized users are frequently rejected', false, 'Rejecting authorized users is the false rejection rate.'),
  ('f597fdee-805e-5f4c-8c34-f45cd890b95d', '0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 1, 'Unauthorized users are incorrectly accepted', true, null),
  ('2b0d396f-e434-52e7-822e-1a4e030d7c2c', '0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 2, 'The system takes too long to scan', false, 'Scan speed is not measured by FAR.'),
  ('7b57ffe3-a1e1-5147-8c41-54e620878053', '0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 3, 'The system cannot store enough templates', false, 'Template storage capacity is unrelated to FAR.')
insert into public.question_topics (question_id, topic_id) values ('0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 'authentication'), ('0262b7cb-cc8d-5d81-96c2-a9ee052740bb', 'physical-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('4ab66416-946d-541e-aa93-0c3ce0445012', 'Which standard uses XML-based assertions so an identity provider can authenticate users for a separate service provider''s web application?', 4, 'medium', 'single', 1, 'SAML exchanges signed XML assertions between an identity provider and service provider, enabling web SSO across organizational boundaries.', 'XML assertions between IdP and SP = SAML.', 'SAML speaks XML.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('30ae55a5-f619-547d-9f36-1022f1888585', '4ab66416-946d-541e-aa93-0c3ce0445012', 0, 'SAML', true, null),
  ('4c2b8c40-126a-5f70-9f4d-9d094d607aa0', '4ab66416-946d-541e-aa93-0c3ce0445012', 1, 'RADIUS', false, 'RADIUS provides AAA for network access such as VPN and Wi-Fi.'),
  ('5d2c16bb-0ad4-5e3f-89f0-fd5072d15113', '4ab66416-946d-541e-aa93-0c3ce0445012', 2, 'Kerberos', false, 'Kerberos issues tickets within a single domain or realm.'),
  ('026d50c5-f3d6-5960-bb7d-e3a13675c345', '4ab66416-946d-541e-aa93-0c3ce0445012', 3, 'LDAP', false, 'LDAP queries and modifies directory services.')
insert into public.question_topics (question_id, topic_id) values ('4ab66416-946d-541e-aa93-0c3ce0445012', 'federation'), ('4ab66416-946d-541e-aa93-0c3ce0445012', 'sso') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e39c7a32-3e3e-5f60-b5b2-9a5172911743', 'A company wants employees to sign in to a partner''s supplier portal using their existing corporate credentials, without the partner ever storing those passwords. Which approach BEST meets this goal?', 4, 'hard', 'single', 1, 'Federation lets the partner trust authentication performed by the company''s identity provider (for example, via SAML or OpenID Connect). Passwords never leave the company.', 'Use your home credentials at another organization without sharing passwords = federation.', 'Federation: your IdP vouches for you.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('c8c0fb34-fe33-5988-929d-627ac3c70851', 'e39c7a32-3e3e-5f60-b5b2-9a5172911743', 0, 'Synchronize employee passwords to the partner''s directory', false, 'Synchronizing passwords to the partner exposes credentials to another organization.'),
  ('7d91e4be-bfdb-5d58-a272-8c2b92d5791c', 'e39c7a32-3e3e-5f60-b5b2-9a5172911743', 1, 'Federate identities so the company''s IdP issues assertions the partner''s portal trusts', true, null),
  ('c4236b1c-0b12-5ba4-a190-695dbee9efd5', 'e39c7a32-3e3e-5f60-b5b2-9a5172911743', 2, 'Create shared generic accounts on the partner''s portal', false, 'Shared accounts destroy accountability and are hard to revoke.'),
  ('7015106d-ac8f-5c38-844c-ed64699aad7b', 'e39c7a32-3e3e-5f60-b5b2-9a5172911743', 3, 'Configure RADIUS on the partner''s VPN concentrator', false, 'RADIUS on a VPN does not provide web portal sign-in with corporate identities.')
insert into public.question_topics (question_id, topic_id) values ('e39c7a32-3e3e-5f60-b5b2-9a5172911743', 'federation'), ('e39c7a32-3e3e-5f60-b5b2-9a5172911743', 'sso'), ('e39c7a32-3e3e-5f60-b5b2-9a5172911743', 'iam') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('1f0a5919-f70a-55a3-ac59-da0260439e0a', 'A mobile app needs permission to read a user''s calendar from another service without ever receiving the user''s password. Which protocol is designed for this delegated authorization?', 4, 'hard', 'single', 1, 'OAuth issues access tokens that grant limited, delegated permissions to an application. OpenID Connect builds on OAuth when authentication is needed.', 'Delegated authorization with tokens = OAuth. Authentication layer on top = OpenID Connect.', 'OAuth grants access; it does not share passwords.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('21ce040b-71f0-5efa-bcdd-cb0005b5d900', '1f0a5919-f70a-55a3-ac59-da0260439e0a', 0, 'OAuth 2.0', true, null),
  ('4a2e75b9-b4ac-59a7-b31c-16e68abb1871', '1f0a5919-f70a-55a3-ac59-da0260439e0a', 1, 'LDAP', false, 'LDAP is a directory access protocol.'),
  ('0df40e7a-ab5d-5117-92be-d92e5729a3aa', '1f0a5919-f70a-55a3-ac59-da0260439e0a', 2, 'Kerberos', false, 'Kerberos handles authentication inside a domain, not third-party delegated access.'),
  ('de2f82bd-540a-5214-9b31-ef38ab9dcd4b', '1f0a5919-f70a-55a3-ac59-da0260439e0a', 3, 'TACACS+', false, 'TACACS+ is used for network device administration AAA.')
insert into public.question_topics (question_id, topic_id) values ('1f0a5919-f70a-55a3-ac59-da0260439e0a', 'federation'), ('1f0a5919-f70a-55a3-ac59-da0260439e0a', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('87c5005f-1982-59b6-bfb7-8ee0537f01a9', 'In a Windows Active Directory domain, which protocol issues time-limited tickets so users can access multiple services after a single login?', 4, 'medium', 'single', 1, 'Kerberos uses a key distribution center to issue a ticket-granting ticket and service tickets, enabling SSO. Because tickets are time-stamped, clocks must be synchronized.', 'Tickets + KDC + time sync = Kerberos.', 'Kerberos hands out tickets like a three-headed gatekeeper.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('24bc246b-30fe-5c30-8a3f-66a9146deded', '87c5005f-1982-59b6-bfb7-8ee0537f01a9', 0, 'NTLM', false, 'NTLM is an older challenge-response protocol without tickets.'),
  ('60725b33-7dd6-52a2-b203-c054d239b9fb', '87c5005f-1982-59b6-bfb7-8ee0537f01a9', 1, 'Kerberos', true, null),
  ('39bd5e8c-3baf-58c0-b59e-3dccf4baa7f7', '87c5005f-1982-59b6-bfb7-8ee0537f01a9', 2, 'SAML', false, 'SAML provides web-based federated SSO, not domain ticketing.'),
  ('22d5e8f3-f773-5935-b6b7-bc606e759792', '87c5005f-1982-59b6-bfb7-8ee0537f01a9', 3, 'RADIUS', false, 'RADIUS provides AAA for network access.')
insert into public.question_topics (question_id, topic_id) values ('87c5005f-1982-59b6-bfb7-8ee0537f01a9', 'sso'), ('87c5005f-1982-59b6-bfb7-8ee0537f01a9', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('92c00d5a-0f79-5413-9567-576418180897', 'Which statement about RADIUS is TRUE?', 4, 'medium', 'single', 1, 'RADIUS uses UDP and encrypts only the password field, leaving other attributes visible. It is widely used for network access such as VPN, Wi-Fi, and 802.1X.', 'RADIUS: UDP, password-only encryption, network access. TACACS+: TCP 49, full encryption, device admin.', 'RADIUS radiates everything except the password.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('10777a3d-ed57-5220-b9c9-dbe6425755c1', '92c00d5a-0f79-5413-9567-576418180897', 0, 'It encrypts only the password in the access-request packet', true, null),
  ('b0c47b0b-b7a9-583c-9c80-3ee760b6a2b2', '92c00d5a-0f79-5413-9567-576418180897', 1, 'It uses TCP port 49', false, 'TCP 49 is used by TACACS+. RADIUS uses UDP (1812/1813).'),
  ('447c8fe0-58cf-5c8d-aa1e-f4124ed3ce51', '92c00d5a-0f79-5413-9567-576418180897', 2, 'It encrypts the entire packet payload', false, 'Full payload encryption is a TACACS+ characteristic.'),
  ('8cacd8d6-2442-5c5b-a69c-409f2c6e301c', '92c00d5a-0f79-5413-9567-576418180897', 3, 'It is designed mainly for authorizing individual router commands', false, 'Per-command authorization for device administration is TACACS+''s strength.')
insert into public.question_topics (question_id, topic_id) values ('92c00d5a-0f79-5413-9567-576418180897', 'radius'), ('92c00d5a-0f79-5413-9567-576418180897', 'aaa') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('13d3a0e6-5558-5eaa-b827-57acd724cba6', 'A network team wants to authorize and log each command administrators run on routers and switches, with the entire session payload encrypted. Which protocol BEST fits?', 4, 'medium', 'single', 1, 'TACACS+ separates authentication, authorization, and accounting, supports per-command authorization, and encrypts the full payload over TCP.', 'Device administration + command authorization + full encryption = TACACS+.', 'TACACS+ = Total encryption, Command-by-command control.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ca0f93fa-ae56-5a44-9e32-86d669d6ff53', '13d3a0e6-5558-5eaa-b827-57acd724cba6', 0, 'RADIUS', false, 'RADIUS combines authentication and authorization and encrypts only the password.'),
  ('82803326-e00c-5aa1-a8e8-3e3e9edcbf83', '13d3a0e6-5558-5eaa-b827-57acd724cba6', 1, 'TACACS+', true, null),
  ('8bd406bf-ab81-569a-b64f-70c8b1e2f2d5', '13d3a0e6-5558-5eaa-b827-57acd724cba6', 2, 'Kerberos', false, 'Kerberos does not authorize individual device commands.'),
  ('54923663-f118-5ab0-b123-45a06f54f60e', '13d3a0e6-5558-5eaa-b827-57acd724cba6', 3, 'SNMPv2c', false, 'SNMPv2c is a monitoring protocol with community strings, not an AAA protocol.')
insert into public.question_topics (question_id, topic_id) values ('13d3a0e6-5558-5eaa-b827-57acd724cba6', 'tacacs'), ('13d3a0e6-5558-5eaa-b827-57acd724cba6', 'aaa'), ('13d3a0e6-5558-5eaa-b827-57acd724cba6', 'logging') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('695878d0-b12d-5094-8757-702e6b78f8ac', 'A company wants employee laptops to authenticate before they can use wired switch ports, with credentials verified against a central server. Which combination is BEST?', 4, 'hard', 'single', 1, '802.1X port-based network access control blocks a port until the supplicant authenticates. The switch relays credentials to a RADIUS server for verification.', 'Port-based access control = 802.1X (supplicant, authenticator, RADIUS server).', '802.1X keeps the port closed until you prove who you are.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('9e34546b-6d1f-561a-a7fb-5f3d35a306de', '695878d0-b12d-5094-8757-702e6b78f8ac', 0, '802.1X with switches as authenticators and a RADIUS authentication server', true, null),
  ('f866c8f2-40f1-52eb-86ad-130d547fe8cb', '695878d0-b12d-5094-8757-702e6b78f8ac', 1, 'TACACS+ with MAC address port security', false, 'TACACS+ is for administering devices, and MAC addresses can be spoofed.'),
  ('ba4ca4d4-85e0-599d-9df4-29e187448902', '695878d0-b12d-5094-8757-702e6b78f8ac', 2, 'WPA3-Personal on the switches', false, 'WPA3-Personal is a wireless standard using a shared passphrase.'),
  ('6df969d4-d859-586e-87ec-5a0733b5f2d0', '695878d0-b12d-5094-8757-702e6b78f8ac', 3, 'Kerberos tickets configured on each switch port', false, 'Switch ports do not authenticate devices using Kerberos tickets directly.')
insert into public.question_topics (question_id, topic_id) values ('695878d0-b12d-5094-8757-702e6b78f8ac', 'radius'), ('695878d0-b12d-5094-8757-702e6b78f8ac', 'network-security'), ('695878d0-b12d-5094-8757-702e6b78f8ac', 'authentication') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e03df688-b564-5c0c-ad42-5c3964cf7a22', 'Which access control model assigns permissions based on job functions such as ''Nurse'' or ''Accountant''?', 4, 'easy', 'single', 1, 'RBAC grants permissions to roles, and users receive access by being assigned to roles that match their jobs.', 'Job title or function = role-based.', 'RBAC: your role decides your rights.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('c0afe15d-524b-5905-b3c8-a292b9a05fbf', 'e03df688-b564-5c0c-ad42-5c3964cf7a22', 0, 'Discretionary access control (DAC)', false, 'DAC lets resource owners decide who has access.'),
  ('2f59aa4f-0493-5cdb-b427-5d7b4624f964', 'e03df688-b564-5c0c-ad42-5c3964cf7a22', 1, 'Mandatory access control (MAC)', false, 'MAC uses labels and clearances enforced by the system.'),
  ('09c5ea18-5d6b-57de-a8a8-e07ceee7e460', 'e03df688-b564-5c0c-ad42-5c3964cf7a22', 2, 'Role-based access control (RBAC)', true, null),
  ('bfc57763-923f-5026-a9cc-e9c9d35c2c81', 'e03df688-b564-5c0c-ad42-5c3964cf7a22', 3, 'Rule-based access control', false, 'Rule-based access control applies system-wide rules such as time-of-day restrictions or firewall ACLs.')
insert into public.question_topics (question_id, topic_id) values ('e03df688-b564-5c0c-ad42-5c3964cf7a22', 'access-control-models'), ('e03df688-b564-5c0c-ad42-5c3964cf7a22', 'iam') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f17a9e47-c327-59b6-90d9-82c9a700160a', 'A company wants to allow access to financial reports only for Finance employees using a managed device, during business hours, from within the country. Which access control model BEST supports these combined conditions?', 4, 'hard', 'single', 1, 'ABAC evaluates many attributes (user department, device state, time, location, resource sensitivity) in policy decisions, supporting fine-grained, context-aware rules.', 'Multiple conditions (who + what device + when + where) = ABAC.', 'ABAC: All the attributes decide.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('18fbad72-ca9f-57d3-a78b-69f4cec75501', 'f17a9e47-c327-59b6-90d9-82c9a700160a', 0, 'Role-based access control', false, 'RBAC can express the Finance role but not device, time, and location conditions on its own.'),
  ('c04d6b55-be41-5cc9-9b87-20563c1f3ec4', 'f17a9e47-c327-59b6-90d9-82c9a700160a', 1, 'Attribute-based access control', true, null),
  ('dcf9ce22-723a-508c-8796-2d0dde06eaae', 'f17a9e47-c327-59b6-90d9-82c9a700160a', 2, 'Discretionary access control', false, 'DAC relies on owner discretion rather than centralized contextual policy.'),
  ('d9b2b84d-e919-5d5e-87fc-748bdcd7266a', 'f17a9e47-c327-59b6-90d9-82c9a700160a', 3, 'Mandatory access control', false, 'MAC relies on classification labels and clearances, not contextual attributes.')
insert into public.question_topics (question_id, topic_id) values ('f17a9e47-c327-59b6-90d9-82c9a700160a', 'access-control-models'), ('f17a9e47-c327-59b6-90d9-82c9a700160a', 'zero-trust') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('56127d2f-7f26-5e50-a559-850a539c9ea4', 'In which access control model does the operating system enforce access using classification labels and user clearances, with owners unable to change permissions?', 4, 'medium', 'single', 1, 'MAC assigns labels (such as Secret) to objects and clearances to subjects. The system enforces access, which is why MAC is used in high-security government environments.', 'Labels + clearances + owners cannot override = MAC.', 'Mandatory means the system decides, not the owner.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('0594607d-705b-55d1-a063-9f9cccd80092', '56127d2f-7f26-5e50-a559-850a539c9ea4', 0, 'Mandatory access control', true, null),
  ('efabe355-3959-54dc-a4d2-464e03ce37a4', '56127d2f-7f26-5e50-a559-850a539c9ea4', 1, 'Discretionary access control', false, 'In DAC, owners control permissions.'),
  ('aac7b5c0-c7b8-53bc-921a-406d62c68497', '56127d2f-7f26-5e50-a559-850a539c9ea4', 2, 'Role-based access control', false, 'RBAC is based on roles, not classification labels.'),
  ('0da3b699-1318-5fb4-ab89-65589cc3d697', '56127d2f-7f26-5e50-a559-850a539c9ea4', 3, 'Rule-based access control', false, 'Rule-based uses administrator-defined rules, not labels and clearances.')
insert into public.question_topics (question_id, topic_id) values ('56127d2f-7f26-5e50-a559-850a539c9ea4', 'access-control-models') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('be862193-6d76-5ba3-b435-d66e8ec7267a', 'Which incident response phase immediately follows detection and analysis?', 4, 'easy', 'single', 1, 'Once an incident is confirmed and analyzed, the team contains it to stop the damage from spreading, then eradicates the cause and recovers.', 'Order: Preparation, Detection, Analysis, Containment, Eradication, Recovery, Lessons learned.', 'Stop the bleeding before you heal the wound.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('4db024a9-4298-57fb-9ae8-fbaf8ddf4448', 'be862193-6d76-5ba3-b435-d66e8ec7267a', 0, 'Preparation', false, 'Preparation happens before any incident occurs.'),
  ('fe73b914-8986-5192-80a0-0147cf883503', 'be862193-6d76-5ba3-b435-d66e8ec7267a', 1, 'Containment', true, null),
  ('9a9d1104-a61c-51a0-afbd-110619bb8e35', 'be862193-6d76-5ba3-b435-d66e8ec7267a', 2, 'Lessons learned', false, 'Lessons learned is the final phase.'),
  ('d0612d6a-f154-5af6-ad57-db35082f37ec', 'be862193-6d76-5ba3-b435-d66e8ec7267a', 3, 'Recovery', false, 'Recovery comes after containment and eradication.')
insert into public.question_topics (question_id, topic_id) values ('be862193-6d76-5ba3-b435-d66e8ec7267a', 'incident-response') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 'A SOC analyst confirms that a workstation is actively communicating with a known command-and-control server. What should the analyst do FIRST?', 4, 'medium', 'single', 1, 'Containment comes first: isolating the host stops attacker control and lateral movement while preserving evidence for investigation.', 'Active compromise confirmed + FIRST = contain (isolate) while preserving evidence.', 'Unplug the problem before you study it.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('6168622b-8468-557a-b632-4073613092af', 'e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 0, 'Reimage the workstation immediately', false, 'Reimaging is eradication and recovery; doing it first destroys volatile evidence.'),
  ('009a7d79-f3eb-5b33-9eab-bcb8171083b3', 'e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 1, 'Isolate the workstation from the network', true, null),
  ('58f3005e-1e4a-59a6-add4-b348a21a39ae', 'e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 2, 'Notify the media', false, 'External communication follows the communication plan and is not a first technical step.'),
  ('f0533a46-077f-53b9-9298-fec1e0afca8d', 'e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 3, 'Run a vulnerability scan across the entire network', false, 'A network-wide scan does not stop the active compromise.')
insert into public.question_topics (question_id, topic_id) values ('e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 'incident-response'), ('e0fb522b-b3e6-5430-9bbd-b59739ba2c9f', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 'After containing a ransomware outbreak, the team restores systems from backups, but the ransomware reappears within hours. Which incident response step was MOST likely incomplete?', 4, 'hard', 'single', 1, 'Eradication removes the root cause, such as persistence mechanisms, compromised accounts, and the initial access vector. Skipping it lets the attacker re-infect restored systems.', 'Came back after recovery? Eradication (root cause and persistence) was missed.', 'Pull the weed by the root, or it grows back.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('e1c38ddd-584b-5dfa-bfbd-6eb276750f6f', '040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 0, 'Eradication', true, null),
  ('a4a70551-4770-5b01-b9f3-6721487aeb54', '040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 1, 'Lessons learned', false, 'Lessons learned improves future response; it would not prevent immediate reinfection.'),
  ('419fef34-57d1-541f-a369-d46c1d7f3112', '040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 2, 'Preparation', false, 'Preparation happens before incidents.'),
  ('21e0b56c-0693-5b47-88fe-22f240920d1e', '040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 3, 'Notification', false, 'Notification informs stakeholders but does not remove the threat.')
insert into public.question_topics (question_id, topic_id) values ('040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 'incident-response'), ('040fa8c1-8b29-5b8c-aa56-2e4a196baf31', 'malware') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 'Which exercise walks key stakeholders through a simulated incident in a discussion-based format without affecting production systems?', 4, 'medium', 'single', 1, 'A tabletop exercise is a low-cost, discussion-driven walkthrough that validates roles, communication, and decisions.', 'Discussion only, around a table, no systems touched = tabletop.', 'Tabletop: talk it through before you live it.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('37c4d228-a356-50d6-ac7c-62dc540daf04', '9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 0, 'Tabletop exercise', true, null),
  ('33871894-b4cd-520b-ba8e-f4736d3a0d11', '9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 1, 'Full-scale failover test', false, 'A failover test actually moves operations to backup systems.'),
  ('15d45294-9d25-5509-8551-9eb69bcca8cb', '9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 2, 'Penetration test', false, 'A penetration test actively attacks systems to find weaknesses.'),
  ('7cb0c85c-aae3-5afe-9ff6-86c3df9b10d4', '9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 3, 'Parallel processing test', false, 'Parallel processing runs recovery systems alongside production.')
insert into public.question_topics (question_id, topic_id) values ('9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 'incident-response'), ('9f4adc2b-5b78-5e36-802f-3a0c84f2bd31', 'disaster-recovery') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('0baf0159-a019-53ed-89bc-b8c0beb839f9', 'What is the primary function of a SIEM?', 4, 'easy', 'single', 1, 'A SIEM collects and normalizes logs, correlates events across sources, generates alerts, and supports investigation and reporting.', 'Aggregation + correlation + alerting across many sources = SIEM.', 'SIEM sees the whole picture by connecting the dots.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('1fd66d39-9837-5b64-b9f2-9c5939a8aa20', '0baf0159-a019-53ed-89bc-b8c0beb839f9', 0, 'To aggregate and correlate logs from many sources to detect and alert on security events', true, null),
  ('dadf9f13-fe5f-5b30-bfdc-dac15cf1cbeb', '0baf0159-a019-53ed-89bc-b8c0beb839f9', 1, 'To block malicious traffic inline at the network edge', false, 'Blocking traffic inline is the job of a firewall or IPS.'),
  ('afb1f2b6-a024-5444-b537-48f00e548864', '0baf0159-a019-53ed-89bc-b8c0beb839f9', 2, 'To scan hosts for missing patches', false, 'Patch scanning is done by vulnerability scanners.'),
  ('b5103953-48a7-5e39-b2a2-0d675f5e9da4', '0baf0159-a019-53ed-89bc-b8c0beb839f9', 3, 'To encrypt log files at rest', false, 'Encryption may protect stored logs, but it is not what a SIEM is for.')
insert into public.question_topics (question_id, topic_id) values ('0baf0159-a019-53ed-89bc-b8c0beb839f9', 'siem'), ('0baf0159-a019-53ed-89bc-b8c0beb839f9', 'logging') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('89ebbf71-c180-589b-b779-8dc64052e46b', 'A SIEM generates thousands of low-value alerts each day, and analysts miss an alert for a real intrusion. What is the BEST way to improve detection?', 4, 'hard', 'single', 1, 'Alert fatigue hides real threats. Tuning rules, suppressing known-benign noise, and prioritizing alerts improves the signal-to-noise ratio.', 'Too many alerts, real attack missed = alert fatigue; the answer is tuning.', 'A quieter SIEM is a smarter SIEM.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('3e3183ef-e2d6-56d5-92a5-2662dba07d16', '89ebbf71-c180-589b-b779-8dc64052e46b', 0, 'Disable alerting and review logs weekly', false, 'Weekly review delays detection far too long.'),
  ('64b33ce5-50fb-5b67-b020-a82f1568b172', '89ebbf71-c180-589b-b779-8dc64052e46b', 1, 'Tune correlation rules and thresholds to reduce false positives and prioritize high-risk alerts', true, null),
  ('53e257d9-a26d-546e-afb7-276ed5462e0f', '89ebbf71-c180-589b-b779-8dc64052e46b', 2, 'Increase log retention to five years', false, 'Longer retention helps investigations but does not reduce noise.'),
  ('a358dacb-2c5e-5eb6-be22-68b614044a15', '89ebbf71-c180-589b-b779-8dc64052e46b', 3, 'Send more log sources to the SIEM without changing rules', false, 'More sources without tuning adds even more noise.')
insert into public.question_topics (question_id, topic_id) values ('89ebbf71-c180-589b-b779-8dc64052e46b', 'siem'), ('89ebbf71-c180-589b-b779-8dc64052e46b', 'logging') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('6d3cbed3-8840-5034-b5bf-6be48281f2a3', 'Which data source shows which internal hosts communicated with which external IP addresses, including byte counts, without capturing full packet contents?', 4, 'medium', 'single', 1, 'Flow data summarizes conversations (source, destination, ports, bytes, duration) and is ideal for spotting unusual connections or large transfers without storing payloads.', 'Who talked to whom and how much, without content = NetFlow.', 'Flow data is the phone bill, not the phone call.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a9d9ce9f-3d73-5227-9f74-69b540bc1bda', '6d3cbed3-8840-5034-b5bf-6be48281f2a3', 0, 'NetFlow (flow records)', true, null),
  ('2374825d-e666-5723-9aa7-6afa4d0922d2', '6d3cbed3-8840-5034-b5bf-6be48281f2a3', 1, 'Full packet capture', false, 'Packet capture records full contents, which is far larger.'),
  ('65254d33-6e34-5587-97a8-57eef54df36c', '6d3cbed3-8840-5034-b5bf-6be48281f2a3', 2, 'DHCP server logs', false, 'DHCP logs map IP addresses to devices but not traffic volumes.'),
  ('f4a28bca-c5b7-5548-a3d7-a2a267e2191f', '6d3cbed3-8840-5034-b5bf-6be48281f2a3', 3, 'Vulnerability scan results', false, 'Scan results describe vulnerabilities, not communications.')
insert into public.question_topics (question_id, topic_id) values ('6d3cbed3-8840-5034-b5bf-6be48281f2a3', 'logging'), ('6d3cbed3-8840-5034-b5bf-6be48281f2a3', 'network-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('ad63f9f7-06b5-5473-b265-83d8ce11de08', 'During an investigation, analysts cannot reliably reconstruct the order of events across firewall, server, and application logs because the timestamps disagree by several minutes. Which control would have prevented this?', 4, 'hard', 'single', 1, 'Accurate, synchronized time is essential for correlating events across systems. NTP keeps clocks consistent so timelines line up.', 'Timeline does not line up across systems = time synchronization (NTP).', 'Same clock, same story.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f929bea7-3be7-5519-8dae-7c59184892c9', 'ad63f9f7-06b5-5473-b265-83d8ce11de08', 0, 'Synchronizing all systems to a common NTP time source', true, null),
  ('ac73c1a8-67fe-59d6-80a0-02a1577ea5f3', 'ad63f9f7-06b5-5473-b265-83d8ce11de08', 1, 'Increasing log verbosity', false, 'More detail does not fix inconsistent clocks.'),
  ('eee4d7b0-8520-5aae-b18b-70e22c21fc03', 'ad63f9f7-06b5-5473-b265-83d8ce11de08', 2, 'Compressing logs before storage', false, 'Compression affects storage, not timestamp accuracy.'),
  ('16a6a2f7-37fd-5a72-a520-572f756e1f90', 'ad63f9f7-06b5-5473-b265-83d8ce11de08', 3, 'Rotating logs daily', false, 'Rotation manages file size, not time accuracy.')
insert into public.question_topics (question_id, topic_id) values ('ad63f9f7-06b5-5473-b265-83d8ce11de08', 'logging'), ('ad63f9f7-06b5-5473-b265-83d8ce11de08', 'forensics'), ('ad63f9f7-06b5-5473-b265-83d8ce11de08', 'siem') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 'Which document records every person who handled a piece of evidence, when they handled it, and for what purpose?', 4, 'easy', 'single', 1, 'Chain of custody documents evidence handling from collection to court so its integrity can be proven.', 'Who touched the evidence and when = chain of custody.', 'Every hand on the evidence gets written down.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b39d9520-5b26-50fa-a28a-2f3803d6ad11', '8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 0, 'Chain of custody', true, null),
  ('7c640db4-0448-542e-ba18-675c87f49791', '8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 1, 'Legal hold notice', false, 'A legal hold requires data to be preserved; it does not track handling.'),
  ('5a8af708-a47b-5b48-a1bf-3ed27640ea77', '8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 2, 'Incident response plan', false, 'An IR plan describes how to respond to incidents.'),
  ('556cd661-85a8-5ae8-9d7e-c4f5342e2491', '8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 3, 'Service level agreement', false, 'An SLA defines service performance commitments.')
insert into public.question_topics (question_id, topic_id) values ('8a2542f9-4ad5-5c2e-8e5d-e96b540fc397', 'forensics') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('34647576-0cf7-50d1-ba2e-72e45900a1dd', 'According to the order of volatility, which evidence should be collected FIRST?', 4, 'medium', 'single', 1, 'Collect the most volatile data first because it disappears quickly. RAM is lost on power-off, while disks and backups persist.', 'Order of volatility: CPU/cache, RAM, swap, disk, remote logs, backups.', 'Grab what evaporates first.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('297972d3-038e-5254-bc71-238ca54f9a31', '34647576-0cf7-50d1-ba2e-72e45900a1dd', 0, 'Contents of system memory (RAM)', true, null),
  ('ab69c7fd-835b-5d8a-abf3-42f2d067444a', '34647576-0cf7-50d1-ba2e-72e45900a1dd', 1, 'Hard drive image', false, 'Disk data persists after shutdown, so it comes after memory.'),
  ('68746b51-6149-5a65-a5bc-3bff34e36f95', '34647576-0cf7-50d1-ba2e-72e45900a1dd', 2, 'Archived backup tapes', false, 'Backups are among the least volatile sources.'),
  ('7492697f-75e2-566c-88ab-552db47425d6', '34647576-0cf7-50d1-ba2e-72e45900a1dd', 3, 'Logs stored on a remote syslog server', false, 'Remote logs are durable and can be collected later.')
insert into public.question_topics (question_id, topic_id) values ('34647576-0cf7-50d1-ba2e-72e45900a1dd', 'forensics'), ('34647576-0cf7-50d1-ba2e-72e45900a1dd', 'incident-response') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 'Legal counsel informs IT that the company is being sued and all email related to a specific project must be preserved. What should IT implement?', 4, 'medium', 'single', 1, 'A legal hold suspends normal deletion and retention policies for relevant data so it is preserved for litigation.', 'Litigation expected + preserve data = legal hold.', 'Legal hold: hold everything, delete nothing.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ae797ed2-3a89-5b0b-8363-c7d5e89fefb4', 'b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 0, 'A legal hold', true, null),
  ('6084e643-ab99-5c5b-8d56-476f178b62e6', 'b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 1, 'An email retention purge', false, 'Purging would destroy evidence and could bring legal penalties.'),
  ('4594d779-54a7-5de9-b4ed-0929b907c521', 'b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 2, 'Data masking', false, 'Masking hides values; it does not preserve records.'),
  ('7e7734ce-cfdb-5d42-9918-8560f94ca9de', 'b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 3, 'An acceptable use policy update', false, 'An AUP update does not preserve existing data.')
insert into public.question_topics (question_id, topic_id) values ('b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 'forensics'), ('b9253ce3-2d1f-5abe-aafc-c12218ef5a2e', 'compliance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('41e337ae-0b87-5ef8-b2f8-28493848cc19', 'Why does a forensic investigator connect a suspect''s hard drive through a write blocker before imaging it?', 4, 'medium', 'single', 1, 'A write blocker allows reads but blocks writes, so the original evidence is not altered. Hashes of the original and image then prove they match.', 'Protect original evidence from modification = write blocker + hashing.', 'Read everything, change nothing.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('fae4835a-cc5d-506c-b3c4-055e5a6c8045', '41e337ae-0b87-5ef8-b2f8-28493848cc19', 0, 'To prevent any changes to the original evidence and preserve its integrity', true, null),
  ('352b7063-2dee-5d56-9769-eb28eb1ce735', '41e337ae-0b87-5ef8-b2f8-28493848cc19', 1, 'To speed up the imaging process', false, 'Write blockers do not speed up imaging.'),
  ('7df14ddc-163a-59bd-bf8c-5b114fd946f2', '41e337ae-0b87-5ef8-b2f8-28493848cc19', 2, 'To decrypt the drive automatically', false, 'They do not decrypt data.'),
  ('a96b642b-9950-57c2-acc9-ed17edabf8fd', '41e337ae-0b87-5ef8-b2f8-28493848cc19', 3, 'To remove malware before analysis', false, 'Removing malware would alter the evidence.')
insert into public.question_topics (question_id, topic_id) values ('41e337ae-0b87-5ef8-b2f8-28493848cc19', 'forensics') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('430e6498-19cb-52ea-b718-895e989ee533', 'What does the Common Vulnerability Scoring System (CVSS) provide?', 4, 'easy', 'single', 1, 'CVSS rates vulnerability severity from 0 to 10 based on factors such as exploitability and impact, helping organizations prioritize remediation.', 'CVE = the name of the vulnerability. CVSS = how bad it is.', 'CVSS scores severity; CVE names it.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('be640386-435c-521f-a27e-86aa915fc4b5', '430e6498-19cb-52ea-b718-895e989ee533', 0, 'A standardized numerical severity score for vulnerabilities', true, null),
  ('2539aaba-35d5-5cd3-9de5-7b484e7622f3', '430e6498-19cb-52ea-b718-895e989ee533', 1, 'A unique identifier for each publicly known vulnerability', false, 'Unique identifiers are CVE IDs.'),
  ('5e003a74-427e-597a-897d-95603a03a640', '430e6498-19cb-52ea-b718-895e989ee533', 2, 'An automated patch deployment tool', false, 'CVSS does not deploy patches.'),
  ('46ad0c64-9d5a-54ad-8003-22ed8e5257d5', '430e6498-19cb-52ea-b718-895e989ee533', 3, 'A list of an organization''s assets', false, 'Asset inventories are maintained separately.')
insert into public.question_topics (question_id, topic_id) values ('430e6498-19cb-52ea-b718-895e989ee533', 'vulnerability-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d6e50e50-34eb-56ca-a32d-b67c02fe1506', 'A vulnerability scan flags a critical OpenSSL flaw on a server. The administrator confirms the installed package already includes the vendor''s backported fix. How should this finding be handled?', 4, 'hard', 'single', 1, 'Scanners often detect vulnerabilities by version strings, which misses backported patches. After validation, the finding is a false positive that should be documented so it is not repeatedly re-raised.', 'Scanner flags something already fixed = false positive; validate and document.', 'Trust, but verify the scanner.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('1d6345a7-fad1-5005-8e38-1b259dc08ef1', 'd6e50e50-34eb-56ca-a32d-b67c02fe1506', 0, 'Treat it as a false positive, document the evidence, and record an exception', true, null),
  ('43f50a61-915e-5f29-9979-281cf64b0d5c', 'd6e50e50-34eb-56ca-a32d-b67c02fe1506', 1, 'Treat it as a true positive and take the server offline', false, 'The fix is present, so the vulnerability is not actually exploitable.'),
  ('dfc0668e-8466-5846-8f15-acd183c0f150', 'd6e50e50-34eb-56ca-a32d-b67c02fe1506', 2, 'Ignore all future results from the scanner', false, 'Discarding all scanner results would hide real issues.'),
  ('bfb686d1-f5e7-53f9-8232-efe0ac623932', 'd6e50e50-34eb-56ca-a32d-b67c02fe1506', 3, 'Lower the CVSS base score in the national database', false, 'Organizations do not change public CVSS scores; they can adjust environmental scoring internally.')
insert into public.question_topics (question_id, topic_id) values ('d6e50e50-34eb-56ca-a32d-b67c02fe1506', 'vulnerability-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d668eda4-29cd-5aea-9e35-4d37d1778b3a', 'Which type of vulnerability scan logs in to target systems to give a more accurate view of missing patches and configuration weaknesses?', 4, 'medium', 'single', 1, 'A credentialed scan authenticates to the system and inspects installed software and settings from the inside, producing fewer false positives.', 'Most accurate internal view = credentialed. Attacker''s view = non-credentialed.', 'Credentials let the scanner look inside.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('27f17336-c0f2-5a68-9fee-e2019ba69122', 'd668eda4-29cd-5aea-9e35-4d37d1778b3a', 0, 'Credentialed scan', true, null),
  ('786dc632-7333-5d97-ad03-842b0bf4aba5', 'd668eda4-29cd-5aea-9e35-4d37d1778b3a', 1, 'Non-credentialed scan', false, 'Non-credentialed scans see only what is exposed externally, like an outside attacker.'),
  ('4cd848b1-ff30-5ba1-a53d-54343a09cae5', 'd668eda4-29cd-5aea-9e35-4d37d1778b3a', 2, 'Passive scan', false, 'Passive scanning observes traffic without probing systems.'),
  ('811b516d-29c2-5dd2-9439-0ccbb5e18611', 'd668eda4-29cd-5aea-9e35-4d37d1778b3a', 3, 'Port scan', false, 'A port scan identifies open ports, not missing patches.')
insert into public.question_topics (question_id, topic_id) values ('d668eda4-29cd-5aea-9e35-4d37d1778b3a', 'vulnerability-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('84a2bb10-e325-5251-83c6-05ebe626ef76', 'Which is the BEST first step when hardening a newly installed server?', 4, 'easy', 'single', 1, 'Hardening reduces the attack surface. Removing what is not needed and eliminating default credentials closes common entry points.', 'Hardening = reduce attack surface: remove, disable, change defaults, apply baselines.', 'If you do not need it, turn it off.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b7cd7bae-59b0-58ac-ba7c-bbad274dd716', '84a2bb10-e325-5251-83c6-05ebe626ef76', 0, 'Disable or remove unnecessary services, ports, and default accounts', true, null),
  ('6ef8724c-5bd2-5544-bf13-3091fa779c01', '84a2bb10-e325-5251-83c6-05ebe626ef76', 1, 'Install a screen saver', false, 'A screen saver has little security value on a server.'),
  ('75287033-4bfc-5090-aa49-661bc45330d9', '84a2bb10-e325-5251-83c6-05ebe626ef76', 2, 'Enable every available feature for flexibility', false, 'Enabling extra features increases the attack surface.'),
  ('fd967e25-3c48-53e9-b566-ef60fc8a70be', '84a2bb10-e325-5251-83c6-05ebe626ef76', 3, 'Share the administrator password with the help desk', false, 'Sharing admin credentials undermines accountability and least privilege.')
insert into public.question_topics (question_id, topic_id) values ('84a2bb10-e325-5251-83c6-05ebe626ef76', 'hardening'), ('84a2bb10-e325-5251-83c6-05ebe626ef76', 'mitigation-techniques') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('199dbcb5-54ca-5472-a130-1163234baf6e', 'Which solution continuously records endpoint activity, detects suspicious behavior, and lets an analyst isolate a compromised host remotely?', 4, 'medium', 'single', 1, 'EDR collects detailed telemetry, uses behavioral analytics to detect threats, and provides response actions such as host isolation and process termination.', 'Record + detect + respond on endpoints = EDR. Across endpoints, network and cloud = XDR.', 'EDR: detect it and respond to it on the endpoint.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('574a05e6-721e-52cf-a32f-22fac20bd6fc', '199dbcb5-54ca-5472-a130-1163234baf6e', 0, 'Endpoint detection and response (EDR)', true, null),
  ('611fd683-cb96-5c54-a176-db368a2db8fd', '199dbcb5-54ca-5472-a130-1163234baf6e', 1, 'Traditional signature-based antivirus', false, 'Signature-based antivirus blocks known malware but lacks behavioral telemetry and investigation tools.'),
  ('edbdd3fd-1d90-5a74-b0e9-530a9e06f0bc', '199dbcb5-54ca-5472-a130-1163234baf6e', 2, 'Host-based firewall', false, 'A host firewall filters traffic but does not record endpoint behavior.'),
  ('19f2228f-2bc2-5e93-850d-1b312282b1af', '199dbcb5-54ca-5472-a130-1163234baf6e', 3, 'Mobile device management (MDM)', false, 'MDM manages device configuration and policy, mainly for mobile devices.')
insert into public.question_topics (question_id, topic_id) values ('199dbcb5-54ca-5472-a130-1163234baf6e', 'endpoint-security'), ('199dbcb5-54ca-5472-a130-1163234baf6e', 'incident-response') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('7d08b76e-7534-5102-b31e-8ee745cc2834', 'Which email authentication mechanism publishes a DNS record listing the mail servers authorized to send email for a domain?', 4, 'medium', 'single', 1, 'Sender Policy Framework uses a DNS TXT record to list authorized sending servers, allowing receivers to detect forged senders.', 'Authorized sending servers list = SPF. Signature = DKIM. Policy + reports = DMARC.', 'SPF: Servers Permitted to Forward.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('392af7ed-5741-5561-81df-d75bf0949673', '7d08b76e-7534-5102-b31e-8ee745cc2834', 0, 'SPF', true, null),
  ('dc16bf1e-241e-59e9-8fd3-6cb1a00e77f1', '7d08b76e-7534-5102-b31e-8ee745cc2834', 1, 'DKIM', false, 'DKIM adds a cryptographic signature to messages.'),
  ('025bd83f-89f8-5142-a041-cea85c24426b', '7d08b76e-7534-5102-b31e-8ee745cc2834', 2, 'DMARC', false, 'DMARC defines what to do when SPF or DKIM fail and provides reporting.'),
  ('d5636550-241c-57f6-85bd-6957c0dfb35f', '7d08b76e-7534-5102-b31e-8ee745cc2834', 3, 'S/MIME', false, 'S/MIME encrypts and signs individual messages using certificates.')
insert into public.question_topics (question_id, topic_id) values ('7d08b76e-7534-5102-b31e-8ee745cc2834', 'email-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('afd863a9-9c4f-5501-8b72-576f6746d0c0', 'A company publishes SPF and DKIM records, yet spoofed emails claiming to be from its domain still reach recipients. Which additional record tells receiving servers how to handle messages that fail these checks and sends reports back to the domain owner?', 4, 'hard', 'single', 1, 'DMARC ties SPF and DKIM to the visible From domain and tells receivers to monitor, quarantine, or reject failures, with aggregate reports to the owner.', 'Enforcement policy (none/quarantine/reject) + reporting = DMARC.', 'DMARC is the manager telling everyone what to do with failures.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('fb4987bc-8adf-5048-b5ce-784febd229e5', 'afd863a9-9c4f-5501-8b72-576f6746d0c0', 0, 'DMARC', true, null),
  ('825b6a29-f3f0-563f-a268-86f6744c7d12', 'afd863a9-9c4f-5501-8b72-576f6746d0c0', 1, 'DNSSEC', false, 'DNSSEC protects DNS responses from tampering; it does not set email handling policy.'),
  ('feb7f6d2-f055-5295-90ae-78563e85fc63', 'afd863a9-9c4f-5501-8b72-576f6746d0c0', 2, 'MX', false, 'MX records identify a domain''s inbound mail servers.'),
  ('5e5d3e5b-5d2b-53be-bf0f-10ac3844b19e', 'afd863a9-9c4f-5501-8b72-576f6746d0c0', 3, 'PTR', false, 'PTR records provide reverse DNS lookups.')
insert into public.question_topics (question_id, topic_id) values ('afd863a9-9c4f-5501-8b72-576f6746d0c0', 'email-security'), ('afd863a9-9c4f-5501-8b72-576f6746d0c0', 'social-engineering') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('8d4a64ad-2fec-5368-9ae0-0cf293040297', 'Which WPA3 feature replaces the WPA2 pre-shared key handshake to protect against offline dictionary attacks?', 4, 'medium', 'single', 1, 'SAE (the Dragonfly handshake) prevents attackers from capturing a handshake and cracking the passphrase offline, and it provides forward secrecy.', 'WPA3-Personal security improvement = SAE.', 'SAE: equals shake hands without revealing secrets.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('fa6e2ff0-abd1-55e8-8d25-83b8f7359b42', '8d4a64ad-2fec-5368-9ae0-0cf293040297', 0, 'Simultaneous Authentication of Equals (SAE)', true, null),
  ('a9e1a89b-b650-5261-abba-fcec1835f140', '8d4a64ad-2fec-5368-9ae0-0cf293040297', 1, 'TKIP', false, 'TKIP is a deprecated WPA encryption protocol.'),
  ('a17c82c6-bdc7-54a2-a2bd-8532a2b81449', '8d4a64ad-2fec-5368-9ae0-0cf293040297', 2, 'WPS PIN authentication', false, 'WPS PIN authentication is vulnerable and should be disabled.'),
  ('230e6938-247b-574d-ad87-347a9078dfe5', '8d4a64ad-2fec-5368-9ae0-0cf293040297', 3, 'MAC address filtering', false, 'MAC filtering is easily bypassed by spoofing.')
insert into public.question_topics (question_id, topic_id) values ('8d4a64ad-2fec-5368-9ae0-0cf293040297', 'wireless-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('a7cf2253-421f-5065-b1d6-314dce2f0d56', 'Which technology uses playbooks to automatically respond to common alerts, such as disabling a compromised account and opening a ticket?', 4, 'medium', 'single', 1, 'Security orchestration, automation, and response platforms run playbooks that integrate tools and automate repetitive response steps, speeding up containment.', 'Playbooks + automated response actions = SOAR.', 'SOAR responds while analysts sleep.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8249af24-9532-54e6-8e64-4eabb964a217', 'a7cf2253-421f-5065-b1d6-314dce2f0d56', 0, 'SOAR', true, null),
  ('7c5f78cb-b966-58e3-8632-0504a90b5df1', 'a7cf2253-421f-5065-b1d6-314dce2f0d56', 1, 'SIEM', false, 'A SIEM detects and alerts; automated response is SOAR''s focus.'),
  ('50ebf549-3f52-5ff7-b6b1-817b07b3d5c6', 'a7cf2253-421f-5065-b1d6-314dce2f0d56', 2, 'DLP', false, 'DLP prevents sensitive data from leaving the organization.'),
  ('c1bc17c7-1667-56c4-bcd8-b3a5329e01e4', 'a7cf2253-421f-5065-b1d6-314dce2f0d56', 3, 'NAC', false, 'NAC controls which devices can join the network.')
insert into public.question_topics (question_id, topic_id) values ('a7cf2253-421f-5065-b1d6-314dce2f0d56', 'automation'), ('a7cf2253-421f-5065-b1d6-314dce2f0d56', 'incident-response') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('31ed04b7-4202-57e6-8fe6-89c799425481', 'A company is disposing of old solid-state drives that held sensitive data and needs assurance the data cannot be recovered. Which method is MOST appropriate?', 4, 'hard', 'single', 1, 'Physical destruction guarantees data cannot be recovered, and a certificate of destruction documents it. SSDs store data in flash memory, so magnetic methods do not work.', 'SSD + must be unrecoverable = physical destruction (degaussing only works on magnetic media).', 'Magnets do not scare flash memory; shredders do.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f7f023d7-8cc9-569d-b0e1-4acfbd229fe9', '31ed04b7-4202-57e6-8fe6-89c799425481', 0, 'Deleting all files and emptying the recycle bin', false, 'Deleting files only removes references; the data remains recoverable.'),
  ('eb222ca5-0022-509c-be35-e680be8627e7', '31ed04b7-4202-57e6-8fe6-89c799425481', 1, 'Performing a quick format', false, 'A quick format does not erase the underlying data.'),
  ('a8941986-e6c4-519f-a4a2-881c0c56bf0b', '31ed04b7-4202-57e6-8fe6-89c799425481', 2, 'Degaussing the drives', false, 'Degaussing uses magnetic fields and does not reliably erase flash-based SSDs.'),
  ('78e88594-854e-553d-8199-edde347ebd65', '31ed04b7-4202-57e6-8fe6-89c799425481', 3, 'Physically shredding the drives and obtaining a certificate of destruction', true, null)
insert into public.question_topics (question_id, topic_id) values ('31ed04b7-4202-57e6-8fe6-89c799425481', 'asset-management'), ('31ed04b7-4202-57e6-8fe6-89c799425481', 'data-protection') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 'Which protocol should replace Telnet for secure remote command-line administration?', 4, 'easy', 'single', 1, 'SSH encrypts the entire session, including credentials. Telnet sends everything in cleartext.', 'Telnet (23) out, SSH (22) in.', 'SSH: Secure SHell, shush your secrets.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('920f7b82-6618-58af-bde2-25102139f026', '82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 0, 'SSH', true, null),
  ('a1223aed-48c8-57b5-b62c-e7dd3dc2d6eb', '82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 1, 'FTP', false, 'FTP transfers files and is unencrypted.'),
  ('ddc08a92-7805-5546-a9e6-264134eb8266', '82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 2, 'SNMPv1', false, 'SNMPv1 is a monitoring protocol with cleartext community strings.'),
  ('2d38daf9-e5f5-5820-9c6f-9ac97472b8b5', '82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 3, 'HTTP', false, 'HTTP is unencrypted web traffic.')
insert into public.question_topics (question_id, topic_id) values ('82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 'secure-protocols'), ('82bd2e8c-dbc3-5e89-ac28-ef87719c792f', 'hardening') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('8e78d0cc-996a-501f-8935-b37f4e83ff19', 'Which TWO protocols are secure, encrypted replacements for insecure protocols?', 4, 'medium', 'multiple', 2, 'SFTP runs file transfers over SSH, and LDAPS wraps LDAP directory queries in TLS. Both protect credentials and data in transit.', 'Secure versions: SSH, SFTP/FTPS, HTTPS, LDAPS, SNMPv3, SRTP, IMAPS/POP3S.', 'If it ends in S (or v3), it is usually the secure one.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
