  ('c661b34b-3786-553c-84bf-0f9fb9d7cdb9', '8e78d0cc-996a-501f-8935-b37f4e83ff19', 1, 'LDAPS', true, null),
  ('74a5b4cc-4a0b-5b92-99f4-035149b4b516', '8e78d0cc-996a-501f-8935-b37f4e83ff19', 2, 'SNMPv2c', false, 'SNMPv2c uses cleartext community strings; SNMPv3 adds encryption.'),
  ('d33926b5-016c-5383-86fa-1dfaa03e8be2', '8e78d0cc-996a-501f-8935-b37f4e83ff19', 3, 'TFTP', false, 'TFTP has no authentication or encryption.'),
  ('d8b9558f-092d-5db0-8a95-32ef66a09473', '8e78d0cc-996a-501f-8935-b37f4e83ff19', 4, 'HTTP', false, 'HTTP is cleartext; HTTPS is the secure version.')
insert into public.question_topics (question_id, topic_id) values ('8e78d0cc-996a-501f-8935-b37f4e83ff19', 'secure-protocols') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('d9fd4523-eac2-5ecb-960f-93665c63b80f', 'Which coding practice BEST prevents SQL injection?', 4, 'medium', 'single', 1, 'Parameterized queries keep user input as data rather than executable SQL, so injected syntax cannot change the query''s structure.', 'SQL injection fix = parameterized queries plus server-side input validation.', 'Parameters keep data as data.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('6f21d183-ae7e-588c-aed4-1c42423e7492', 'd9fd4523-eac2-5ecb-960f-93665c63b80f', 0, 'Parameterized queries (prepared statements)', true, null),
  ('4587a47d-06fc-5d71-8f29-be1c11fc6081', 'd9fd4523-eac2-5ecb-960f-93665c63b80f', 1, 'Client-side JavaScript validation only', false, 'Client-side validation is easily bypassed by sending requests directly.'),
  ('4be8fb8e-b6f9-5b55-a82a-a6f936717c03', 'd9fd4523-eac2-5ecb-960f-93665c63b80f', 2, 'Encrypting the database at rest', false, 'Encryption at rest does nothing to stop malicious queries.'),
  ('eda97c74-ca9b-59ba-a5c6-600218b0ab33', 'd9fd4523-eac2-5ecb-960f-93665c63b80f', 3, 'Hiding error messages from users', false, 'Hiding errors makes exploitation harder to see but does not prevent injection.')
insert into public.question_topics (question_id, topic_id) values ('d9fd4523-eac2-5ecb-960f-93665c63b80f', 'application-security'), ('d9fd4523-eac2-5ecb-960f-93665c63b80f', 'application-attacks') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3fdb737c-bd52-587f-b93f-749b5d3176f0', 'Which application security testing method analyzes source code for flaws without running the application?', 4, 'medium', 'single', 1, 'SAST reviews source code, bytecode, or binaries at rest, catching issues early in development.', 'Static = code at rest. Dynamic = running app.', 'Static stands still; dynamic runs.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('35e7a94b-be3c-5867-aa63-8084312e41eb', '3fdb737c-bd52-587f-b93f-749b5d3176f0', 0, 'Static application security testing (SAST)', true, null),
  ('d4f3920c-6f63-5e84-b525-d2e4ed7e1cea', '3fdb737c-bd52-587f-b93f-749b5d3176f0', 1, 'Dynamic application security testing (DAST)', false, 'DAST tests a running application from the outside.'),
  ('34e35eb6-3162-5980-8b54-87ea30ccf2af', '3fdb737c-bd52-587f-b93f-749b5d3176f0', 2, 'Fuzzing', false, 'Fuzzing sends malformed input to a running program.'),
  ('cacb2818-7661-5503-8e3b-ac51ecb0761b', '3fdb737c-bd52-587f-b93f-749b5d3176f0', 3, 'Penetration testing', false, 'Penetration testing actively exploits running systems.')
insert into public.question_topics (question_id, topic_id) values ('3fdb737c-bd52-587f-b93f-749b5d3176f0', 'application-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('96f276de-ed11-54ca-809b-346c3e43d946', 'A company wants to prevent employees from emailing files containing credit card numbers outside the organization. Which solution BEST fits?', 4, 'medium', 'single', 1, 'DLP inspects content leaving endpoints, email, and networks, and can block or quarantine messages containing patterns such as payment card numbers.', 'Stop sensitive data leaving = DLP.', 'DLP guards the exits.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('98b5a9e0-6c04-5582-bfa5-defde6ff3544', '96f276de-ed11-54ca-809b-346c3e43d946', 0, 'Data loss prevention (DLP)', true, null),
  ('bdcb383c-5c18-5399-958f-42ade82dedfb', '96f276de-ed11-54ca-809b-346c3e43d946', 1, 'Network access control (NAC)', false, 'NAC controls which devices can connect to the network.'),
  ('8d3c666f-ada3-5cab-9f95-7c0dfaea7095', '96f276de-ed11-54ca-809b-346c3e43d946', 2, 'Web application firewall', false, 'A WAF protects web applications from incoming attacks.'),
  ('c5396336-6fe4-59f0-ac3e-0d7f3d3c4c17', '96f276de-ed11-54ca-809b-346c3e43d946', 3, 'Full-disk encryption', false, 'Disk encryption protects stored data if a device is lost, not outbound email.')
insert into public.question_topics (question_id, topic_id) values ('96f276de-ed11-54ca-809b-346c3e43d946', 'dlp'), ('96f276de-ed11-54ca-809b-346c3e43d946', 'data-protection'), ('96f276de-ed11-54ca-809b-346c3e43d946', 'email-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9e77ff96-f7df-5006-9092-c2418557f636', 'During a malware investigation on a running workstation, which TWO actions help preserve evidence?', 4, 'hard', 'multiple', 2, 'Volatile memory must be captured before shutdown, and disk images with hashes prove the evidence was not altered. Rebooting, cleaning, or continued use all destroy or change evidence.', 'Preserve evidence: capture volatile data first, image with hashes, avoid changing the system.', 'Capture, hash, then investigate.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('e64b7975-a14b-5790-aad3-67e9f898a5aa', '9e77ff96-f7df-5006-9092-c2418557f636', 0, 'Capture a memory image before powering the system off', true, null),
  ('b95528b4-0975-500a-b744-796f24df3fbf', '9e77ff96-f7df-5006-9092-c2418557f636', 1, 'Create a forensic disk image and record its hash values', true, null),
  ('44d4175c-7b57-5d90-aba1-cc76919659f6', '9e77ff96-f7df-5006-9092-c2418557f636', 2, 'Reboot the system to stop the malware', false, 'Rebooting wipes RAM, including running malware and network connections.'),
  ('76d0b14a-618e-5e98-aa30-cd3d18650fe1', '9e77ff96-f7df-5006-9092-c2418557f636', 3, 'Run antivirus to delete the malicious files', false, 'Deleting files destroys evidence needed for analysis.'),
  ('d2321d86-8760-5904-9614-b51b3e5c43f0', '9e77ff96-f7df-5006-9092-c2418557f636', 4, 'Let the user keep working until the end of the day', false, 'Continued use overwrites data and risks further damage.')
insert into public.question_topics (question_id, topic_id) values ('9e77ff96-f7df-5006-9092-c2418557f636', 'forensics'), ('9e77ff96-f7df-5006-9092-c2418557f636', 'incident-response') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 'A security team wants to know when devices connecting to the network are missing required patches or antivirus, and automatically move them to a quarantine VLAN. Which solution BEST fits?', 4, 'medium', 'single', 1, 'NAC checks device health (posture) at connection time and enforces policy, such as placing noncompliant devices in a remediation VLAN.', 'Check device health before granting network access = NAC.', 'NAC checks your health at the door.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('23aa1a2f-bdc5-5a07-9d60-41e2d2953b24', 'b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 0, 'Network access control (NAC) with posture assessment', true, null),
  ('fc151a69-40cd-549d-b3a3-f6c58879bf5a', 'b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 1, 'A honeynet', false, 'A honeynet is a decoy network for attackers.'),
  ('140ede62-893f-5334-8f4c-b82dd0b8e4c3', 'b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 2, 'A forward proxy', false, 'A forward proxy filters outbound web requests.'),
  ('bf156349-be29-5be6-a672-d91997ce4bce', 'b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 3, 'A SIEM dashboard', false, 'A SIEM can report on compliance but does not enforce network placement.')
insert into public.question_topics (question_id, topic_id) values ('b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 'network-security'), ('b4f55ba6-48a9-5015-a86f-69ba0f881bfe', 'endpoint-security') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9e121ad2-f8f4-5496-8016-144a1dacb1cc', 'Which type of governance document states management''s high-level intent, such as ''All company data must be classified by sensitivity''?', 5, 'medium', 'single', 1, 'A policy is a broad, mandatory statement of management intent. Standards, procedures, and guidelines support it with specifics.', 'Policy = why/what (high level). Standard = specific mandatory rule. Procedure = how, step by step. Guideline = recommended.', 'Policies point the direction; procedures give the directions.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8ae80eda-ec41-5660-b0f3-03356fe74083', '9e121ad2-f8f4-5496-8016-144a1dacb1cc', 0, 'Policy', true, null),
  ('3260b1c8-09e3-5310-843c-9eb58ad9f649', '9e121ad2-f8f4-5496-8016-144a1dacb1cc', 1, 'Procedure', false, 'A procedure gives step-by-step instructions for performing a task.'),
  ('fd5c1eab-e5c2-558a-9fe9-221b6b8432c3', '9e121ad2-f8f4-5496-8016-144a1dacb1cc', 2, 'Guideline', false, 'A guideline offers recommended, optional practices.'),
  ('fe77768f-78e9-567c-bbee-b64e78f48753', '9e121ad2-f8f4-5496-8016-144a1dacb1cc', 3, 'Standard', false, 'A standard sets specific mandatory requirements, such as a required encryption algorithm.')
insert into public.question_topics (question_id, topic_id) values ('9e121ad2-f8f4-5496-8016-144a1dacb1cc', 'governance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('5e8dca5f-a4b7-58d9-8d64-939e116e9216', 'A document requires all company laptops to use AES-256 full-disk encryption. What type of document is this MOST likely?', 5, 'medium', 'single', 1, 'Standards specify mandatory technologies, configurations, or methods that support a policy. Naming a specific algorithm and scope is characteristic of a standard.', 'Specific, measurable, mandatory technical requirement = standard.', 'A standard sets the bar you must meet.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('031e9b15-6f75-5d94-87b9-5884ad684064', '5e8dca5f-a4b7-58d9-8d64-939e116e9216', 0, 'Guideline', false, 'Guidelines are recommendations, not requirements.'),
  ('08608099-37f3-5bdd-8a57-75a5aced72b9', '5e8dca5f-a4b7-58d9-8d64-939e116e9216', 1, 'Standard', true, null),
  ('6127ee8a-9f70-5122-bbcf-ae54dc2ddfa7', '5e8dca5f-a4b7-58d9-8d64-939e116e9216', 2, 'Policy', false, 'A policy would state intent, such as ''data on mobile devices must be protected'', without naming AES-256.'),
  ('9c8a973b-7241-55d6-ac91-f2725afe40a3', '5e8dca5f-a4b7-58d9-8d64-939e116e9216', 3, 'Procedure', false, 'A procedure would list the steps to enable the encryption.')
insert into public.question_topics (question_id, topic_id) values ('5e8dca5f-a4b7-58d9-8d64-939e116e9216', 'governance'), ('5e8dca5f-a4b7-58d9-8d64-939e116e9216', 'encryption') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 'Which document do employees typically sign to acknowledge the rules for using company systems, email, and internet access?', 5, 'easy', 'single', 1, 'An AUP defines permitted and prohibited uses of organizational resources, and signing it establishes the user''s acknowledgment.', 'Employee rules for using company systems = AUP.', 'AUP: what you may and may not do with company stuff.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('73a6dc9d-876b-5efc-a100-e6150a84a7c1', '0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 0, 'Acceptable use policy (AUP)', true, null),
  ('12d355a9-0071-5c27-a9d1-8fa9a599eace', '0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 1, 'Service level agreement (SLA)', false, 'An SLA defines service performance between a provider and customer.'),
  ('e0d19f6c-9eba-51d2-995a-e36c54608ba9', '0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 2, 'Business partners agreement (BPA)', false, 'A BPA governs a partnership between businesses.'),
  ('e89c3cf8-2df1-5f91-8726-23b75dccd550', '0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 3, 'Memorandum of understanding (MOU)', false, 'An MOU records a general, often non-binding, understanding between organizations.')
insert into public.question_topics (question_id, topic_id) values ('0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 'governance'), ('0fd8f0b9-d9c3-5edd-926d-00e3b96b5d93', 'security-awareness') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9dd3e68c-ace2-583d-8249-493c0e091b42', 'A server is valued at $20,000. A flood would destroy 40% of its value. What is the single loss expectancy (SLE)?', 5, 'medium', 'single', 1, 'SLE = asset value x exposure factor = $20,000 x 0.40 = $8,000.', 'SLE = AV x EF. ALE = SLE x ARO.', 'Single loss: how much one event costs.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ecfff8b9-9a09-59bf-bad6-b5cb92e7a32e', '9dd3e68c-ace2-583d-8249-493c0e091b42', 0, '$4,000', false, '$4,000 would be a 20% exposure factor.'),
  ('d925da81-1bbd-5024-9197-1ab82e1968a5', '9dd3e68c-ace2-583d-8249-493c0e091b42', 1, '$8,000', true, null),
  ('37df230d-5b52-5094-9e06-bff572441b02', '9dd3e68c-ace2-583d-8249-493c0e091b42', 2, '$12,000', false, '$12,000 is the value that would remain (60%), not the loss.'),
  ('ffebd8c1-7d8d-560a-9d81-124e51a5a535', '9dd3e68c-ace2-583d-8249-493c0e091b42', 3, '$20,000', false, '$20,000 is the full asset value, which assumes total loss.')
insert into public.question_topics (question_id, topic_id) values ('9dd3e68c-ace2-583d-8249-493c0e091b42', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 'The single loss expectancy of a data breach is $50,000, and such a breach is expected to occur once every four years. What is the annualized loss expectancy (ALE)?', 5, 'medium', 'single', 1, 'Once every four years means an annualized rate of occurrence of 0.25. ALE = $50,000 x 0.25 = $12,500.', 'Convert frequency to ARO: once every N years = 1/N.', 'ALE spreads one loss over the years it takes to happen.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('76e3a853-4702-593d-bead-19eb12c2b4f1', '1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 0, '$12,500', true, null),
  ('4678a7b1-5f0c-5e89-bb86-0df94aa798be', '1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 1, '$50,000', false, '$50,000 is the SLE, not the annualized loss.'),
  ('ff48ec85-9404-5a4c-b8c4-af154e41cdf4', '1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 2, '$200,000', false, '$200,000 incorrectly multiplies by 4 instead of 1/4.'),
  ('195560a2-5b8d-5107-a1e7-461092b4f041', '1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 3, '$25,000', false, '$25,000 would correspond to once every two years.')
insert into public.question_topics (question_id, topic_id) values ('1e0a57b9-b98e-5317-a47c-39ab5cf788f4', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b52cca3c-6ed2-5172-aa3f-96eb235318e0', 'A company purchases a cyber insurance policy to cover financial losses from ransomware. Which risk response is this?', 5, 'easy', 'single', 1, 'Insurance shifts the financial impact of a risk to a third party, which is risk transference.', 'Insurance or outsourcing liability = transfer.', 'Transfer: hand the bill to someone else.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('af6de6f4-c952-537a-b570-8989eb4ad90d', 'b52cca3c-6ed2-5172-aa3f-96eb235318e0', 0, 'Acceptance', false, 'Acceptance means acknowledging the risk and taking no further action.'),
  ('79e6498e-7bbc-5988-86e6-ab6fc97b7e56', 'b52cca3c-6ed2-5172-aa3f-96eb235318e0', 1, 'Avoidance', false, 'Avoidance means stopping the risky activity entirely.'),
  ('14a230ce-0cd2-5d9a-9e1b-5db1ea0d1040', 'b52cca3c-6ed2-5172-aa3f-96eb235318e0', 2, 'Transference', true, null),
  ('e96bb6e3-fdf2-5717-9994-41dc90c5adb6', 'b52cca3c-6ed2-5172-aa3f-96eb235318e0', 3, 'Mitigation', false, 'Mitigation reduces likelihood or impact with controls.')
insert into public.question_topics (question_id, topic_id) values ('b52cca3c-6ed2-5172-aa3f-96eb235318e0', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('0a54c8a0-e345-5b2f-924a-219de61bb9af', 'A company discontinues a legacy file-transfer service because securing it would cost more than the revenue it generates. Which risk response is this?', 5, 'medium', 'single', 1, 'Stopping the activity that creates the risk eliminates the risk entirely. That is avoidance.', 'Stop doing the risky thing = avoid.', 'Avoid it by not doing it.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a98e3407-a5cb-5065-89a5-d0fdec8aac60', '0a54c8a0-e345-5b2f-924a-219de61bb9af', 0, 'Avoidance', true, null),
  ('549565a1-f6fd-5bfd-a860-4e22f22e44b2', '0a54c8a0-e345-5b2f-924a-219de61bb9af', 1, 'Acceptance', false, 'Acceptance would keep the service running and live with the risk.'),
  ('136021df-587a-5034-9699-c8e949b253e8', '0a54c8a0-e345-5b2f-924a-219de61bb9af', 2, 'Transference', false, 'Transference would shift the impact to a third party, such as an insurer.'),
  ('59604cdb-5319-5573-80f6-835d73dfd531', '0a54c8a0-e345-5b2f-924a-219de61bb9af', 3, 'Mitigation', false, 'Mitigation would add controls while keeping the service.')
insert into public.question_topics (question_id, topic_id) values ('0a54c8a0-e345-5b2f-924a-219de61bb9af', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('b96893ff-5283-51fa-9cb8-8bb805198b05', 'Which TWO actions are examples of risk mitigation?', 5, 'medium', 'multiple', 2, 'Mitigation reduces a risk''s likelihood or impact by implementing controls. Patching and MFA both reduce the chance of successful attacks.', 'Adding a control = mitigate. Insurance = transfer. Stop = avoid. Sign-off = accept.', 'Mitigate means make it smaller.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('b3989e52-cdc0-5f40-8b1a-3af6260f88df', 'b96893ff-5283-51fa-9cb8-8bb805198b05', 0, 'Applying security patches to vulnerable servers', true, null),
  ('12cdc45a-a1d7-5453-bbde-474b953fcc6b', 'b96893ff-5283-51fa-9cb8-8bb805198b05', 1, 'Requiring multifactor authentication for remote access', true, null),
  ('67b6625c-3ef6-598c-b5ba-df82ce645221', 'b96893ff-5283-51fa-9cb8-8bb805198b05', 2, 'Purchasing cyber insurance', false, 'Insurance transfers risk.'),
  ('a8d11e63-ce4f-580b-8d9e-a5232fdd7f1f', 'b96893ff-5283-51fa-9cb8-8bb805198b05', 3, 'Formally accepting a risk with executive sign-off', false, 'Formal sign-off is risk acceptance.'),
  ('8ceab9ab-8271-5f05-920f-5a9a4ce095a6', 'b96893ff-5283-51fa-9cb8-8bb805198b05', 4, 'Discontinuing a risky product line', false, 'Discontinuing the activity is avoidance.')
insert into public.question_topics (question_id, topic_id) values ('b96893ff-5283-51fa-9cb8-8bb805198b05', 'risk-management'), ('b96893ff-5283-51fa-9cb8-8bb805198b05', 'mitigation-techniques') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('84443d13-d92a-58a8-87df-3fc188fd94b1', 'Which document lists identified risks along with their owners, likelihood, impact, and planned responses?', 5, 'easy', 'single', 1, 'A risk register is the central record used to track risks, their ratings, owners, and treatment decisions over time.', 'Central list of risks with owners and responses = risk register.', 'The register records every risk.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8913bf43-c474-5478-82d3-b3c35693fbba', '84443d13-d92a-58a8-87df-3fc188fd94b1', 0, 'Risk register', true, null),
  ('754d3f4f-3cdd-57f4-9916-a3bca035b5c2', '84443d13-d92a-58a8-87df-3fc188fd94b1', 1, 'Business impact analysis', false, 'A BIA identifies critical functions and recovery requirements.'),
  ('35c6a9a2-6cad-54c7-84fe-10e9715583f4', '84443d13-d92a-58a8-87df-3fc188fd94b1', 2, 'Rules of engagement', false, 'Rules of engagement define the conditions of a penetration test.'),
  ('748fe733-5465-5431-8f2f-514904119a09', '84443d13-d92a-58a8-87df-3fc188fd94b1', 3, 'Asset inventory', false, 'An asset inventory lists hardware, software, and data assets.')
insert into public.question_topics (question_id, topic_id) values ('84443d13-d92a-58a8-87df-3fc188fd94b1', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 'The overall amount of risk an organization is willing to pursue or retain to achieve its objectives is called its:', 5, 'medium', 'single', 1, 'Risk appetite is leadership''s broad statement of how much risk is acceptable. It guides decisions about which risks to accept or treat.', 'Willingness to take risk = appetite. Remaining after controls = residual. Before controls = inherent.', 'Appetite: how much risk the organization is hungry for.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a7c91325-e977-58ef-b3be-68df594dfc7b', '48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 0, 'Risk appetite', true, null),
  ('9cb7af4f-ae8e-507f-b694-a775c2e545a9', '48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 1, 'Residual risk', false, 'Residual risk is what remains after controls are applied.'),
  ('99b1335b-dd7a-5c07-a1c6-974e7f741cf2', '48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 2, 'Inherent risk', false, 'Inherent risk is the risk before any controls are applied.'),
  ('0d228469-0949-5be6-8609-96a96ab7177e', '48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 3, 'Key risk indicator', false, 'A KRI is a metric that signals changes in risk exposure.')
insert into public.question_topics (question_id, topic_id) values ('48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 'risk-management'), ('48abdfcb-2d32-5c24-81b3-619baaf3ac5a', 'governance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 'After a company implements firewalls, MFA, and encryption, some risk of a data breach remains. What is this remaining risk called?', 5, 'easy', 'single', 1, 'Residual risk is the risk left after controls are applied. It should fall within the organization''s risk appetite.', 'Left over after controls = residual.', 'Residual is the residue after cleaning up.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7a709550-12cb-514a-8605-c005636202c0', '931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 0, 'Inherent risk', false, 'Inherent risk exists before controls are applied.'),
  ('6e25b909-0659-5375-b841-35c98c2d9261', '931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 1, 'Residual risk', true, null),
  ('37f7c59b-c195-5e63-af97-cc75c98efbe0', '931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 2, 'Risk appetite', false, 'Risk appetite is the level of risk the organization is willing to accept.'),
  ('cb9706c3-e257-5807-b5b2-343e803bdea7', '931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 3, 'Control risk', false, 'Control risk is the chance that a control itself fails.')
insert into public.question_topics (question_id, topic_id) values ('931aaa22-ce48-57a2-89ad-e10a5d3c6ddf', 'risk-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('9b8b8569-1f81-59ea-8661-349793bb2b3e', 'A business impact analysis determines that the order-processing system must be restored within four hours of an outage. Which metric is this?', 5, 'medium', 'single', 1, 'RTO is the maximum acceptable time to restore a system after a disruption.', 'How long can we be down? = RTO. How much data can we lose? = RPO.', 'RTO = Time to recover. RPO = Point we recover to.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('75bc537d-7210-5bf0-9740-0767e1cfda3d', '9b8b8569-1f81-59ea-8661-349793bb2b3e', 0, 'Recovery point objective (RPO)', false, 'RPO is the maximum acceptable amount of data loss, measured in time.'),
  ('7fc65544-8fed-5ba9-bcbe-7f195c6c51ba', '9b8b8569-1f81-59ea-8661-349793bb2b3e', 1, 'Recovery time objective (RTO)', true, null),
  ('3b224c81-d9a1-57a4-8c98-26ede978c610', '9b8b8569-1f81-59ea-8661-349793bb2b3e', 2, 'Mean time between failures (MTBF)', false, 'MTBF measures average time between failures, a reliability metric.'),
  ('5e8eb056-3c3b-5567-97e4-8101e5a362db', '9b8b8569-1f81-59ea-8661-349793bb2b3e', 3, 'Mean time to repair (MTTR)', false, 'MTTR measures the average time to repair a component.')
insert into public.question_topics (question_id, topic_id) values ('9b8b8569-1f81-59ea-8661-349793bb2b3e', 'business-impact-analysis'), ('9b8b8569-1f81-59ea-8661-349793bb2b3e', 'disaster-recovery') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 'Management states that the company can lose no more than 15 minutes of transaction data. Which approach BEST meets this recovery point objective?', 5, 'hard', 'single', 1, 'The RPO dictates backup or replication frequency. To lose at most 15 minutes of data, copies must be taken at least every 15 minutes or continuously.', 'RPO drives backup frequency. RTO drives recovery speed and site choice.', 'Back up at least as often as the data you can afford to lose.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('65af2574-dee1-5e49-aa6c-99a5638496e3', '36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 0, 'Nightly full backups', false, 'Nightly backups could lose up to 24 hours of data.'),
  ('e2e6d444-3060-5dde-9c9b-753866532dc1', '36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 1, 'Weekly full backups with daily incremental backups', false, 'Daily incrementals could lose up to a day of data.'),
  ('f1fc2188-bd6c-5876-9a6f-3352f2005b10', '36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 2, 'Continuous replication or backups taken at least every 15 minutes', true, null),
  ('1d4759b7-34b4-530d-adb9-3eabe6f09b17', '36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 3, 'A hot site with no data replication', false, 'A hot site without current data still loses everything since the last copy.')
insert into public.question_topics (question_id, topic_id) values ('36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 'business-impact-analysis'), ('36a16d5f-8978-5ad5-b6b6-bb4a7f1d2909', 'backups') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('8a89358f-386a-57c7-8d5a-939c3dc63a20', 'Which metric represents the average time required to repair a failed component and return it to service?', 5, 'easy', 'single', 1, 'Mean time to repair (recover) measures how quickly a failed component is fixed. Lower MTTR means faster recovery.', 'Repair speed = MTTR. Reliability = MTBF (higher is better).', 'MTTR: Mean Time To Repair.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('e9e53f57-2faf-5be8-aca1-c4cd27b04bb3', '8a89358f-386a-57c7-8d5a-939c3dc63a20', 0, 'MTBF', false, 'MTBF is the average time a system operates between failures.'),
  ('8d7a975f-6466-5212-a0e0-785ab16b5df5', '8a89358f-386a-57c7-8d5a-939c3dc63a20', 1, 'MTTR', true, null),
  ('9ae80eb9-e2d9-5d5e-a644-38d572e9bb34', '8a89358f-386a-57c7-8d5a-939c3dc63a20', 2, 'RPO', false, 'RPO is the acceptable data loss window.'),
  ('28a64378-5d7a-5e01-81ba-2795e3032239', '8a89358f-386a-57c7-8d5a-939c3dc63a20', 3, 'ARO', false, 'ARO is how often a risk event is expected per year.')
insert into public.question_topics (question_id, topic_id) values ('8a89358f-386a-57c7-8d5a-939c3dc63a20', 'business-impact-analysis'), ('8a89358f-386a-57c7-8d5a-939c3dc63a20', 'resilience') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 'A retailer processes and stores customer credit card payments. Which standard governs how it must protect cardholder data?', 5, 'easy', 'single', 1, 'The Payment Card Industry Data Security Standard applies to organizations that store, process, or transmit cardholder data.', 'Credit cards = PCI DSS. Health data = HIPAA. Public company financials = SOX.', 'PCI protects the Plastic Card Information.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('17236fa2-95b9-5ffe-85af-e4c2e67f9c38', '3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 0, 'PCI DSS', true, null),
  ('6e75e105-387d-5ef9-be5c-6137545dd19d', '3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 1, 'HIPAA', false, 'HIPAA governs protected health information in the US.'),
  ('07dc3aa5-8ac4-5b7f-bf2a-fb23eaf09541', '3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 2, 'SOX', false, 'SOX governs financial reporting controls of US public companies.'),
  ('51fe11a8-b3cf-5f1d-8ac8-ba3fcacc564f', '3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 3, 'FERPA', false, 'FERPA protects student education records in the US.')
insert into public.question_topics (question_id, topic_id) values ('3be810e0-d9b9-59ea-ad1a-efe0d1cb6313', 'compliance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('548cdd1c-3f82-5755-a8ee-45d39218ea3e', 'Under privacy regulations such as the GDPR, which role determines the purposes and means of processing personal data?', 5, 'medium', 'single', 1, 'The data controller decides why and how personal data is processed and carries primary accountability for compliance.', 'Decides why and how = controller. Processes on its behalf = processor.', 'The controller is in control of the purpose.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('32062334-86dc-58c8-812a-f34f66ccdead', '548cdd1c-3f82-5755-a8ee-45d39218ea3e', 0, 'Data processor', false, 'A processor handles data on behalf of the controller, following its instructions.'),
  ('ff9cb16c-a32e-51da-8bff-020bddb53ef6', '548cdd1c-3f82-5755-a8ee-45d39218ea3e', 1, 'Data controller', true, null),
  ('34f9cd6e-4749-5d83-af51-e1da0dc12e83', '548cdd1c-3f82-5755-a8ee-45d39218ea3e', 2, 'Data custodian', false, 'A custodian implements and maintains technical controls for data.'),
  ('33ec1c7b-8b8f-5b4c-8a08-8e2bc028a82f', '548cdd1c-3f82-5755-a8ee-45d39218ea3e', 3, 'Data subject', false, 'The data subject is the individual the data is about.')
insert into public.question_topics (question_id, topic_id) values ('548cdd1c-3f82-5755-a8ee-45d39218ea3e', 'data-privacy'), ('548cdd1c-3f82-5755-a8ee-45d39218ea3e', 'compliance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('838e7108-ad14-5a5c-9065-98f6d2b7998b', 'A customer asks a company to permanently delete all personal data it holds about them. Which privacy right is being exercised?', 5, 'easy', 'single', 1, 'The right to erasure lets individuals request deletion of their personal data when there is no overriding reason to keep it.', 'Delete my data = right to be forgotten (erasure).', 'Forget me means erase me.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('17851b63-18a1-52ec-8b19-723f80d90a0b', '838e7108-ad14-5a5c-9065-98f6d2b7998b', 0, 'Right to be forgotten (erasure)', true, null),
  ('6f1bb615-c03a-59c5-b9e6-92929e08ef8b', '838e7108-ad14-5a5c-9065-98f6d2b7998b', 1, 'Right to data portability', false, 'Portability is receiving one''s data in a usable format to move elsewhere.'),
  ('662b0c48-31ac-55cd-a36a-3e0d0d142d14', '838e7108-ad14-5a5c-9065-98f6d2b7998b', 2, 'Right of access', false, 'Access is the right to see what data is held.'),
  ('811bbfb1-eee8-5049-9891-a935a4685ba3', '838e7108-ad14-5a5c-9065-98f6d2b7998b', 3, 'Right to object to profiling', false, 'Objecting to profiling limits certain automated processing.')
insert into public.question_topics (question_id, topic_id) values ('838e7108-ad14-5a5c-9065-98f6d2b7998b', 'data-privacy') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('f672c8c0-627f-596b-bb32-2b07ba57d59c', 'Who is typically accountable for classifying a dataset and deciding who may access it?', 5, 'medium', 'single', 1, 'The data owner, usually a senior business leader, is accountable for the data''s classification and access decisions.', 'Accountable and decides = owner. Implements and maintains = custodian.', 'Owners decide; custodians do.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('55ce9cd8-56a2-58df-b18a-bb58d312a569', 'f672c8c0-627f-596b-bb32-2b07ba57d59c', 0, 'Data owner', true, null),
  ('aa399a40-3bb9-55c5-bdfb-cccb94bddf03', 'f672c8c0-627f-596b-bb32-2b07ba57d59c', 1, 'Data custodian', false, 'Custodians implement the owner''s decisions, such as backups and permissions.'),
  ('a9398d16-b6ed-52d4-8518-9e51776083fd', 'f672c8c0-627f-596b-bb32-2b07ba57d59c', 2, 'Data processor', false, 'Processors handle data on behalf of a controller.'),
  ('0e919dac-8d75-590a-aedd-c6501665dc1c', 'f672c8c0-627f-596b-bb32-2b07ba57d59c', 3, 'Data subject', false, 'Subjects are the people the data describes.')
insert into public.question_topics (question_id, topic_id) values ('f672c8c0-627f-596b-bb32-2b07ba57d59c', 'governance'), ('f672c8c0-627f-596b-bb32-2b07ba57d59c', 'data-protection') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('565fb79e-2d60-5cde-ba35-0d22742884eb', 'Which agreement defines measurable performance levels, such as 99.9% uptime, and the remedies if they are not met?', 5, 'easy', 'single', 1, 'An SLA defines service metrics such as uptime and response times, plus penalties or credits if the provider falls short.', 'Uptime, response times, penalties = SLA.', 'SLA: the Service Level you Agreed to.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('a1ee4407-d106-576d-a07d-03575bef1e5b', '565fb79e-2d60-5cde-ba35-0d22742884eb', 0, 'Service level agreement (SLA)', true, null),
  ('f70637a9-9f17-5674-a01e-46b96e184952', '565fb79e-2d60-5cde-ba35-0d22742884eb', 1, 'Non-disclosure agreement (NDA)', false, 'An NDA protects confidential information shared between parties.'),
  ('57f89075-533f-50ed-aaf6-eb4f39e6d40a', '565fb79e-2d60-5cde-ba35-0d22742884eb', 2, 'Memorandum of understanding (MOU)', false, 'An MOU describes a general understanding and is often not legally binding.'),
  ('e2b99dad-3deb-5e94-a863-aefe1c99dbfd', '565fb79e-2d60-5cde-ba35-0d22742884eb', 3, 'Statement of work (SOW)', false, 'A SOW describes specific deliverables and tasks for a project.')
insert into public.question_topics (question_id, topic_id) values ('565fb79e-2d60-5cde-ba35-0d22742884eb', 'vendor-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('2a718e5c-3279-5100-b0bd-c78d54024bdf', 'Two companies sign a broad agreement establishing general terms, such as payment and liability, that will govern many future projects. Specific projects will be defined later in separate documents. Which agreement is this?', 5, 'medium', 'single', 1, 'An MSA sets the overarching terms of a relationship, so future work orders or SOWs only need to specify project details.', 'Umbrella terms for future work = MSA. Specific project = SOW or work order.', 'The master agreement covers everything that follows.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('f1999e2c-9d30-5466-a1fc-d428e82e3c12', '2a718e5c-3279-5100-b0bd-c78d54024bdf', 0, 'Master service agreement (MSA)', true, null),
  ('96643bc8-fbb1-54dd-b98d-9310a1818d66', '2a718e5c-3279-5100-b0bd-c78d54024bdf', 1, 'Statement of work (SOW)', false, 'A SOW defines a specific project''s scope and deliverables under an MSA.'),
  ('a922bc52-0c41-54a7-9904-d70ac4f1effd', '2a718e5c-3279-5100-b0bd-c78d54024bdf', 2, 'Non-disclosure agreement (NDA)', false, 'An NDA covers confidentiality only.'),
  ('ab22f7c4-7871-5e17-90fd-c8b98c1ba12e', '2a718e5c-3279-5100-b0bd-c78d54024bdf', 3, 'Service level agreement (SLA)', false, 'An SLA defines performance metrics.')
insert into public.question_topics (question_id, topic_id) values ('2a718e5c-3279-5100-b0bd-c78d54024bdf', 'vendor-management') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 'Before signing with a new cloud payroll provider, a company wants assurance that the vendor''s security controls operate effectively. Which is the BEST evidence to request?', 5, 'hard', 'single', 1, 'A SOC 2 Type II report is produced by an independent auditor and tests whether controls operated effectively over a period of time, providing objective assurance.', 'Objective assurance about a vendor = independent audit or attestation report.', 'Trust the auditor''s report over the vendor''s brochure.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('e22a01a4-d44e-5fd6-96f4-74198995d758', '11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 0, 'An independent third-party audit report, such as a SOC 2 Type II', true, null),
  ('8b3b18c4-1ba1-578d-8380-c62d391ae9ee', '11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 1, 'The vendor''s marketing whitepaper on security', false, 'Marketing materials are self-reported and unverified.'),
  ('2219d502-f5fb-5b0b-a8e9-5812c7bbfef4', '11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 2, 'A signed non-disclosure agreement', false, 'An NDA protects confidentiality but says nothing about control effectiveness.'),
  ('8e18cfe8-6228-5fb9-93ec-1ef44132f955', '11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 3, 'The vendor''s public privacy policy', false, 'A privacy policy states intentions, not tested control effectiveness.')
insert into public.question_topics (question_id, topic_id) values ('11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 'vendor-management'), ('11b47a45-b3e9-5a1d-8e48-6de6a20ce244', 'audits') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('c476abd8-07da-52ac-bac2-81440523255b', 'Which contract clause lets a company assess a vendor''s security practices directly or through a third party?', 5, 'medium', 'single', 1, 'A right-to-audit clause gives the customer contractual permission to evaluate the vendor''s controls.', 'Want to verify a vendor''s controls yourself = right-to-audit clause.', 'Put the right to check in writing.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('7070a3f8-d0c0-51a3-951c-865cfb46e834', 'c476abd8-07da-52ac-bac2-81440523255b', 0, 'Right-to-audit clause', true, null),
  ('d3c1310b-823a-585e-8922-68c99b5efa65', 'c476abd8-07da-52ac-bac2-81440523255b', 1, 'Non-compete clause', false, 'A non-compete restricts competitive activity.'),
  ('f1c37659-4b7c-59c2-8692-af15b85bd1ae', 'c476abd8-07da-52ac-bac2-81440523255b', 2, 'Force majeure clause', false, 'Force majeure excuses performance during extraordinary events.'),
  ('b949d723-1506-5893-b850-e3f0477cc6dc', 'c476abd8-07da-52ac-bac2-81440523255b', 3, 'Indemnification clause', false, 'Indemnification assigns responsibility for certain losses.')
insert into public.question_topics (question_id, topic_id) values ('c476abd8-07da-52ac-bac2-81440523255b', 'vendor-management'), ('c476abd8-07da-52ac-bac2-81440523255b', 'audits') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('3e8026af-22f2-5128-9076-7bd534e74590', 'In which type of penetration test does the tester receive full details about the target environment, including network diagrams and source code?', 5, 'easy', 'single', 1, 'A known-environment (white box) test gives testers full information, allowing thorough coverage in less time.', 'Full knowledge = known (white box). None = unknown (black box). Some = partially known (gray box).', 'Known environment: nothing is hidden from the tester.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('cf243773-1019-5456-bfd6-eb856da3715f', '3e8026af-22f2-5128-9076-7bd534e74590', 0, 'Known environment', true, null),
  ('e78a9fd5-e520-5d6f-b696-826ea65c3ff8', '3e8026af-22f2-5128-9076-7bd534e74590', 1, 'Unknown environment', false, 'Unknown-environment (black box) testers start with little or no information.'),
  ('27b7b92c-311e-5c0a-83d1-94618d3cc3cf', '3e8026af-22f2-5128-9076-7bd534e74590', 2, 'Partially known environment', false, 'Partially known (gray box) testers receive some, but not full, information.'),
  ('ce32d280-4e99-5c34-9a99-b74f8e28fb1a', '3e8026af-22f2-5128-9076-7bd534e74590', 3, 'Passive reconnaissance only', false, 'Passive reconnaissance is an information-gathering technique, not a test type.')
insert into public.question_topics (question_id, topic_id) values ('3e8026af-22f2-5128-9076-7bd534e74590', 'penetration-testing') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 'Which penetration testing activity gathers publicly available information about a target without directly interacting with its systems?', 5, 'medium', 'single', 1, 'Passive reconnaissance uses sources such as public websites, DNS records, and social media (OSINT) without touching the target''s systems, so it is hard to detect.', 'No direct contact with the target = passive. Scanning or probing = active.', 'Passive recon only watches from a distance.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('bebff3f7-e4e9-50a6-8693-2a1556405e64', '33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 0, 'Passive reconnaissance', true, null),
  ('70f607af-2f19-5237-86b3-f1d090eafd2e', '33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 1, 'Active reconnaissance', false, 'Active reconnaissance directly probes systems, for example with port scans.'),
  ('a4a21209-75d0-5347-8722-55d80c413716', '33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 2, 'Privilege escalation', false, 'Privilege escalation gains higher permissions after initial access.'),
  ('b4734dca-085b-5757-b389-6b65bc6716c4', '33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 3, 'Lateral movement', false, 'Lateral movement pivots between systems after compromise.')
insert into public.question_topics (question_id, topic_id) values ('33952f27-bbcc-5922-8ba1-82b10bd9f0c7', 'penetration-testing') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 'Before a penetration test begins, which document defines the scope, testing windows, permitted techniques, and emergency contacts?', 5, 'easy', 'single', 1, 'Rules of engagement set the boundaries and logistics of a test and, together with written authorization, protect both the tester and the client.', 'Scope + timing + allowed techniques + contacts = rules of engagement.', 'RoE: the rules of the game before anyone plays.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('513aa402-9da5-58b7-aab9-cfad9768eabf', '24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 0, 'Rules of engagement', true, null),
  ('7d2d550c-f99f-5b8c-9dcd-2eaf970d0bd1', '24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 1, 'Service level agreement', false, 'An SLA defines service performance levels.'),
  ('b2fdcb4e-01f3-5e51-9bfa-1400abff3e18', '24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 2, 'Acceptable use policy', false, 'An AUP governs employee use of company systems.'),
  ('25f64ca6-5ff7-565c-beb9-65a3ff7a8e06', '24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 3, 'Business impact analysis', false, 'A BIA identifies critical processes and recovery requirements.')
insert into public.question_topics (question_id, topic_id) values ('24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 'rules-of-engagement'), ('24d84479-5fdb-5bc1-91dc-b3b0df755f5f', 'penetration-testing') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('7014696b-b83d-5137-b449-28d940f04f99', 'During an authorized penetration test, a tester discovers a customer database server on an IP range that is not listed in the scope. What should the tester do?', 5, 'hard', 'single', 1, 'Testing outside the authorized scope can be illegal and may affect systems the client does not own. The tester must stay within scope and ask the client for clarification.', 'Anything out of scope = do not touch it; escalate to the client contact.', 'If it is not in scope, it is not yours to test.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('12ff205a-f083-56d2-833c-b303490e8ca2', '7014696b-b83d-5137-b449-28d940f04f99', 0, 'Exploit the server to demonstrate the risk to the client', false, 'Exploiting an out-of-scope system exceeds authorization.'),
  ('257ee345-5d96-5899-bfd4-d69617fc2665', '7014696b-b83d-5137-b449-28d940f04f99', 1, 'Stop, do not test the server, and contact the client''s designated point of contact', true, null),
  ('4d14391e-8e8f-595e-9d84-e1518a6cdfc3', '7014696b-b83d-5137-b449-28d940f04f99', 2, 'Run a light vulnerability scan since it is probably owned by the client', false, 'Even light scanning is testing without authorization.'),
  ('9ebb073f-d449-5ac0-a223-e3125cfed620', '7014696b-b83d-5137-b449-28d940f04f99', 3, 'Collect credentials from the server for the final report', false, 'Collecting credentials from an unauthorized system is a serious violation.')
insert into public.question_topics (question_id, topic_id) values ('7014696b-b83d-5137-b449-28d940f04f99', 'rules-of-engagement'), ('7014696b-b83d-5137-b449-28d940f04f99', 'penetration-testing') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('859ca377-24fe-5b84-a67b-47e73420f2d7', 'Which type of assessment is performed by an independent outside party to provide assurance to regulators, customers, or shareholders?', 5, 'easy', 'single', 1, 'External audits are conducted by independent third parties, which gives their findings credibility with outside stakeholders.', 'Independence and outside assurance = external audit.', 'External eyes, independent opinion.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('ec4ec935-625e-52b3-ae5c-8fda83bda43e', '859ca377-24fe-5b84-a67b-47e73420f2d7', 0, 'External audit', true, null),
  ('96758d6d-b2ee-58e3-b0e2-1fadac255efb', '859ca377-24fe-5b84-a67b-47e73420f2d7', 1, 'Internal self-assessment', false, 'A self-assessment is performed internally and lacks independence.'),
  ('608794f5-726d-553a-aca6-13687a039d6d', '859ca377-24fe-5b84-a67b-47e73420f2d7', 2, 'Tabletop exercise', false, 'A tabletop exercise tests incident response plans through discussion.'),
  ('2402c721-5e3a-52b4-8e18-79acbf78ef96', '859ca377-24fe-5b84-a67b-47e73420f2d7', 3, 'Vulnerability scan by the IT team', false, 'An internal scan is useful but not independent assurance.')
insert into public.question_topics (question_id, topic_id) values ('859ca377-24fe-5b84-a67b-47e73420f2d7', 'audits'), ('859ca377-24fe-5b84-a67b-47e73420f2d7', 'compliance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 'A simulated phishing campaign shows that 30% of employees clicked the link. What is the BEST next step?', 5, 'medium', 'single', 1, 'Awareness programs aim to change behavior. Targeted training plus ongoing measurement shows whether click rates improve over time.', 'Awareness failures are fixed with training and metrics, not punishment.', 'Teach, test, track.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('48a6be0f-aefd-5f5e-b236-f0e2bb5b0e27', '1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 0, 'Terminate the employees who clicked', false, 'Punitive responses discourage reporting and do not build skills.'),
  ('893e23d5-58d7-5394-a51e-17877ae3a5b1', '1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 1, 'Provide targeted training to those who clicked and measure improvement in future simulations', true, null),
  ('c09c4c4c-f7db-56e1-a641-637b7a35f7c8', '1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 2, 'Stop running phishing simulations because they harm morale', false, 'Stopping simulations removes a key measurement and training tool.'),
  ('bf742190-c05e-530b-9c88-d8995fb586c8', '1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 3, 'Block all links in every incoming email permanently', false, 'Blocking all links is impractical and ignores the human-behavior goal.')
insert into public.question_topics (question_id, topic_id) values ('1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 'security-awareness'), ('1584b2a3-3473-56c1-a7ec-9dd211fb79a6', 'social-engineering') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 'An organization continuously monitors, maintains, and updates its security controls after implementing them. Which concept does this ongoing effort BEST demonstrate?', 5, 'hard', 'single', 1, 'Due care means acting responsibly by maintaining and operating reasonable protections. Due diligence is the investigation and research done to understand risks before acting.', 'Researching and assessing = due diligence. Doing and maintaining = due care.', 'Diligence investigates; care maintains.', true, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('8deb9a67-3c3a-5515-88b4-58baeb679331', 'eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 0, 'Due care', true, null),
  ('a3f942ea-5a2f-56dd-a097-9ad569386653', 'eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 1, 'Due diligence', false, 'Due diligence is the assessment and research performed to identify risks and appropriate controls.'),
  ('96e65302-960f-5f87-b0fe-da2dc4380b25', 'eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 2, 'Attestation', false, 'Attestation is a formal statement confirming something, such as compliance.'),
  ('6090969c-08ac-553e-bdf0-3014e559a601', 'eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 3, 'Risk transference', false, 'Transference shifts risk to another party.')
insert into public.question_topics (question_id, topic_id) values ('eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 'compliance'), ('eca127ef-c7a2-592e-b874-e9ea1e89ad8f', 'governance') on conflict do nothing;
insert into public.questions (id, stem, domain_id, difficulty, question_type, correct_count, explanation, exam_clue, memory_tip, is_scenario, status, created_at, updated_at) values ('636b960f-e746-537b-b6d8-7df34eb2e154', 'Which activity is performed during the lessons learned phase of incident response?', 5, 'easy', 'single', 1, 'Lessons learned is a post-incident review that identifies what worked, what did not, and how plans, controls, and training should change.', 'After-action review and process improvement = lessons learned.', 'Learn it so you do not live it twice.', false, 'published', '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.question_choices (id, question_id, position, body, is_correct, explanation) values
  ('704873be-2247-5559-ada8-b063b39d16b3', '636b960f-e746-537b-b6d8-7df34eb2e154', 0, 'Reviewing what happened and updating procedures to improve future response', true, null),
